INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6k7h8', '6k7h8', 'Celso Furtado: reforma, política e ideologia (1950-1964)', NULL, '["Rosa Maria Vieira"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Para a mais recente geração de economistas, Celso Furtado é o intelectual com uma das contribuições mais férteis no plano das formulações teóricas ancoradas na problemática das economias periféricas – a industrialização por substituição de importações como forma de os subdesenvolvidos transitarem ao capitalismo. Muitos acentuam o caráter utópico de suas proposições, por ousarem o projeto de um Brasil de capitalismo autônomo. Há, ainda, os que veem em seu pensamento a matriz de nova epistemologia econômica. Mas inegável é o consenso de que se trata de um intelectual ímpar, construtor de ideias originais, um humanista e homem de ação, devotado aos problemas da América Latina. Este livro traz uma reflexão que inova na abordagem da produção furtadiana. Rosa Maria Vieira, com um texto elegante, optando pela análise dialética da teoria de Furtado e buscando sua imanência histórica, revela um economista que ultrapassou a condição de cepalino keynesiano ao transformar a preocupação com o subdesenvolvimento na procura da particularidade do capitalismo no Brasil, vinculando-se a uma tradição intelectual brasileira comprometida com a modernização do país. O Furtado que Vieira desvela na análise é o humanista, para quem, no Brasil, a questão democrática transcende o jogo político liberal, passando pela equação econômica que erradicasse a miséria estrutural e transformasse a estrutura agrária. Trata-se de um livro indispensável para aqueles que ainda hoje estão empenhados na reflexão e no debate sobre os impasses e desafios da formação social brasileira.', '["Celso Furtado","economic reform","economic policy","economic ideology","import substitution","peripheral economies","underdevelopment","Brazilian capitalism","modernization","agrarian structure","structural poverty","democracy"]', '10.7476/9786589992271', '9786589992271', 'https://books.scielo.org/id/6k7h8', 'https://books.scielo.org/id/6k7h8/pdf/vieira-9786589992271.pdf', NULL, 'https://books.scielo.org/id/6k7h8/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6kf82', '6kf82', 'Reforma do judiciário', NULL, '["Maria Tereza Sadek"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Uma análise dos sucessivos relatórios elaborados sobre a PEC 96/92 nos permitiu identificar três dimensões principais da reforma judiciária. Há, em primeiro lugar, o problema da jurisdição política constitucional[...]. A segunda dimensão da reforma trata da existência e efetividade de mecanismos de controle e fiscalização dos órgãos do sistema de justiça [...]. Por fim, a terceira dimensão contempla os aspectos organizacionais e estruturais segundo sua capacidade de ampliar ou reduzir o acesso à Justiça e a democratização do Judiciário.', '["judicial reform","political jurisdiction","constitutional jurisdiction","access to justice","democratization of the judiciary","Brazilian judiciary"]', '10.7476/9788579820335', '9788579820335', 'https://books.scielo.org/id/6kf82', 'https://books.scielo.org/id/6kf82/pdf/sadek-9788579820335.pdf', NULL, 'https://books.scielo.org/id/6kf82/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6ktrn', '6ktrn', 'Desastres: velhos e novos desafios para a saúde coletiva', NULL, '["Vânia Rocha","Luciana R. Londe"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-06-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Secas, inundações, escorregamento de terras, derramamento de óleo, rompimento de barragens e pandemia de Covid-19. Tudo isso faz parte de um conjunto de desastres - causados pelos mais diversos fatores - enfrentados pela população brasileira. O livro da coleção Temas em Saúde amplia os debates sobre essas ocorrências, abordando os desastres que fazem parte da rotina de diversas regiões do país já há bastante tempo, assim como eventos mais recentes, como é o caso da emergência sanitária causada pelo novo coronavírus. Na obra, as biólogas Luciana Londe e Vânia Rocha transitam por interações entre desastres e saúde, apresentam e classificam ameaças naturais e ameaças tecnológicas e discorrem sobre os desafios da saúde coletiva diante desses cenários.', '["natural disasters","technological disasters","collective health","drought","floods","landslides","oil spills","dam failure","COVID-19 pandemic","health emergencies","disaster health","Brazil"]', '10.7476/9786557081051', '9786557080344', 'https://books.scielo.org/id/6ktrn', NULL, NULL, 'https://books.scielo.org/id/6ktrn/cover/cover_thumbnail.jpeg', 138, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6m9xq', '6m9xq', 'A primazia do corpo próprio: posição e crítica da função simbólica nos primeiros trabalhos de Merleau-Ponty', NULL, '["Danilo Saretta Veríssimo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O estudo propõe um exame da função simbólica nos primeiros trabalhos do filósofo francês Maurice Merleau-Ponty (1908-61), tentando abordar, mais especificamente, o papel dela no livro “A estrutura do comportamento”, publicado em 1942, e na sua retomada crítica dentro da “Fenomenologia da Percepção”, de 1945. Segundo o autor, o tema, pouco explicitado pelo próprio filósofo, também é objeto de raros debates entre seus comentadores, embora a sua importância na obra de Merleau-Ponty seja inegável. No primeiro trabalho, Merleau-Ponty, utilizando-se das categorias simbólicas emprestadas da neuropsisquiatria do começo do século XX, caracteriza a corporalidade humana como a capacidade de ultrapassar o caráter imediato das situações vividas. A própria atividade humana, assim, redimensionaria a existência concreta que se denota também, por exemplo, no comportamento animal. Já na “Fenomenologia da percepção”, em que o filósofo trata da espacialidade, da motricidade e da expressividade do corpo próprio, Merleau-Ponty prescinde das explicações calcadas na função simbólica, doravante associadas à análises de cunho intelectualista, embora continue a combater o que considera representar uma autonomia crescente da idealização simbólica na dinâmica entre conteúdo e forma.', '["Merleau-Ponty","symbolic function","The Structure of Behavior","phenomenology of perception","own body","embodiment","human behavior","animal behavior","spatiality","expressivity","form and content","intellectualism"]', '10.7476/9786557144923', '9786557144923', 'https://books.scielo.org/id/6m9xq', 'https://books.scielo.org/id/6m9xq/pdf/verissimo-9786557144923.pdf', NULL, 'https://books.scielo.org/id/6m9xq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6mdz8', '6mdz8', 'Múltiplos olhares para as relações raciais na educação', NULL, '["Silva, Maria da Anunciação Conceição","Jardim, Fabiana A. A.","Oliveira, Rosenilton Silva de"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A coletânea reúne artigos de pesquisadores e pesquisadoras de diferentes estados do Brasil com lentes aguçadas para dialogar, a partir das suas áreas de conhecimento, sobre o racismo e as múltiplas facetas que envolvem educação, formação docente, religião, gênero, psicologia e uma análise teórica sobre afrografias com base em produções artísticas e literárias baianas.', '["racism in education","race relations","teacher professional development","religion","gender","Afro-Brazilian literature","Afro-Brazilian art","Bahia","race and education"]', '10.7476/9788585813376', '9786588211717', 'https://books.scielo.org/id/6mdz8', 'https://books.scielo.org/id/6mdz8/pdf/silva-9788585813376.pdf', 'https://books.scielo.org/id/6mdz8/epub/silva-9788585813376.epub', 'https://books.scielo.org/id/6mdz8/cover/cover_thumbnail.jpeg', 302, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6p3mz', '6p3mz', 'Territórios da Bahia: regionalização, cultura e identidade', NULL, '["Ângelo Serpa"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A partir de uma análise sobre as relações existentes entre cultura e poder, o livro investiga a articulação e a implementação de políticas de desenvolvimento territorial e cultural implantadas a partir de 2007 no estado da Bahia. A partir disso, faz-se a problematização das noções de cidadania, cultura, identidade e política. Portanto, Territórios da Bahia é o imbricamento entre a dimensão territorial e a consolidação de processos políticos que valorizem o exercício da cidadania.', '["territorial development policy","cultural policy","culture and power","regionalization","cultural identity","citizenship","political identity","Bahia","territoriality"]', '10.7476/9788523220129', '9788523220129', 'https://books.scielo.org/id/6p3mz', 'https://books.scielo.org/id/6p3mz/pdf/serpa-9788523220129.pdf', NULL, 'https://books.scielo.org/id/6p3mz/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6p4jp', '6p4jp', 'Dos micróbios aos mosquitos: febre amarela e a revolução pasteuriana no Brasil', NULL, '["Jaime Larry Benchimol"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Consistente contribuição à história social da ciência e da medicina no Brasil, que articula recentes avanços da história, filosofia e antropologia da ciência. Analisa, sem anacronismos, a trajetória que Domingos Freire descreveu no efervescente mundo das ciências biomédicas de finais do século XIX, desnudando a complexa rede que começava então a unir os médicos cientistas. Enfim, uma obra com o mérito de mostrar que, na ''corrida'' por compreender a febre amarela e finalmente anular os seus efeitos, o passo dos que ''perderam'' também bateu o chão sobre o qual se ergueria o pódio para os ''vencedores''.', '["yellow fever","Louis Pasteur","history of medicine","social history of science","microbiology","mosquitoes","scientific networks","Brazil"]', '10.7476/9788575413166', '9788575413166', 'https://books.scielo.org/id/6p4jp', 'https://books.scielo.org/id/6p4jp/pdf/benchimol-9788575413166.pdf', NULL, 'https://books.scielo.org/id/6p4jp/cover/cover_thumbnail.jpeg', NULL, 129, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6pdyn', '6pdyn', 'Tecnologias digitais na educação', NULL, '["Robson Pequeno de Sousa"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Tecnologias Digitais na Educação apresenta uma seleção de artigos que são resultado das monografias da primeira turma do curso de Especialização em Novas Tecnologias na Educação.', '["digital technologies in education","educational technology"]', '10.7476/9788578791247', '9788578791247', 'https://books.scielo.org/id/6pdyn', 'https://books.scielo.org/id/6pdyn/pdf/sousa-9788578791247.pdf', NULL, 'https://books.scielo.org/id/6pdyn/cover/cover_thumbnail.jpeg', NULL, 52, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6q', '6q', 'As donas do canto: o sucesso das estrelas-intérpretes no carnaval de Salvador', NULL, '["Marilda Santana"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Daniela Mercury, Margareth Menezes e Ivete Sangalo. A publicação é fruto de uma tese de doutorado e analisa a trajetória de cada uma dessas cantoras. O objetivo é identificar elementos constitutivos do êxito na carreira de cada uma delas e da capacidade de cada uma enquanto autoras e gestoras de suas carreiras.', '["samba","women singers","career success","career management","singer-songwriters","Brazilian popular music"]', '10.7476/9788523208851', '9788523208851', 'https://books.scielo.org/id/6q', 'https://books.scielo.org/id/6q/pdf/santanna-9788523208851.pdf', NULL, 'https://books.scielo.org/id/6q/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6qjv9', '6qjv9', 'A filosofia natural de Benjamin Franklin: traduções de cartas e ensaios sobre a eletricidade e a luz', NULL, '["Breno Arsioli Moura"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Benjamin Franklin (1706-1790) é um dos mais conhecidos personagens da história da ciência. Embora seja famoso por conta do experimento da pipa em meio a uma tempestade – uma anedota bastante controversa, aliás –, Franklin foi um pensador muito mais abrangente. Suas ideias acerca dos fenômenos elétricos buscaram responder às principais lacunas da eletricidade no século XVIII, cobrindo desde a eletrização dos corpos até a formação de grandes temporais com raios e trovões. Franklin abordou também outras questões em seus textos sobre o mundo natural, incluindo a natureza e comportamento da luz. Neste livro, apresento traduções de seis cartas escritas por ele entre 1747 e 1752 – período em que foi mais ativo na filosofia natural – e de um pequeno ensaio sobre a luz, publicado no final da vida, em 1788. A partir disso, o leitor terá acesso direto ao pensamento de Franklin, aos termos que utilizou e às suas explicações para os mais diversos fenômenos da eletricidade e da luz. Esta é a primeira vez que textos de Franklin são traduzidos integralmente para o português brasileiro. Espero que a leitura seja produtiva e que a filosofia natural de Franklin possa ser conhecida em toda sua dimensão e importância.', '["Benjamin Franklin","natural philosophy","electricity","light","history of science","18th century","Brazilian Portuguese translation","lightning","thunderstorms","electrification"]', '10.7476/9786589992288', '9786589992288', 'https://books.scielo.org/id/6qjv9', 'https://books.scielo.org/id/6qjv9/pdf/moura-9786589992288.pdf', NULL, 'https://books.scielo.org/id/6qjv9/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6qxg8', '6qxg8', 'Ações afirmativas na educação superior: a experiência da Universidade Federal da Fronteira Sul', NULL, '["Rosileia Lúcia Nierotka","Joviles Vitório Trevisol"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro apresenta os resultados de uma pesquisa que teve o objetivo de investigar as políticas de acesso e as ações afirmativas implementadas pela UFFS, com o propósito de compreender como tais políticas contribuem para o processo de democratização da educação superior pública brasileira. Ao tomar a UFFS como objeto de estudo, foi possível considerar que as suas políticas de acesso e ações afirmativas contribuem para a democratização da educação superior pública brasileira. No entanto, é necessário considerar que se trata de uma instituição ainda muito jovem. Ainda há muitos desafios e questionamentos para que, de fato, possa se consolidar como uma universidade inclusiva, com uma educação pública e de qualidade. Mesmo sendo jovem, os resultados demonstraram que a UFFS, desde sua criação, priorizou a escola pública em suas políticas de acesso.', '["affirmative action","democratization of higher education","public universities","Universidade Federal da Fronteira Sul","inclusive education","public schools","university inclusion"]', '10.7476/9786550190071', '9786550190071', 'https://books.scielo.org/id/6qxg8', 'https://books.scielo.org/id/6qxg8/pdf/nierotka-9786550190071.pdf', NULL, 'https://books.scielo.org/id/6qxg8/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6r5h6', '6r5h6', 'Lygia Fagundes Telles e René Magritte: diálogos entre textos e telas', NULL, '["Ana P. Rodrigues"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Ana Paula Dias Rodrigues propõe o diálogo entre três pares de contos de Lygia Fagundes Telles e telas de René Magritte, analisando os aspectos intrínsecos das obra. Essas análises destacam fatores ligados ao funcionamento de cada sistema, e o exercício intersemiótico ilumina as questões ligadas ao funcionamento das respectivas linguagens. Dessa maneira, o livro apresenta uma perspectiva nova de se ler Lygia Fagundes Telles, tendo como elemento condutor a implicação metalinguística da consciência artística, o que possibilita a sua aproximação com o pintor belga. Assim, contos da escritora são projetados em telas de Magritte e por elas iluminados, da mesma maneira que telas do pintor refletem os mistérios dos textos da escritora brasileira. O resultado são análises originais e instigantes, que revelam a consciência crítica e a sensibilidade perceptiva da autora.', '["Lygia Fagundes Telles","René Magritte","short stories","intersemiotic dialogue","text and image","metalinguistic awareness","artistic consciousness","Brazilian literature","Belgian painting","literary and visual art"]', '10.7476/9786557145036', '9786557145036', 'https://books.scielo.org/id/6r5h6', 'https://books.scielo.org/id/6r5h6/pdf/rodrigues-9786557145036.pdf', NULL, 'https://books.scielo.org/id/6r5h6/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6r89g', '6r89g', 'O espírito das relações internacionais', NULL, '["Amado Luiz Cervo"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2022, '2022-06-09', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Análise e interpretação de 11 comandos que conduzem e explicam o movimento dos agentes das relações internacionais pelo mundo – Estados, nações e agentes privados, sobretudo empresas, capitais e tecnologias –, este livro responde à pergunta essencial acerca do movimento das relações internacionais: quais são os impulsos de origem e como condicionam políticas, estratégias e resultados alcançados pelos agentes, por um lado, e, por outro, como esses mesmos agentes são condicionados? Ou seja: quais são os comandos superiores das relações internacionais? É um livro didático, útil para pesquisadores e estudantes da área de relações internacionais, teoria e história, e tem por objetivo a compreensão das relações internacionais no médio e no longo prazo.', '["international relations theory","international relations history","state","nation","corporations","capital","technology","international policy","international strategy"]', '10.7476/9786558461616', '9786558461425', 'https://books.scielo.org/id/6r89g', NULL, NULL, 'https://books.scielo.org/id/6r89g/cover/cover_thumbnail.jpeg', 156, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6s23h', '6s23h', 'Psicologia e literatura', NULL, '["Rui Moreira Leite","Dante Moreira Leite"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'É bem conhecida a afirmação de Dostoiévski sobre os poderes relativos da literatura e da psicologia. Para ele, um psicólogo jamais alcançaria a eficácia do escritor: é na literatura que encontramos um retrato acurado da mente. Mas mesmo para aqueles que reivindicam superioridade para um desses dois pólos uma coisa é certa: psicologia e literatura partilham uma ampla fronteira e guardam inter-relações significativas Essa convivência ao mesmo tempo conflituosa e complementar é estudada por Dante Moreira Leite em vários de seus ângulos. Neste conhecido e influente ensaio, ênfase particular é dada à questão da criatividade, à avaliação de vertentes psicologistas (junguiana, psicanalítica etc.) da análise literária e aos processos psicológicos associados à leitura e ao autor.', '["psychology and literature","Fyodor Dostoevsky","creativity","literary analysis","Jungian psychology","psychoanalytic literary criticism","reading process","authorship"]', '10.7476/9788539303380', '9788571394322', 'https://books.scielo.org/id/6s23h', NULL, NULL, 'https://books.scielo.org/id/6s23h/cover/cover_thumbnail.jpeg', 380, 73, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6s555', '6s555', 'Cultura, democracia e ética: reflexões comportamentalistas', NULL, '["Carolina Laurenti","Carlos Eduardo Lopes"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este livro apresenta discussões sobre a cultura em uma perspectiva analítica- comportamental. Mais do que isso, é uma obra que tenta enfrentar as críticas sociais dirigidas ao comportamentalismo desde suas origens, a saber, que se trataria de uma filosofia que subsidiaria uma proposta psicológica norteada pela ideologia do controle social, estando o serviço de elite, filiando-se, necessariamente a uma política de direita. As respostas a essas críticas são buscadas tanto nos textos de Skinner, quanto de outros autoras que tentam dar continuidade ao comportamentalismo na atualizada.', '["behaviorism","culture","democracy","ethics","social control","B. F. Skinner","critique of behaviorism","right-wing ideology"]', '10.7476/9788576286929', '9788576286318', 'https://books.scielo.org/id/6s555', NULL, NULL, 'https://books.scielo.org/id/6s555/cover/cover_thumbnail.jpeg', 138, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6sc7t', '6sc7t', 'Origens e evolução das idéias da física', NULL, '["José Fernando Moura Rocha"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Numa linguagem simples, as origens e evolução das idéias da Física são apresentadas, partindo-se das noções iniciais introduzidas pelos filósofos gregos, até as concepções atuais da Teoria da Relatividade e da Física Quântica.', '["history of physics","ancient Greek philosophy","relativity","quantum physics","philosophy of physics"]', '10.7476/9788523208783', '9788523202545', 'https://books.scielo.org/id/6sc7t', NULL, NULL, 'https://books.scielo.org/id/6sc7t/cover/cover_thumbnail.jpeg', 372, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6sfk9', '6sfk9', 'Os sentidos da casa própria: condomínios horizontais populares fechados e novas práticas espaciais em Presidente Prudente e São Carlos', NULL, '["Viviane Fernanda de Oliveira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A expansão urbana experimentada pelas cidades brasileiras vem ocorrendo em descontinuidade, com a implantação de espaços residenciais fechados de alto padrão em áreas distantes da malha urbana compactada, mas também de condomínios horizontais populares fechados, aos quais voltamos nossa atenção nessa dissertação, que procura compreender como essas novas formas de morar são influenciadas e influenciam a produção do espaço urbano de cidades médias, como Presidente Prudente e São Carlos. A perspectiva metodológica adotada é a do cotidiano dos seus moradores, em sua relação com os espaços urbanos, e as práticas dos moradores de um espaço residencial popular aberto em cada uma dessas cidades também foram analisadas, como forma de identificar contrapontos e semelhanças. Com as entrevistas, constatamos que a opção pela tipologia fechada, pelos agentes imobiliários, visa reverter desvantagens locacionais e superexplorar espaços internos, enquanto que, para os moradores, ela é estratégica na evitação dos estigmas próprios das periferias nas quais estão localizados os condomínios pesquisados. Embora convivam com processos que não são novos de produção desses espaços periféricos, as novas barreiras (físicas e simbólicas) contribuem para que novos sentidos da casa própria sejam difundidos, ao mesmo tempo em que acentuam a tendência à privatização, em curso nessas cidades.', '["urban periphery","housing production","everyday life","spatial practices","urban expansion","real estate agents","stigma","privatization","Presidente Prudente","São Carlos, São Paulo","medium-sized cities"]', '10.7476/9788579837098', '9788579837098', 'https://books.scielo.org/id/6sfk9', 'https://books.scielo.org/id/6sfk9/pdf/oliveira-9788579837098.pdf', NULL, 'https://books.scielo.org/id/6sfk9/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6snt6', '6snt6', 'Crimes em comum: escravidão e liberdade sob a pena do Estado imperial brasileiro (1830-1888)', NULL, '["Ricardo Alexandre Ferreira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Nesta pesquisa realizada por Ricardo Alexandre Ferreira são investigadas as histórias do crime e do direito, focando, mais especificamente, no período da escravidão no Brasil. Aqui, através de uma vasta pesquisa documental, o autor analisa como o escravismo aparece referenciado no código penal do Império e as diferenças de punição entre homens livres e cativos. A grande importância deste estudo se encontra na revelação deste aspecto da vida jurídica do Brasil imperial. Por meio de processos e penas redigidas na época, e de relatórios feitos pelas autoridades reportando sua preocupação com a segurança pública, Ricardo Alexandre Ferreira leva o leitor a descobrir as implicâncias sociais e judiciais da separação entre escravos e homens livres.', '["slavery","criminal law","Brazilian Empire","criminal code","slave punishment","slavery and freedom","public security","legal history","criminal justice","19th-century Brazil"]', '10.7476/9786557145203', '9786557145203', 'https://books.scielo.org/id/6snt6', 'https://books.scielo.org/id/6snt6/pdf/ferreira-9786557145203.pdf', NULL, 'https://books.scielo.org/id/6snt6/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6t3hs', '6t3hs', 'A dinâmica do sistema produtivo da saúde: inovação e complexo econômico-industrial', NULL, '["Carlos Augusto Grabois Gadelha"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Esta publicação integra o projeto Perspectivas de Investimento no Brasil, desenvolvido em 2008 e 2009 pelos institutos de Economia da Universidade Federal do Rio de Janeiro (UFRJ) e da Universidade Estadual de Campinas (Unicamp) em parceria com o Banco Nacional de Desenvolvimento Econômico e Social (BNDES). Para o desenvolvimento da análise referente ao Complexo Econômico-Industrial da Saúde (CEIS), os coordenadores do projeto se associaram a pesquisadores do Grupo de Inovação em Saúde da Escola Nacional de Saúde Pública Sérgio Arouca da Fundação Oswaldo Cruz (GIS/Ensp/Fiocruz), coordenado por Carlos Gadelha. O resultado dessa iniciativa pode ser visto neste livro, que apresenta uma versão revista e atualizada de relatório do GIS/Ensp/Fiocruz, no âmbito do referido projeto; Bibliografia: p. 209-221; Documento online disponível em: http://books.scielo.org/id/6t3hs/pdf/gadelha-9788575415931.pdf; Todo o conteúdo deste trabalho, exceto quando houver ressalva, é publicado sob a licença Creative Commons Atribuição 4.0, que dá o direito de: Compartilhar — copiar e redistribuir o material em qualquer suporte ou formato; Adaptar — remixar, transformar, e criar a partir do material para qualquer fim, mesmo que comercial. Esta licença é aceitável para Trabalhos Culturais Livres. O licenciante não pode revogar estes direitos desde que se respeite os termos da licença.De acordo com os termos seguintes: Atribuição — Deve-se dar o crédito apropriado, prover um link para a licença e indicar se mudanças foram feitas. Você deve fazê-lo em qualquer circunstância razoável, mas de nenhuma maneira que sugira que o licenciante apoia você ou o seu uso. Sem restrições adicionais — Você não pode aplicar termos jurídicos ou medidas de caráter tecnológico que restrinjam legalmente outros de fazerem algo que a licença permita.', '["healthcare innovation","health economic-industrial complex","health investment","health technology innovation"]', '10.7476/9788575415931', '9788575415931', 'https://books.scielo.org/id/6t3hs', 'https://books.scielo.org/id/6t3hs/pdf/gadelha-9788575415931.pdf', NULL, 'https://books.scielo.org/id/6t3hs/cover/cover_thumbnail.jpeg', NULL, 39, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6tdtg', '6tdtg', 'Gênero, direito e relações internacionais: debates de um campo em construção', NULL, '["Denise Vitale","Renata Nagamine"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'APRESENtAÇÃoGênero, direitos e relações internacionais O feminismo, como objeto de ação social e pensamento, remonta ao século XVIII e, como debate acadêmico, aos anos 1920.É na década de 1920 que se forma o que chamamos de primeira onda feminista, ligada a demandas pelo direito das mulheres ao sufrágio.Embora outras ondas feministas tenham se seguido a essa, o feminismo se constituiu como tema de interesse global apenas na segunda metade dos anos 1990, para o que teriam concorrido processos internos aos Estados, a abertura do internacional a temas normativos com o fim da Guerra Fria e, mais especificamente, a Conferência das Nações Unidas sobre Mulheres, conhecida como Conferência de Pequim, em 1995.É nessa conferência que se dá o deslocamento da categoria "mulheres" por "gênero" e a adoção de uma abordagem particular dele, a mainstreaming ou da transversalidade.Essa abordagem implicaria considerar o gênero, ao lado do desenvolvimento e do meio ambiente, uma dimensão que atravessa toda a agenda global, a ser contemplada, por isso, em deliberações e ações de órgãos, agências, programas e fundos das organizações internacionais.Sobretudo dos anos 2000, em diante, as questões relacionadas com o gênero ganharam, assim, maior densidade e destaque nas relações internacionais.Organizações internacionais como a Organização dos Estados Americanos (OEA), o Conselho da Europa, a União Europeia (UE) e a própria Organização das Nações Unidas (ONU) passaram a se engajar politicamente na promoção da agenda dos direitos das mulheres e da agenda LGBTI, atuando em parceria com Organizações Não Governamentais (ONG), redes de ativismo e Estados.Migrações, em especial de mulheres refugiadas, e a perseguição de pessoas LGBTI por sua orientação sexual e 8 Gênero, direito e relações internacionais identidade de gênero, o estupro como arma em conflitos armados, a violência cotidiana contra a mulher, os seus direitos reprodutivos, a igualdade entre homens e mulheres, a autonomia das mulheres, as interseccionalidades que se conjugam em um ponto de vista único, a responsabilidade do Estado em matéria de direitos relacionados com o gênero são alguns temas tocantes às relações entre corpos femininos e corpos masculinos postos em questão no período.Os anos 2000 e seguintes são, portanto, um período de grandes transformações nas relações sociais, as quais têm merecido a atenção da academia, inclusive a brasileira.Na esfera internacional, as questões de gênero têm suscitado um debate profícuo e uma importante produção acadêmica nas Ciências Sociais em sentido amplo há algumas décadas.Dois marcos na história dessa literatura são a publicação de The Boundaries of International Law: A Feminist Analysis, de Hilary Charlesworth e Christine Chinkin, em 2000, e de Gendering World Politics, de J. A. Tickner, em 2001.Passadas quase duas décadas de suas publicações, esses dois estudos seguem como referência para a pesquisa acadêmica, por sua qualidade, mas também pela surpreendente escassez de material sobre o assunto nos campos do Direito e nas Relações Internacionais durante um longo período de tempo, até começar a ser suprida mais recentemente.Essa escassez é particularmente impressionante no Brasil, onde a discriminação e a violência contra a mulher são práticas comuns e só começaram a ser estudadas de maneira mais consistente, nas universidades brasileiras, nos anos 2000.É nesse período, e em sinergia com sua saliência nas relações internacionais, que o gênero emerge como um objeto de debate acadêmico e interesse fora dos muros da academia brasileira, a suscitar uma precipitação de discursos nas relações sociais.No que se refere ao debate acadêmico, ele ainda nos parece ser incipiente por um lado e, por outro, altamente qualificado, o que nos sugere que se trata de uma discussão entre poucas e boas pesquisas.O tema também tem despertado intensa curiosidade intelectual de alunos e alunas.Os capítulos reunidos neste livro pretendem contribuir para o debate sobre o tema e fomentar o campo de estudos de gênero na fronteira entre o direito e as relações internacionais.Eles nascem da inquietação Rojava", (Capítulo 11) analisando o feminismo que emergiu com a autodenominada revolução de Rojava, em 2012, na Síria, do ponto de vista de sua concepção teórica e processo político-social.O livro se encerra com a contribuição de Heloisa Pait e Renata Nagamine "Marielle, Presente!Um luto político e uma reconfiguração da política nacional -a necessária articulação de um pensamento liberal brasileiro que incorpore demandas sociais e de inclusão" (Capítulo 12), no qual as autoras refletem sobre os desdobramentos sociopolíticos do assassinato da vereadora Marielle Franco, em março de 2018, com um olho no Brasil e outro para as relações entre o luto e a luta no Brasil com processos globais.Distintos em forma e conteúdo, o conjunto de capítulos que apresentamos refletem pesquisas em estágios diferentes: algumas mais avançadas e maduras, outras mais exploratórias e de caráter mais ensaístico.Com todas as suas particularidades, eles compartilham da pretensão que motivou a publicação deste livro, que é colocar em circulação opiniões plurais acerca dos limites e das possibilidades dos direitos e ideias quando se trata de debater gênero na interface entre direito e relações internacionais.Esperamos que as ideias aqui reunidas incentivem novas reflexões e aprofundem o campo de estudos sobre o tema no Brasil.', '["gender","international relations","feminism","women''s rights","mainstreaming","transversality","United Nations","LGBT rights","refugee women","sexual violence in armed conflict","violence against women","gender mainstreaming"]', '10.7476/9788523218638', '9788523218638', 'https://books.scielo.org/id/6tdtg', 'https://books.scielo.org/id/6tdtg/pdf/vitale-9788523218638.pdf', NULL, 'https://books.scielo.org/id/6tdtg/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6tfv6', '6tfv6', 'El Partido Revolucionario Cubano de José Martí: concepción ético-política original', NULL, '["Marcos de Souza Queiroz","Maria Angélica Puntel"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1997, '1997-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Esta obra es el resultado de una cuidadosa selección, organización y traducción de documentos, comunicaciones, artículos de periódicos y cartas de José Martí sobre el Partido Revolucionario Cubano (PRC), publicados en diferentes tomos de sus Obras completas. Está ordenada temáticamente buscando ofrecer al lector las líneas más generales del pensamiento y de la actividad martianas en el Partido fundado por él para organizar la guerra de independencia y crear las condiciones para una real descolonización de la república a ser creada. Se consideró importante mostrar la originalidad de esa institución política, observable en su estructura, sus estatutos, sus principios ideológicos, su postura ética, en las formas de financiamiento y, sobre todo, en la amplia y profunda democracia presente en las prácticas cotidianas dentro del Partido. Ocho capítulos reúnen los textos en grandes áreas para presentar una visión general de los intereses del PRC y la actividad de Martí. Sus títulos son: “Documentos programáticos del PRC”, “Política e ideología”, “La política y la ética en la política”, “Financiamiento y recaudación de fondos”, “Contra el autonomismo y el anexionismo”, “La unidad de diferentes clases y sectores sociales”, “Convivencia, fraternidad y honradez” y “El PRC en la guerra”.', '["leprosy","leprosy stigma","patient representation","healthcare workers","denial of illness","depression","public health practice","social representations of disease","history of leprosy","José Martí","Cuban independence wars","political ethics","party ideology","party constitution","party funding"]', '10.7476/9788575412596', '9788575412596', 'https://books.scielo.org/id/6tfv6', 'https://books.scielo.org/id/6tfv6/pdf/queiroz-9788575412596.pdf', NULL, 'https://books.scielo.org/id/6tfv6/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6tkwh', '6tkwh', 'Midiartivismo: sobre usos e abusos da arte e mídia ativistas', 'sobre usos e abusos da arte e mídia ativistas', '["Freitas, Ricardo Oliveira de"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro reúne textos de pesquisadores vinculados às mais diversas áreas de conhecimento e atuação, que analisam práticas e iniciativas que tentam contribuir para a transformação de realidades excludentes, reservadas a grupos e comunidades historicamente subalternizadas no Brasil, que fazem uso de expressões em artes e recursos de mídia, a fim de tornar públicas suas causas, seus problemas, suas prioridades, seus desejos, promovendo, desse modo, um tipo de ativismo social.', '["activist art","activist media","social activism","subaltern groups","marginalized communities","art and media","social change"]', '10.7476/9788574556307', '9788574556062', 'https://books.scielo.org/id/6tkwh', NULL, NULL, 'https://books.scielo.org/id/6tkwh/cover/cover_thumbnail.jpeg', 271, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6tmww', '6tmww', 'Patentes Pesquisa &amp;amp Desenvolvimento um manual de propriedade intelectual', NULL, '["Maria Fernanda Gonçalves Macedo","A. L. Figueira Barbosa"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Em um país de industrialização recente, como é o caso do Brasil, há ainda um conhecimento limitado sobre o papel e as funções dos sistemas de propriedade intelectual, em especial as patentes de invenção da propriedade industrial. Escrito por especialistas, este manual se propõe a divulgar o potencial do sistema de proteção e informação do conhecimento técnico para o alcance dos objetivos do projeto de pesquisa e desenvolvimento. Esclarecedor, fornece subsídios essenciais para pesquisadores e todos os envolvidos, ou para aqueles que simplesmente desejem obter ampla gama de informações e orientações acerca de tão relevante assunto. Este livro de orientação e informação foi elaborado para a comunidade técnico-científica da FIOCRUZ, sem que tal especificidade haja sido capaz de anular a sua utilidade para pesquisadores e gestores tecnológicos de outras instituições, incluindo os peritos localizados nos departamentos de pesquisa de empresas. Basicamente, o texto informa sobre as noções básicas de como as invenções podem ser protegidas por meio das patentes de invenção (e modelo de utilidade) - os requisitos e os procedimentos para a obtenção desses privilégios -, esclarece o valor das informações tecnológicas contidas nos documentos de patente e os princípios para a recuperação dessas informações para apoiar os projetos de pesquisa e desenvolvimento, e, ainda, discute de maneira sucinta as bases para a negociação e transferência de tecnologia, incluindo a recente problemática da transferência de material biológico. Além disso, o texto está atualizado perante os recentes tratados multilaterais e o novo Código da Propriedade Industrial, a Lei nº 9.279, vigente a partir de maio de 1997, fazendo-se, quando necessário, referência a leis anteriores e não mais em vigor.', '["patents","industrial property","research and development","intellectual property","patent system","patent information","Brazil"]', '10.7476/9788575412725', '9788575412725', 'https://books.scielo.org/id/6tmww', 'https://books.scielo.org/id/6tmww/pdf/macedo-9788575412725.pdf', NULL, 'https://books.scielo.org/id/6tmww/cover/cover_thumbnail.jpeg', NULL, 38, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6vkk8', '6vkk8', 'Tradução &amp;: perspectivas teóricas e práticas', NULL, '["Lauro Maia Amorim","Cristina Carneiro Rodrigues","Érika Nogueira de Andrade Stupiello"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"O oportuno título desta obra representa com perfeição o que ela tem de peculiar: a análise da teoria e da prática da tradução associada a outros tópicos e campos de conhecimento, como a adaptação, a psicanálise, o direito, a tradução de poesia no Brasil, a questão de gênero, a crítica, as novas tecnologias.Segundo os organizadores, a intenção deste trabalho “foi trazer alguns tópicos teóricos tanto ao leitor não especializado como àquele que já tem familiaridade com a leitura da literatura sobre tradução, sem ter como objetivo uma aplicação direta de princípios teóricos nem de uma metodologia. Trata-se de um convite a uma refl exão teórica sobre a prática de tradução, a partir dos tópicos selecionados”.Os ensaios do presente livro, escritos por pesquisadores da área ligados a universidades brasileiras que oferecem cursos de tradução em nível de graduação ou pós-graduação, revelam a consolidação dos Estudos da Tradução como disciplina."', '["translation theory","translation practice","adaptation","poetry translation","gender and translation","literary criticism","translation studies as a discipline"]', '10.7476/9788568334614', '9788568334614', 'https://books.scielo.org/id/6vkk8', 'https://books.scielo.org/id/6vkk8/pdf/amorim-9788568334614.pdf', NULL, 'https://books.scielo.org/id/6vkk8/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6wnp4', '6wnp4', 'Ficções contemporâneas: histórias e memórias', NULL, '["Marilene Weinhardt"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Maurício Cesar Menon, em "Por sendas e fendas de Sinhá Braba", ocupa-se do escritor Agripa Vasconcelos (1896 -1969), autor de sete títulos sob a denominação "Sagas do País das Gerais": Fome em Canaã -romance do ciclo dos latifúndios nas Gerais; Sinhá Braba -D.Joaquina do Pompéu -romance do ciclo agropecuário nas Gerais; A Vida em Flor de Dona Beja -romance do ciclo do povoamento nas Gerais; Gongo-Sôco -romance do ciclo do ouro nas Gerais; Chica que Manda -Chica da Silva -romance do ciclo dos diamantes nas Gerais; Chico Rei -romance do ciclo da escravidão nas Gerais; Ouro Verde e Gado Negro -romance dos ciclos do café e da abolição do cativeiro nas Gerais.A análise evidencia, para além do aspecto temático e histórico de Sinhá Braba, os recursos expressivos, narrativos e linguísticos utilizados na composição desse romance histórico.Em "Paródia e condição nacional: estudo sobre a ficção histórica de Ana Miranda", Eunice de Morais analisa os romances Boca do inferno, A última quimera e Dias e dias como construções paródicas.A perspectiva é que a apropriação textual realizada nos romances tanto homenageia quanto discute e questiona discursos de nação, ou a sua ausência, que serviram a projetos literários do passado.Esses discursos revelam o Brasil barroco, romântico e modernista como "comunidades imaginadas", de modo que a condição nacional do passado constitua uma face paralela e integrante da condição nacional do presente.A abordagem visa demonstrar que nos romances em estudo há, através da revisitação da memória e do momento literário de cada poeta, uma busca pela representação que proporcione ou sugira a discussão a respeito da condição nacional (política, cultural e literária), confrontando o passado com o presente e vice-versa.Naira de Almeida Nascimento propõe a leitura dos romances Heranças (2008) e Mil rosas roubadas (2014), em "A vida como literatura e a literatura para viver: apontamentos sobre a ficção de Silviano Santiago", levando em consideração a preocupação que o autor sempre devotou à literatura brasileira e ao seu diálogo no concerto das nações.Os preceitos da crítica cultural manifestos pelo ensaísta Silviano estão presentes no discurso do ficcionista.', '["historical fiction","parody","national conditions","nationhood","memory","Brazilian national identity","textual appropriation","imagined community"]', '10.7476/9788577982141', '9788577982141', 'https://books.scielo.org/id/6wnp4', 'https://books.scielo.org/id/6wnp4/pdf/weinhardt-9788577982141.pdf', NULL, 'https://books.scielo.org/id/6wnp4/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6xj59', '6xj59', 'Dicionário crítico de migrações internacionais', NULL, '["Leonardo C. Cavalcanti","Tuíla Botega","Tânia Tonhati","Dina Araújo"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As migrações internacionais vêm alcançando dimensões peculiares nos atuais tempos de globalização dos mercados e de inovações nas tecnologias da informação, comunicação e transportes. Acadêmicos da temática chegam a sugerir que vivemos na era das migrações, que seriam sintetizadas em cinco características fundamentais: globalização, aceleração, diferenciação, feminização e crescente politização das migrações. As migrações internacionais atravessam um momento de grande intensidade e sem precedentes na história recente. Isso se reflete no aumento dos migrantes e refugiados ao redor do mundo, nas dissonâncias das diferentes políticas migratórias e na intensidade dos debates teóricos e metodológicos. Cada vez mais complexas, as migrações contemporâneas são difíceis de ser contabilizadas, são resistentes a marcos teóricos únicos ou disciplinares e apresentam características multifacetadas, complexas e materializadas em diferentes escalas. Nesse contexto, o Dicionário crítico de migrações internacionais apresenta conceitos derivados dos debates teóricos sobre as migrações internacionais e também de áreas afins que são apropriados pelos estudos migratórios. Essa mescla, multidisciplinar e ampla, é a tentativa de responder ao desafio de trazer abordagens e conceitos diversos que ofereçam, em alguma medida, elementos que ajudem a compreender o fenômeno migratório na atualidade e as diferentes formas de mobilidade.', '["international migration","migration theory","globalization","acceleration","differentiation","feminization of migration","politicization of migration","refugees","migration policy","mobility","critical concepts"]', '10.7476/9788523013400', '9788523012113', 'https://books.scielo.org/id/6xj59', NULL, NULL, 'https://books.scielo.org/id/6xj59/cover/cover_thumbnail.jpeg', 740, 18, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6y9nc', '6y9nc', 'O novo mapa da indústria no início do século XXI: diferentes paradigmas para leitura das dinâmicas territoriais do Estado de São Paulo', NULL, '["Eliseu Savério Spósito"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'mostram as fontes oficiais de informação 639 Amanda Mergulhão APRESENTAÇÃO Eliseu Savério Sposito 1Este livro é resultado de um trabalho de cinco anos.Os autores, integrantes de um grupo de pesquisa que se dedicou a fazer uma leitura temática da dinâmica industrial do estado de São Paulo, fizeram suas pesquisas com independência metodológica e teórica.Sempre houve, no entanto, um objetivo comum: tentar desvendar como, por intermédio de várias temáticas, a indústria se apresenta no início do século XXI.Procuramos trabalhar com dois blocos principais.O primeiro trata dos processos e das formas.Neste caso, tivemos abordagens que versam sobre o papel da tecnologia, da reestruturação produtiva, dos condomínios de empresas, o Valor Adicionado Fiscal, considerando processos que regulam a implantação e a disseminação da indústria, como ramos de atividade, com destaque para os de alimentos e de calçados.Do ponto de vista da rede urbana, os arranjos produtivos locais se articulam com a hierarquia urbana, com ênfase também para as cidades pequenas.No segundo bloco da obra, que focaliza os processos e os fluxos, a circulação e os transportes estruturam a formação dos eixos de desenvolvimento.Foram abordados os investimentos na indústria, os transportes aéreos, rodoviários e hidroviários.No final de cada bloco há um texto que registra diferentes procedimentos metodológicos utilizados para a leitura da dinâmica industrial e suas manifestações territoriais no estado de São Paulo. PARTE I OS PROCESSOS E AS FORMASAcreditamos que, quando se diz "sociedade do conhecimento", o significado da palavra conhecimento assume um sentido específico.Não expressa, em si, cognição e sabedoria, dentre outros sinônimos que poderíamos arrolar.O significado da palavra conhecimento no termo "sociedade do conhecimento" se investe da acepção de que o conhecimento se constitui na principal força de produção dessa sociedade.Significa que o conhecimento se distancia da ideia de constituição do espírito humano e se torna uma força produtiva.Como disse Jean-François Lyotard, o antigo princípio segundo o qual a aquisição do saber é indissolúvel da formação do espírito, e mesmo da pessoa, cai e cairá cada vez mais em desuso.Essa relação entre fornecedores e usuários do conhecimento e o próprio conhecimento tende e tenderá a assumir a forma que os produtores e os consumidores de mercadorias têm com estas últimas, ou seja, a forma valor.O saber é e será produzido para ser vendido, e ele é e será consumido para ser valorizado numa nova produção, nos dois casos, para ser trocado [...] (Lyotard, 1986, p.4-5) O que significa dizer que o conhecimento assume o sentido de ser produzido e consumido como mercadoria.É nesse sentido, de coisa da produção e não de coisa do espírito, que o conhecimento se define hoje em dia.O conhecimento como "coisa da produção" é indispensável à compreensão de qualquer atividade econômica nos dias atuais.Imprescindível, portanto, para se compreender a dinâmica industrial, aqui interessando em particular a indústria de transformação, referida, nesse texto simplesmente como indústria.No caso das informações se referirem ao conjunto da indústria de transformação e da indústria extrativa, esse conjunto estará explicitado.Se não, trata-se apenas da indústria de transformação.Além do aspecto da inovação, que iremos nos referir posteriormente, o grau de intensidade tecnológica para a produção industrial é revelador da incorporação de conhecimento como "coisa da produção".Os exemplos da microeletrônica e da automação na indústria automobilística, em que os robôs roubam a cena, atestam com clareza ofuscante que o conhecimento é "coisa da produção" expresso no alto grau de inovação e de intensidade tecnológica dessas máquinas.Sem menos sedução que os robôs, que nos remetem às fantasias vividas no cinema graças ao robô Sonny, do filme Eu, Robô, ou devido aos robôs R2 e C3PO de Guerra nas estrelas ou, ainda, ao pequeno Wall-e e à O gráfico 1 ilustra o decréscimo da participação da indústria no PIB, mas é importante ponderar que se trata de um decréscimo relativo.Ou seja, esse decréscimo guarda relação com os demais setores da economia.Não podemos, contudo, afirmar que esses dados revelam desindustrialização; o que eles revelam é que, frente aos demais setores da economia, a participação da indústria declinou.Não mais que isso.É interessante chamar atenção para o fato de que, nos países mais ricos, também a participação da indústria no PIB vem decrescendo e, em paralelo, ocorrendo o crescimento do setor de serviços, que passou a gerar mais renda e emprego, como no Brasil.A participação da indústria no PIB dos Estados Unidos decresceu; passou de 21% em 1989, para 13% em 2011.4 Alguns dados podem ajudar a compreender o que estamos querendo afirmar.O valor adicionado da indústria em relação ao PIB correspondeu a 13,3 % no Reino Unido, em 2005, e a 12,7% nos Estados Unidos, em 2009.5 O que vem ocorrendo é que, no Brasil, o setor de serviços vem progressiva e intensamente aumentando sua participação no PIB.Os dados para o Brasil indicam que, em 2009, essa participação foi de 68,5%; ou seja, quase 70% do PIB.A agropecuária contribuiu com 6,1% e a indústria, 15,5%, como indicamos.Essa é a inflexão, a crescente participação do setor de serviços entre as atividades econômicas.6 Examinando-se as contas nacionais no que diz respeito à contribuição ao PIB dada pelas diversas atividades econômicas, vemos que a participação da indústria que era, em 2001, de R$ 17,662 milhões passou a R$ 41,543 milhões em 2009 -último ano de divulgação dos dados.Portanto, cresceu, nesse período, uma vez e meia.Mesmo se descontarmos o efeito das variações monetárias, a indicação de crescimento não se abala.Com crescimento similar temos os dados dos serviços, cuja participação, em 2009, foi de 1,7 vez maior que a de 2001.Especificamente, saltou de R$ 49,132 milhões, em 2001, para R$ 130,426 milhões, em 2009.7 Em termos absolutos, a participação dos 4 Declínio Fabril.(Editorial).Folha de S.Paulo, 9/9/2012, p.2. 5 Fonte dos dados: Banco Mundial.6 Fonte dos dados: FEE.Fundação de Economia e Estatística, Centro de Informações Estatísticas, Núcleo de Contabilidade Social Governo do Estado do Rio Grande do Sul.Valor adicionado bruto a preço básico por setores de atividade -2002-2010.7 Idem.Sabendo-se que a taxa média de inovação da indústria foi da ordem de 38,4%, podemos apreender quais os ramos industriais que estão acima ou abaixo da média de inovação da indústria.Entre os ramos industriais cujas taxas de inovação estão acima dessa média destacam-se o de fabricação de automóveis, caminhonetas e utilitários, caminhões e ônibus, que é um sub--ramo da fabricação de veículos automotores, reboques e carrocerias.Em segundo e terceiro lugares, com uma distância considerável -20% a menos de inovação -, os ramos de fabricação de produtos farmoquímicos e farmacêuticos e o de fabricação de outros produtos eletrônicos e ópticos, este último um sub-ramo do ramo denominado fabricação de equipamentos de informática, produtos eletrônicos e óticos.Em posição diametricamente oposta, relativa aos ramos industriais com menores taxa de inovação, temos a fabricação de celulose e outras pastas, um sub-ramo do ramo de fabricação de celulose, papel e produtos de papel, bem como a fabricação de produtos do fumo, o ramo intitulado manutenção, reparação e instalação de máquinas e equipamentos e, ainda, o ramo de fabricação de produtos de madeira, esse, em último lugar, com uma taxa de inovação de 23%.Um outro dado importante para compreendermos a relação entre indústria e território, do ponto de vista do desenvolvimento regional, diz respeito ao padrão tecnológico da indústria nos diferentes lugares.Essa referência é importante.Como dissemos, produzir aviões é diferente de produzir palitos de fósforos.Portanto, é fundamental levar em consideração o padrão tecnológico na análise da atividade industrial.Para distinguirmos as atividades industriais se', '["industrial dynamics","territorial dynamics","São Paulo state","knowledge society","productive restructuring","industrial clusters","value added tax","food industry","footwear industry","urban hierarchy","small towns","transport infrastructure"]', '10.7476/9788568334669', '9788568334669', 'https://books.scielo.org/id/6y9nc', 'https://books.scielo.org/id/6y9nc/pdf/sposito-9788568334669.pdf', NULL, 'https://books.scielo.org/id/6y9nc/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6yjkh', '6yjkh', 'Sociedade e cultura no Rio Grande do Norte: diálogos interdisciplinares', NULL, '["Alan Martins de Oliveira","Lemuel Rodrigues da Silva","Marcílio Lima Falcão"]', 'EdUFERSA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro Sociedade e Cultura no Rio Grande do Norte: diálogos interdisciplinares tem por objetivo ampliar a reflexão sobre cultura, cidadania, história e sociedade e refletir sobre o necessário diálogo entre universidade, escola e sociedade. É uma construção coletiva, fruto da parceria entre a Universidade Federal Rural do Semi-Árido e a Universidade do Estado do Rio Grande do Norte e conta com o apoio de outras universidades, organizações não governamentais, pesquisadores, estudantes e lideranças comunitárias. Está estruturado em duas partes, a primeira destaca aspectos da cultura e cidadania na perspectiva dos indígenas de João Câmara e Assu, dos quilombolas de Patu e dos educadores potiguares; na segunda parte a ênfase é sobre história e sociedade, ao descrever aspectos relacionados ao batismo e compadrio de escravos em Assú no século XIX e sobre o papel da imprensa e da memória acerca da libertação dos escravos em Mossoró. Destaca ainda a religiosidade do sertanejo potiguar durante a primeira república e descreve o papel do jornal “a ordem” pós-1935. Neste livro é feito um resgate de aspectos que ajudam a compreender o presente na ótica social e cultural, bem como o estágio de desenvolvimento local; além de referenciar pesquisas futuras e subsidiar políticas públicas. É uma obra feita para pessoas que buscam uma leitura interdisciplinar e transversal, tendo como cenário o Estado do Rio Grande do Norte.', '["Rio Grande do Norte","indigenous peoples","quilombola communities","citizenship","culture and society","history and society","university-school-community partnership","Assú","João Câmara","Patu","Mossoró","abolition of slavery"]', '10.7476/9786587108582', '9786587108100', 'https://books.scielo.org/id/6yjkh', 'https://books.scielo.org/id/6yjkh/pdf/oliveira-9786587108582.pdf', NULL, 'https://books.scielo.org/id/6yjkh/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6ys2j', '6ys2j', 'La gráfica urbana entre lo público y lo privado: expresión, cultura e imagen en seis localidades de Bogotá', NULL, '["Omar Alonso García Martínez"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Los autores toman los conceptos “público” y “privado” como puntos de anclaje para comprender las dinámicas que se gestan y dan significado a la imagen como institución comunicativa. Inician su recorrido hablando sobre la posición del arte urbano en el entorno político-social; asimismo, cómo la expresión gráfica se relaciona con un modelo popular de comunicación en los grupos poblacionales “menos favorecidos”. Además, cómo se convierten en elementos de contestación, denuncias políticas, persuasión, crítica social y demarcación del territorio. Lo anterior permite pensar el arte como un discurso estético y político.', '["public and private","urban image","political art","street art","marginalized communities","political protest","social criticism","territorial demarcation","Bogotá"]', '10.7476/9786289558203', '9786289558203', 'https://books.scielo.org/id/6ys2j', 'https://books.scielo.org/id/6ys2j/pdf/garcia-9786289558203.pdf', NULL, 'https://books.scielo.org/id/6ys2j/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6yss8', '6yss8', 'Agrotóxicos: um enfoque multidisciplinar', NULL, '["Jorge Ulises Guerra Villalobos","Silvio Alexandre Fazolli"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Na definição legal de agrotóxicos vê-se que são produtos cuja finalidade é alterar a composição da flora ou da fauna, a fim de preservá-las da ação danosa de seres vivos considerados nocivos. Esses produtos – os agrotóxicos – aparentemente só eliminariam os seres vivos considerados nocivos ou pragas. Muitos produtores ou comerciantes chegaram a denominá-los de ´defensivos agrícolas´. Contudo é muito mais complexa a situação, pois os agrotóxicos poderão ter ´características teratogênicas, carcinogênicas ou mutagênicas´ (art. 3º. da lei 7.802/1989) e, então, não poderão ser registrados (BRASIL, 1989). O nome oficial desses produtos no Brasil é agrotóxico, devendo a sua propaganda comercial conter advertência sobre os malefícios decorrentes de seu uso (art. 220, § 4º da Constituição da República) (BRASIL, 1988). Estudar a produção e os efeitos dos agrotóxicos é de alta importância científica e cívica. É um terreno disciplinar, em que estão, ou deveriam estar presentes, advogados, biólogos, botânicos, ecólogos, engenheiros-agrônomos, engenheiros florestais, geógrafos, químicos, sociólogos e veterinários, entre outros profissionais. Tratar, por meio de diversas facetas, da segurança alimentar é contribuir, decididamente, para valorização dos seres humanos e do equilíbrio ecológico – direito de todos. O livro, Agrotóxicos: um enfoque multidisciplinar, fará com que o leitor se aprofunde em temas que são vitais para a sua sobrevivência no planeta Terra.', '["agrochemicals","pesticides","food safety","multidisciplinary approach","pesticide registration","teratogenicity","carcinogenicity","mutagenicity","environmental impact of pesticides","ecological balance"]', '10.7476/9788576287438', '9788576286998', 'https://books.scielo.org/id/6yss8', NULL, NULL, 'https://books.scielo.org/id/6yss8/cover/cover_thumbnail.jpeg', 214, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6z3tw', '6z3tw', 'Processo de enfermagem: da teoria à prática em cuidados intensivos', NULL, '["Argenta, Carla","Édlamar Kátia Adamy","Bitencourt, Julia Valeria de Oliveira Vargas"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Nursing', '“Processo de Enfermagem: da teoria à prática em cuidados intensivos” reúne uma coletânea de textos cujo objetivo é tornar público, a professores, estudantes e profissionais, um produto que compila o esforço coletivo sustentado pela integração ensino e serviço, disponibilizando material com o qual se pretende subsidiar o processo de ensino e aprendizagem e as práticas de educação permanente relativas ao tema Processo de Enfermagem desenvolvido junto ao paciente internado em terapia intensiva. A obra, que constitui o segundo volume da Coleção “Processo de Enfermagem: da teoria à prática”, aborda a experiência de implantação/implementação do PE no setor da UTI no Hospital Regional do Oeste e, portanto, contextualiza: o PE na assistência à saúde por meio de uma síntese dos aspectos filosóficos, teóricos e metodológicos do PE; alguns aspectos relacionados à UTI; a contextualização do processo de trabalho metodológico para a implantação/implementação do PE; a produção do Histórico de enfermagem e a evolução de enfermagem; a produção da matriz de Diagnósticos de Enfermagem (DE) NANDA-I; a produção da matriz Resultados de Enfermagem (NOC); a produção da matriz de Intervenções de Enfermagem (NIC); a construção final do Instrumento NANDA, NIC, NOC; a aplicação do PE na UTI (estudo de caso); a manutenção da implementação do PE na UTI.', '["nursing process","critical care nursing","intensive care","nursing education","nursing diagnosis","NANDA-I","Nursing Outcomes Classification","nursing interventions","history of nursing","nursing process implementation","nursing documentation"]', '10.7476/9786586545708', '9786586545708', 'https://books.scielo.org/id/6z3tw', 'https://books.scielo.org/id/6z3tw/pdf/argenta-9786586545708.pdf', NULL, 'https://books.scielo.org/id/6z3tw/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-6z5r3', '6z5r3', 'Arquitetura colonial baiana: alguns aspectos da sua história', NULL, '["Robert C. Smith"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O Arquivo Histórico Colonial Português, de Lisboa, possui riquíssimas coleções de desenhos de edifícios do período colonial, incluindo a arquitetura da antiga capital do Brasil. Os documentos anexos, com seus largos relatórios sobre obras públicas e de caridade, merecem a atenção de todos os estudiosos da história da arquitetura colonial, revelando não somente as origens de muitos monumentos, mas oferecendo preciosas elucidações a respeito das modificações que esses edifícios sofreram, principalmente no século XVIII.', '["colonial architecture","Bahia","public works","charity work","architectural history","18th century","historic monuments","architectural alterations"]', '10.7476/9788523211585', '9788523211585', 'https://books.scielo.org/id/6z5r3', 'https://books.scielo.org/id/6z5r3/pdf/smith-9788523211585.pdf', NULL, 'https://books.scielo.org/id/6z5r3/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-724mz', '724mz', 'Sistemas alimentares, fome e insegurança alimentar e nutricional no Brasil', NULL, '["Rosana Salles‐Costa","Aline Alves Ferreira","Paulo R. C. Castro","Luciene Burlandy"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-09-20', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Fome, insegurança alimentar e nutricional, desnutrição, obesidade e doenças crônicas não transmissíveis (DCNT). Questões complexas que influenciam a vida de milhões de pessoas no Brasil e no mundo e que foram potencializadas pelo contexto da pandemia de Covid-19. O livro joga luz sobre esse cenário a partir das perspectivas dos pesquisadores e nutricionistas Rosana Salles-Costa, Aline Alves Ferreira, Paulo Castro Junior e Luciene Burlandy. Segundo os autores, o volume foi elaborado com o intuito de corroborar o debate sobre os desafios e as reflexões pautadas na recente agenda científica sobre o tema. Em cinco capítulos, a obra aborda ainda uma concepção ampliada da chamada SAN: segurança alimentar e nutricional. Essa abordagem leva em conta a construção, ao longo dos anos, de uma política e de um Sistema Nacional de Segurança Alimentar e Nutricional no Brasil, formalizados na Lei Orgânica de Segurança Alimentar e Nutricional (Losan), além das redes organizadas da sociedade civil, das instituições acadêmicas e de segmentos de governos.', '["food systems","hunger","food and nutrition insecurity","malnutrition","obesity","non-communicable diseases","food and nutrition security","civil society networks","food policy","COVID-19 pandemic","Brazil"]', '10.7476/9786557081686', '9786557081341', 'https://books.scielo.org/id/724mz', NULL, NULL, 'https://books.scielo.org/id/724mz/cover/cover_thumbnail.jpeg', 144, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-72gwc', '72gwc', 'As paixões humanas em Thomas Hobbe: entre a ciência e a moral, o medo e a esperança', NULL, '["Hélio Alexandre da Silva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro ''As Paixões Humanas em Thomas Hobbes: entre a ciência e a moral, o medo e a esperança'' analisa a relação existente entre a ciência de matriz mecanicista e o projeto político presente na obra desse autor inglês do séc. XVII. Defende a hipótese de que Hobbes deve muito de sua concepção moral e política aos seus estudos acerca da ciência, que o orientam a pensar o homem e suas paixões. Com esse pressuposto, são também discutidas no livro algumas interpretações que criticam a relação entre filosofia natural (ciência) e filosofia moral. Finalmente, investiga-se o papel que duas paixões em especial, o medo e a esperança, desempenham no processo que afasta a guerra de todos e procura construir a paz política', '["Thomas Hobbes","human passions","fear","hope","mechanistic science","political philosophy","state of nature","war of all against all","peace"]', '10.7476/9788579830242', '9788579830242', 'https://books.scielo.org/id/72gwc', 'https://books.scielo.org/id/72gwc/pdf/silva-9788579830242.pdf', NULL, 'https://books.scielo.org/id/72gwc/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-72xt9', '72xt9', 'Alimentação em jogo: o lobby na regulação da publicidade no Brasil', NULL, '["Marcello Fragano Baird"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Para enfrentar a epidemia de obesidade e outras doenças crônicas, governos de todo o mundo passaram a regular os alimentos ultraprocessados, como salgadinhos e refrigerantes, que geram enormes custos aos sistemas de saúde. “Alimentação em Jogo” desvenda as estratégias de lobby em torno da pioneira iniciativa da Anvisa de regular a publicidade de alimentos não saudáveis no Brasil. O livro também alerta para o perigo de o país ficar para trás na corrida pela regulação dos alimentos ultraprocessados, num contexto em que o tema deverá estar no centro dos debates de saúde pública no Brasil e no mundo.', '["food advertising regulation","lobbying","ultra-processed foods","ANVISA","obesity","chronic disease prevention","public health policy","food industry influence","Brazil"]', '10.7476/9786589992264', '9786589992264', 'https://books.scielo.org/id/72xt9', 'https://books.scielo.org/id/72xt9/pdf/baird-9786589992264.pdf', NULL, 'https://books.scielo.org/id/72xt9/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-74ph9', '74ph9', 'Adolpho Lutz - Hanseníase - v.1, Livro 2', NULL, '["Jaime Larry Benchimol","Magali Romero Sá"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Integra a coleção: BENCHIMOL, J. L.; SÁ, M. R. (Org.). Adolpho Lutz: obra completa. Rio de Janeiro: Fiocruz, [2004-200-?]. 4 v.', '["leprosy","Adolpho Lutz","history of medicine","tropical medicine","public health"]', '10.7476/9788575412367', '9788575412367', 'https://books.scielo.org/id/74ph9', 'https://static.scielo.org/scielobooks/74ph9/pdf/benchimol-9788575412367.pdf', NULL, 'https://books.scielo.org/id/74ph9/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-74psp', '74psp', 'Sociedade civil e democracia na América Latina: crise e reinvenção da política', NULL, '["Bernardo Sorj","Miguel Darcy de Oliveira"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Sociedade Civil e Democracia na América Latina: crise e reinvenção da política abre um debate urgente e necessário sobre os desafios que afetam a governabilidade e consolidação da democracia em nosso continente.Seu ponto de partida é a percepção de que, na América Latina contemporânea, cansaço e desencanto com a democracia representativa e os partidos políticos coexistem com a emergência de uma nova cidadania e o fortalecimento de sociedades abertas.1 Sociólogo e ex-presidente do Brasil.A democracia no centro da agenda 9 formar juízos de opinião.Blogs, emails, celulares e sites estão se tornando ferramentas poderosas de um novo tipo de comunicação: pessoal, participativa e interativa.Vivemos em sociedades "abertas" -violentas, injustas, desiguais -, mas nas quais a liberdade e a diversidade, o debate e a deliberação, a inovação e a experimentação são vetores permanentes de transformação.Essas mudanças no perfil da sociedade tornam mais rica e complexa a interação entre os cidadãos e as instituições políticas.As pessoas recorrem cada vez mais à sua própria experiência para tomar posição.Há uma exigência crescente de verdade e transparência.Estamos no limiar de um novo ciclo histórico em que o verdadeiro debate se dá entre velhos modelos e novas idéias, entre regressão autoritária e fortalecimento da democracia.Novas tendências e dinâmicas levantam novas questões e desafios:• qual o sentido dos processos de transformação política e social em curso em nossas sociedades; • quais os riscos para a democracia do agravamento das tensões étnicas e sociais em vários países da região; • quais os atores e os caminhos para o fortalecimento de uma cultura cívica e de uma democracia no quotidiano, bases para uma reinvenção da política; • quais as perspectivas de renovação das formas clássicas de representação em função da emergência de uma cidadania ativa e de uma nova esfera pública de participação e debate; • qual o significado para a governabilidade democrática da transição de uma esfera pública ancorada nas instituições políticas formais para uma esfera públi-Organizações que invocam direitos.Sociedade civil e representação na Argentina Catalina Smulovitz 1 I. Nos últimos anos, a Argentina experimentou um crescimento significativo no número de organizações da sociedade civil, no número de pessoas nelas envolvidas, bem como um aumento na visibilidade de suas tarefas, funções e reconhecimento.O fenômeno, que coexistiu com o processo da instalação da democracia no país, merece algumas questões.', '["civil society","democracy","Latin America","democratic consolidation","political representation","new citizenship","political participation","public sphere","authoritarianism","civic culture","social movements","governance"]', '10.7476/9788599662236', '9788599662236', 'https://books.scielo.org/id/74psp', 'https://books.scielo.org/id/74psp/pdf/sorj-9788599662236.pdf', NULL, 'https://books.scielo.org/id/74psp/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-75pz8', '75pz8', 'Filosofia, política e cosmologia: ensaios sobre o renascimento', NULL, '["Fabrina Magalhães Pinto","Flávia Benevenuto"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O Renascimento foi sobretudo um período de grande eclosão do pensamento e da criatividade humanas desde a ciência e as várias artes - pintura, arquitetura, escultura - até a filosofia, a poesia, o pensamento político e o jurídico. Foi também um período de grande transformação na sociedade com o surgimento de novos modelos de organização política e econômica que trouxeram grande dinamismo a algumas regiões da Europa e que inclui as navegações no Novo Mundo, que tiveram além do genovês Cristóvão Colombo, o florentino Américo Vespúcio como um de seus protagonistas. O Renascimento é um período multifacetado que produziu obras inovadoras nos campos mais diversos desde o Corpus Hermeticum até O Príncipe de Maquiavel, desde a Capela Sistina de Michelangelo até as máquinas bélicas de Leonardo Da Vinci. No presente livro Filosofia, Política e Cosmologia: Ensaios sobre o Renascimento, organizado por Fabrina Magalhães Pinto e Flávia Benevenuto, e incluindo textos de alguns dos mais importantes especialistas na área no Brasil e no exterior, temos uma significativa contribuição para o estudo do Renascimento precisamente em algumas dessas múltiplas facetas. Essas contribuições, que refletem as pesquisas realizadas por seus autores, assim como os debates que vêm desenvolvendo regularmente, se concentram em três grandes linhas que se interpenetram: a política e a ética; a linguagem; e a cosmologia.', '["Renaissance","Renaissance philosophy","Renaissance political thought","Renaissance cosmology","Renaissance ethics","Renaissance art","Renaissance science","Hermeticism","Niccolò Machiavelli","Columbus","Amerigo Vespucci"]', '10.7476/9788568576939', '9788568576939', 'https://books.scielo.org/id/75pz8', 'https://books.scielo.org/id/75pz8/pdf/pinto-9788568576939.pdf', NULL, 'https://books.scielo.org/id/75pz8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-75wgp', '75wgp', 'Medidas antidumping e política doméstica: o caso da citricultura estadunidense', NULL, '["Camilla Silva Geraldello"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra analisa o funcionamento da dinâmica política dos EUA no processo de tomada de decisões de política externa comercial no contencioso do suco de laranja na OMC ocorrido entre 2009 e 2011, mostrando como tal dinâmica influenciou o embate internacional. A utilização pelos EUA de metodologia já condenada pela OMC para o cálculo de direitos antidumping sobre o produto brasileiro denota que, embora o segmento citricultor não articule cadeias produtivas nacionais, sua importância na Flórida e a importância estratégica deste estado na dinâmica política estadunidense são suficientes para que o setor consiga superar as preferências de livre comércio das indústrias, garantindo proteção.', '["anti-dumping measures","WTO dispute settlement","citrus industry","American politics","trade policy","Florida citrus","political economy of trade"]', '10.7476/9788579836657', '9788579836657', 'https://books.scielo.org/id/75wgp', 'https://books.scielo.org/id/75wgp/pdf/geraldello-9788579836657.pdf', NULL, 'https://books.scielo.org/id/75wgp/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-76264', '76264', 'Fitoterapia e a Ovinocaprinocultura: uma associação promissora', NULL, '["Bezerra, Ana Carla Diógenes Suassuna","Michele Dalvina Correia da Silva"]', 'EdUFERSA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Immunology and Microbiology', 'Em razão da importância do controle dos endoparasitos para a saúde dos pequenos ruminantes frente ao desafio imposto pelo crescente desenvolvimento da resistência parasitária aos produtos químicos, surgiu o interesse em desenvolver uma obra atual, com informações claras sobre os principais helmintos gastrintestinais, estratégias de manejo animal, resistência desenvolvida aos fármacos sintéticos (em especial, a resistência associada aos SNPs), bem como as formas alternativas de controle. Dando ênfase à fitoterapia como estratégia economicamente viável e ambientalmente segura para o tratamento alternativo de animais de produção, a obra traz uma revisão de espécies vegetais encontradas no Brasil cujas ações anti-helmínticas de importância para a saúde de pequenos ruminantes são descritas na literatura. Diante da vasta diversidade de plantas contendo antiparasitários naturais, é dado destaque às metodologias aplicadas in vitro e in vivo para validação científica de plantas como anti-helmínticas, potencialmente úteis como plantas medicinais fitoterápicas. Tais validações vêm sendo realizadas pelos autores, caracterizando plantas do Semiárido Nordestino como fontes de biomoléculas antiparasitárias. Por fim, a Biotecnologia é sinalizada como uma área indispensável para desvendar o conhecimento atual sobre endoparasitas a nível molecular, bem como para desenvolver tecnologias visando o controle parasitário, tais como fármacos inteligentes nanoencapsulados e vacinas gênicas.', '["herbal medicine","sheep and goat farming","gastrointestinal helminths","anthelmintic plants","anthelmintic resistance","alternative parasite control","medicinal plants","genetic vaccines"]', '10.7476/9786587108643', '9786587108643', 'https://books.scielo.org/id/76264', 'https://books.scielo.org/id/76264/pdf/bezerra-9786587108643.pdf', NULL, 'https://books.scielo.org/id/76264/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-76365', '76365', 'Envelhecimento, saúde e cognição humana: importância da dieta, da genética e do estilo de vida', NULL, '["Valdemiro Carlos Sgarbieri","Maria Teresa Bertoldo Pacheco","Nádia Fátima Gibrim","Denise Aparecida Gonçalves de Oliveira","Maria Elisa Caetano‐Silva"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Biochemistry, Genetics and Molecular Biology', 'O livro enfatiza fatores que regem a vida humana do início ao fim e que podem ser muito diferentes entre indivíduos e populações: 1) caracteres genéticos herdados diretamente de nossos pais e indiretamente de nossos ancestrais, os quais permanecem relativamente estáveis ao longo da vida; 2) fatores ambientais (alimentação, condição e estilo de vida) até certo ponto controláveis, sendo a alimentação o mais importante. A primeira parte do livro trata da definição e da conceituação do processo de envelhecimento e seus efeitos na saúde. Seguem-se a apresentação e a discussão de mecanismos que promovem degradação molecular e celular responsáveis por distúrbios metabólicos que podem resultar em doenças crônico-degenerativas. A maior parte do texto é dedicada à apresentação de alimentos e compostos bioativos que agem combatendo o envelhecimento precoce e retardando doenças da idade. Por fim, faz-se uma discussão sobre conceitos de dietas saudáveis com sugestões para pesquisas, visando melhorar o perfil alimentar do brasileiro.', '["aging","health","human cognition","diet","genetics","lifestyle","metabolic disorders","chronic degenerative diseases","bioactive compounds","healthy eating","Brazilian diet"]', '10.7476/9788526815353', '9786586253795', 'https://books.scielo.org/id/76365', NULL, NULL, 'https://books.scielo.org/id/76365/cover/cover_thumbnail.jpeg', 334, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-76v95', '76v95', 'Fragmentos do contemporâneo: leituras', NULL, '["Sérgio Vicente Motta","Susanna Busato"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Fragmentos do contemporâneo: leituras reúne artigos de professores do Programa de Pós-Graduação em Letras da UNESP, campus de São José do Rio Preto, resultado de suas recentes pesquisas sobre literatura contemporânea. O livro, composto por sete estudos, analisa textos e autores nacionais e internacionais, em prosa e poesia, como um modo de recortar esse grande painel e apontar, em seus fragmentos, possibilidades de leituras. Frederico Barbosa, Heitor Ferraz e Fábio Weintraub analisam o sujeito que adere ao espaço urbano em Um reflexo da natureza da poesia contemporânea brasileira; Sérgio Vicente Motta aprecia Leite Derramado, romance de Chico Buarque; Arnaldo Franco Junior explora as relações entre produção textual, intertextualidade em obras de Dalton Trevisan e Valêncio Xavier; a literatura contemporânea portuguesa é contemplada na leitura de Sônia H. Piteri sobre a obra de Maria Gabriela Llansol; enquanto Maria H. Martins Dias aborda o discurso ficcional de António Lobo Antunes, em O manual dos inquisidores. Num outro ângulo sobre o contemporâneo, Giséle Manganelli Fernandes investiga como a ficção pós-moderna reavalia o passado, e para discutir o estilo na tradução literária, Diva Cardoso de Camargo estuda as relações entre estilo do autor e do autotradutor flagradas em Viva o Povo Brasileiro, de João Ubaldo Ribeiro, e em An invincible memory, sua tradução. Obra indispensável para especialistas e interessados em literatura', '["contemporary literature","contemporary Brazilian poetry","Chico Buarque","Leite Derramado","Dalton Trevisan","Valêncio Xavier","intertextuality","contemporary Portuguese literature","Maria Gabriela Llansol","António Lobo Antunes","postmodern fiction","literary translation"]', '10.7476/9788579830051', '9788579830051', 'https://books.scielo.org/id/76v95', 'https://books.scielo.org/id/76v95/pdf/motta-9788579830051.pdf', NULL, 'https://books.scielo.org/id/76v95/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7783t', '7783t', 'História natural da religião', NULL, '["David Hume"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, o filósofo escocês David Hume trata das origens e das causas que produzem o fenômeno da religião, dos seus efeitos sobre a vida e a conduta humanas e das variações cíclicas entre o politeísmo e o monoteísmo. Uma de suas preocupações é também chamar a atenção para os efeitos das diferentes espécies de religião sobre a tolerância e a moralidade. Hume desenvolve uma investigação sobre os princípios "naturais" que originam a crença religiosa, bem como um estudo antropológico e histórico sobre os efeitos sociais da religião.', '["David Hume","natural history of religion","origins of religion","polytheism","monotheism","religious tolerance","morality"]', '10.7476/9788539303120', '9788571396043', 'https://books.scielo.org/id/7783t', NULL, NULL, 'https://books.scielo.org/id/7783t/cover/cover_thumbnail.jpeg', 158, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-77m4f', '77m4f', 'Basta aplicar uma injeção? desafios e contradições da saúde pública nos tempos de JK (1956-1961)', NULL, '["Érico Silva Muniz"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O ano era 1956. Parcelas expressivas das populações pobres do interior padeciam de uma doença infecciosa que atingia pele, ossos e cartilagens, provocando deformidades. Era a bouba, causada por uma bactéria e hoje pouco conhecida mesmo entre médicos e profissionais de saúde. Naquela época, porém, representava um dos entraves à integração do sertão com o litoral e ao avanço do país. Defendia-se, pois, a importância das novas tecnologias médicas para curar aqueles doentes e torná-los trabalhadores aptos à agricultura modernizada. Eram os tempos do nacional-desenvolvimentismo. Esta história – que revela os meandros da saúde pública brasileira na década de 1950, em especial durante o governo de Juscelino Kubitscheck – está esmiuçada neste livro, fruto da premiada dissertação de mestrado do autor. Ele problematiza conceitos como os de controle e erradicação de doenças, e demonstra os limites de uma nova tecnologia biomédica diante da persistência dos determinantes sociais de uma enfermidade – como a pobreza e a fome.', '["osteomyelitis","Juscelino Kubitschek","history of public health","disease control and eradication","biomedical technology","poverty and health","hunger","social determinants of health","rural health","national development","1950s Brazil","sertão"]', '10.7476/9788575414453', '9788580541199', 'https://books.scielo.org/id/77m4f', NULL, NULL, 'https://books.scielo.org/id/77m4f/cover/cover_thumbnail.jpeg', 104, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-77xg3', '77xg3', 'Etnohistorias de América Latina y el Caribe', NULL, '["Heriberto Erquicia"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este es un trabajo colectivo, a partir de una convocatoria abierta, que dio como resultado el libro titulado: Perfiles etnohistóricos en América Latina y el Caribe, que contiene artículos que presentan resultados de investigaciones, reflexiones críticas, teóricas, metodológicas y técnicas de investigación utilizadas en los estudios etnohistóricos del área. El interés de la obra fue generar el debate sobre la articulación de los contextos locales a los procesos de la globalización y sus nexos históricos, políticos, sociales y culturales con América Latina y el Caribe. Es por lo que, en su mayoría, los textos trascienden las barreras geográficas y geopolíticas, y van más allá de los nacionalismos, regionalismos o de las áreas geográficas comúnmente trazadas por las fronteras del Estado nación. Los escritos permiten entender las diversas dinámicas sociales e interrelaciones históricas y geográficas del continente, con el entramado de nexos globales que inciden en la construcción de formas, fronteras e imaginarios particulares de ver, conocer y dominar al “otro” y lo “otro”. El libro está dividido en dos grandes secciones, una Etnohistorias de América Latina, siglos XVI-XX, y la otra Historia, derecho, género y políticas en América Latina, siglos XX y XXI. La primera sección inicia con el artículo denominado, Los Izalcos: Un altépetl complejo registrado por los tlaxcaltecas en 1524, de Hugo Díaz Chávez, Julio César Alvarado Hernández y David Calogero Messana Villafranco. Este artículo aporta a la comprensión de la distribución geográfica de los pueblos nahuas antes de la invasión y ocupación europea, así como, su impronta en las divisiones administrativas actuales.', '["ethnohistory","Latin America","Caribbean","globalization","Nahuas","Izalco","altepetl","indigenous peoples","otherness"]', '10.7476/9789978106709', '9789978106709', 'https://books.scielo.org/id/77xg3', 'https://books.scielo.org/id/77xg3/pdf/uribe-9789978106709.pdf', NULL, 'https://books.scielo.org/id/77xg3/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-78c7c', '78c7c', 'Segurança alimentar e nutricional: perspectivas, aprendizados e desafios para as políticas pública', NULL, '["Cecília Rocha","Luciene Burlandy","Rosana Magalhães"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O desafio: entender a segurança alimentar e nutricional como um bem público em sociedades pautadas em economias de mercado e como uma questão ampla que demanda a articulação de ações relacionadas à produção, comercialização, abastecimento, acesso e consumo de alimentos. O caminho: reflexões teóricas e metodológicas articuladas a análises sobre experiências implementadas no Brasil. O resultado: esta coletânea que discute as conexões entre dinâmica alimentar, sistema alimentar e políticas públicas, direitos sociais e padrões de desenvolvimento equitativos. A construção do conceito de segurança alimentar e nutricional é o assunto explorado na primeira parte do livro, que também aborda as interfaces com os campos da economia, nutrição, sociologia e políticas públicas. Já na segunda parte, discutem-se as experiências de diferentes programas e ações, bem como questões de planejamento e avaliação. A coletânea comenta a Política Nacional de Alimentação e Nutrição, o Sistema e a Política Nacional de Segurança Alimentar e Nutricional, o Sistema de Vigilância Alimentar e Nutricional (Sisvan), a promoção da alimentação saudável e outras ações do Ministério da Saúde; o Programa Nacional de Fortalecimento da Agricultura Familiar (Pronaf); o Programa de Aquisição de Alimentos (PAA); o Programa Bolsa Família (PBF); e diversos outros. O PBF é alvo de um dos capítulos da terceira parte, dedicada a segmentos populacionais específicos – no caso, a pesquisa analisa a relação do Bolsa Família com a segurança alimentar e nutricional sob a ótica das desigualdades raciais. Há também capítulos voltados à análise da segurança alimentar e nutricional em comunidades quilombolas e das inter-relações com as questões de gênero.', '["food and nutrition security","food systems","public policy","nutrition policy","food monitoring","healthy eating promotion","Food Acquisition Program (PAA)","Bolsa Família","conditional cash transfers","racial inequality","quilombola communities","gender relations"]', '10.7476/9788575415849', '9788575414354', 'https://books.scielo.org/id/78c7c', NULL, NULL, 'https://books.scielo.org/id/78c7c/cover/cover_thumbnail.jpeg', 225, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-78sxn', '78sxn', 'O conceito de imitação na ópera francesa do século XVIII', NULL, '["Rodrigo Barbosa Lopes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Cette mémoire porte sur Le Concept de l''Imitation à l''Opéra Français du XVIIIe siècle à partir de l''examen de textes français de référence du même siècle, comme ceux de Jean Baptiste Dubos et Charles Batteux. On se demande quels ont-été les concept et modèles mimétiques utilisés au XVIIIe siècle en France? Comment mimesis a été attachée aux concepts de goût définis dans les textes et traités de l''époque? On a suivi le chemin herméneutique de l''imitation comme une condition sine qua non pour la mise en œuvre de l''opéra, tout en considérant les controverses, querelles et changements sociaux qui ont fait de la mimesis une victime de son temps. Le concept d’imitation, comme une règle établie dans la Poétique d''Aristote et utilisé comme un modèle pour le théâtre classique français du XVIIe siècle, a connu dans l’opéra, depuis la Renaissance, une autre forme d’expression. Le concept de mimesis chez Aristote était attaché à un concept de la nature d’où il inférait ses modèles et définitions de goût. Ce même concept de la nature a changé pendant le XVIIIe, en modifiant également le dispositif d''imitation. Raison, sentiment et expression ont été trois concepts renfermés dans la concept de la nature au fur et à mesure que la théorie mimétique était utilisé comme dispositif permanent pour la mise en œuvre de l''opéra français. Parmi les théoriciens de l’imitation, ils se demandaient quelle était la signification de la musique, à quoi imitait-elle, ou encore à quoi doit-elle imiter. On soutien comme hypothèse dans cette mémoire que la nature de l’opéra français au XVIIIe siècle ne permettait point de concrétiser totalement le concept de mimesis.', '["imitation","French opera","18th-century opera","music aesthetics","Enlightenment philosophy","opera theory"]', '10.7476/9788579836633', '9788579836633', 'https://books.scielo.org/id/78sxn', 'https://books.scielo.org/id/78sxn/pdf/lopes-9788579836633.pdf', NULL, 'https://books.scielo.org/id/78sxn/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-79827', '79827', 'Jacinta Passos, coração militante: obra completa: poesia e prosa, biografia, fortuna crítica', NULL, '["Janaína Amado"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Essa é a primeira edição da obra completa de Jacinta. Os quatro livros de poemas que publicou, entre os anos de 1942 e 1958, foram lançados em edições pequenas, há muito esgotadas. A presente edição contém a poesia completa de Jacinta, incluindo seus livros publicados, poemas esparsos e poemas inéditos, estes últimos, parte de uma série manuscrita, produzida nos últimos anos de vida da autora, jamais trazidas antes ao público. O volume conta ainda com uma prosa completa de Jacinta, a biografia da jornalista e um caderno de imagens, contendo fotos de Jacinta e de pessoas e locais importantes em sua vida.', '["Brazilian poetry","women poets","unpublished poems","collected works","journalists","critical reception","Brazilian prose","literary criticism","women writers"]', '10.7476/9788523212070', '9788523208981', 'https://books.scielo.org/id/79827', 'https://books.scielo.org/id/79827/pdf/amado-9788523212070.pdf', NULL, 'https://books.scielo.org/id/79827/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-79rkr', '79rkr', 'Diálogos sobre gestão cultural', NULL, '["Gisele Marchiori Nussbaumer","Giuliana Kauark","Nara Pessoa"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A coletânea Diálogos sobre Gestão Cultural revisita debates promovidos ao longo de nove edições do evento homônimo, realizadas entre 2017 e 2024 pelo grupo de pesquisa Coletivo Gestão Cultural (UFBA/UFRB). Destinado a pesquisadores(as), gestores(as) e agentes culturais, o livro analisa a gestão cultural na contemporaneidade, articulando reflexões teóricas de viés contra-hegemônico e experiências empíricas que evidenciam práticas insurgentes e engajadas. Ao abordar temas como institucionalidade, tecnicismo, espaços culturais, liberdade artística e conservadorismo político, a obra busca contribuir com a produção de conhecimento no campo da cultura, bem como estimular e defender perspectivas e práticas que promovam uma gestão cultural democrática.', '["cultural management","counter-hegemonic perspectives","institutionalization","technicism","cultural space","artistic freedom","political conservatism","cultural actors"]', '10.7476/9786556309040', '9786556307527', 'https://books.scielo.org/id/79rkr', 'https://books.scielo.org/id/79rkr/pdf/nussbaumer-9786556309040.pdf', NULL, 'https://books.scielo.org/id/79rkr/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-79zyr', '79zyr', 'Estudos sociopolíticos da Inteligência Artificial', NULL, '["Iasulaitis, Sylvia","Silveira, Sérgio Amadeu da"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Computer Science', 'Com o avanço da Inteligência Artificial (IA) e a proliferação de suas aplicações em diversos âmbitos, os atores inteligentes não humanos estão, cada vez mais, tornando-se parte da sociedade contemporânea e impulsionando transformações em diversos aspectos da organização e da realidade social. As disciplinas científicas que estudam o social, particularmente as Ciências Sociais, podem dar sua contribuição para compreensão dos aspectos específicos da digitalização na vida cotidiana, que é um domínio onde a Inteligência Artificial desempenha papel crescente. Nesta coletânea, o intuito é apresentar um conjunto de textos que refletem sobre a Inteligência Artificial a partir de uma perspectiva eminentemente sociológica, partindo-se da concepção de que a IA consiste em um fenômeno social, sendo, ela própria, um ator social não humano.', '["artificial intelligence","digitalization of everyday life","sociology of artificial intelligence","social change"]', '10.7476/9786552210234', '9786552210241', 'https://books.scielo.org/id/79zyr', 'https://books.scielo.org/id/79zyr/pdf/iasulaitis-9786552210234.pdf', NULL, 'https://books.scielo.org/id/79zyr/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7b42x', '7b42x', 'Interculturalidad. Problemáticas y perspectivas diversas', NULL, '["Fernando Garcés","Rubén Bravo"]', 'SciELO', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este libro es una muestra de la ampliación de los horizontes reflexivos en torno a la interculturalidad. Se puede, se debe, hoy pensar la filosofía, la política pública, la universidad, la formación del profesorado, las luchas sociales, etc, en clave intercultural. No por un mero afán academicista sino como base para desde ahí construir sociedades interculturales. Hoy ya es lugar común saber que lo intercultural nació vinculado a la simple idea de diversidad; sin embargo, más que nunca es necesario pensarla como posibilidad de ruta crítica de mucho del accionar humano. Este trabajo se publica en el contexto post paro nacional de octubre de 2019. Ahí quedó claro que la interculturalidad tiene que ver con históricas cargas racistas-coloniales y con contemporáneas desigualdades económicas que cruzan geopolíticas globales, regionales y nacionales. Esto nos muestra la necesidad de tomarnos en serio una interculturalidad que apunte a la abolición de las asimetrías sociales en conexión con la apuesta por la construcción de una verdadera plurinacionalidad. Una que exija el respeto a la diferencia en términos políticos y equidad en términos económicos.', '["interculturality","intercultural society","diversity","economic inequality","social justice","plurinationalism","public policy","teacher professional development","universities","social movements","respect for differences","equity"]', '10.7476/9789978104972', NULL, 'https://books.scielo.org/id/7b42x', 'https://books.scielo.org/id/7b42x/pdf/garces-9789978104972.pdf', NULL, 'https://books.scielo.org/id/7b42x/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7bm6b', '7bm6b', 'O escândalo do corpo falante: Don Juan com Austin, ou a sedução em duas línguas', NULL, '["Shoshana Felman"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Publicado na França e nos Estados Unidos na década de 1980, este livro inaugura um dos conceitos mais importantes de Shoshana Felman – o de “corpo falante” –, cunhado a partir da articulação entre a teoria de Austin, sobre o performativo, e a de Lacan, sobretudo no que se refere às noções lacanianas de “lettre” e de “parlêtre”. Numa preciosa articulação entre a letra/carta e o corpo; o ser, a letra e o sujeito, este último tomado em sua dimensão de “ato discursivo” como o “animal promitente” por excelência, Shoshana Felman relê a figura do personagem Don Juan, no texto literário/dramatúrgico Don Juan, de Molière, de maneira a nos fazer reler as noções de ato, na conjunção entre a teoria dos atos de fala com a teoria psicanalítica, mas sobretudo no atravessamento radical operado pela “coisa literária”, em sua formulação autoral de “corpo falante” (Os tradutores).', '["Shoshana Felman","speaking body","J. L. Austin","performativity","Jacques Lacan","Molière","Don Juan","seduction","translation"]', '10.7476/9788526816626', '9788526815612', 'https://books.scielo.org/id/7bm6b', NULL, NULL, 'https://books.scielo.org/id/7bm6b/cover/cover_thumbnail.jpeg', 188, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7bp9j', '7bp9j', 'Latinitas: uma introdução à língua latina através dos textos', NULL, '["José Amarante"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta 2ª edição é a reunião do primeiro volume (Fábulas mitológicas e esópicas, epigramas, epístolas) e do segundo volume (Elegias, poesia épica, odes) de “Latinitas: Leituras de texto em língua latina”, compilados em um volume único. A obra assim mantém seus elementos e participa da história educacional do latim no Brasil, compondo um método próprio para o estudo da língua, com a abordagem de obras de variados gêneros, trazendo textos originais de autores canônicos, abarcando o maior número possível de exercícios e de vocabulário e contribuindo para o enriquecimento das pesquisas no país na área de didática das línguas clássicas, que vêm se ampliando consideravelmente.', '["Latin language","Latin didactics","classical language teaching","Latin texts","mythological fables","Aesop''s fables","Latin epigram","Latin letters","Latin elegy","Latin epic poetry","Latin odes","Latin vocabulary"]', '10.7476/9788523220341', '9788523216740', 'https://books.scielo.org/id/7bp9j', NULL, NULL, 'https://books.scielo.org/id/7bp9j/cover/cover_thumbnail.jpeg', 606, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7bvvd', '7bvvd', 'Proceso de construcción de la política cultural en la Universidad del Rosario', NULL, '["Adriana Díaz Támara","Margarita Guzmán Bejarano"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La Decanatura del Medio Universitario de manera concertada con la Dirección de Extensión y la Escuela de Ciencias Humanas de la Universidad del Rosario desarrolló un estudio, comprendido entre el 2009 y el 2011, con el objetivo de establecer lineamientos para construir una política cultural en la universidad. Este trabajo se plasmó en un documento que definió la forma de cumplir el objetivo de “fortalecer la proyección del Medio Universitario” a través de la inserción de políticas, estrategias, programas y líneas de acción cuyo foco esté puesto en el concepto de Universidad Promotora de Salud. Este programa se desarrolló mediante varios ejes, entre ellos el cultural, lo que dio espacio para el diseño de una política en ese sentido. Este texto presenta la ruta que se siguió para construir dicha política. La publicación de las memorias de este proceso aporta a la discusión sobre cómo abordar la cultura desde las Instituciones de Educación Superior –IES, la importancia que esta tiene y, la experiencia del Rosario, sirve de referente para los procesos de construcción de política que adelantan otras IES.', '["cultural policy","higher education institutions","university cultural policy","Colegio Mayor de Nuestra Señora del Rosario","university extension","policy making"]', '10.7476/9789587385410', '9789587385410', 'https://books.scielo.org/id/7bvvd', 'https://books.scielo.org/id/7bvvd/pdf/diaz-9789587385410.pdf', NULL, 'https://books.scielo.org/id/7bvvd/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7bzx4', '7bzx4', 'Cuidar, controlar, curar: ensaios históricos sobre saúde e doença na América Latina e Caribe', NULL, '["Gilberto Hochman","Diego Armus"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'ApresentaçãoEste livro é dedicado inteiramente à história da saúde, da medicina e das doenças na América Latina e no Caribe e resulta de um empreendimento que se iniciou com uma conversa dos dois organizadores no Rio de Janeiro no final do ano de 2000.A idéia inicial que perseguimos ao longo de três anos foi oferecer ao leitor brasileiro um livro inédito que reunisse trabalhos e autores que o instigassem a refletir sobre as relações entre saúde, doença e sociedade na América Latina em perspectiva histórica, espelhando o estado da arte desse campo emergente e constituindo uma referência, e mesmo um livro-texto, para profissionais, professores e estudantes das áreas de história, saúde coletiva, medicina, ciências sociais e humanidades em geral.Desde o início, a Editora Fiocruz acolheu nossa proposta e forneceu suporte a um empreendimento acadêmico e editorial que se sabia complexo e trabalhoso.Por meio de inúmeras trocas de correios eletrônicos e algumas reuniões durante seminários internacionais, selecionamos textos já publicados, e mesmo consagrados, no Brasil e no exterior; para alguns autores, solicitamos atualizações e adaptações; para outros, encomendamos trabalhos originais.A nossa escolha recaiu em seis trabalhos sobre o Brasil e mais oito experiências nacionais que enfocam o período que vai do final do século XIX às últimas décadas do século XX.Reunimos autores de diferentes inscrições disciplinares e pertencentes a diversas instituições acadêmicas da América Latina e da América do Norte.Ainda que seja desnecessário esclarecer que toda seleção é incompleta, acreditamos que esta representa bastante fielmente as direções e possibilidades que está tomando o campo de estudos da saúde e da doença na América Latina e no Caribe em pers-enfermeiras e antropólogos.Se a medicalização de nossas sociedades implicou relações intrinsecamente hierárquicas e disciplinadoras, e com subordinações múltiplas, a produção de conhecimento, as estratégias de controle, os atos de cuidar e as práticas de cura portam também dissonâncias, insubordinações, contestações, negociações, consensos, diluições, ambigüidades, recriações e positividades.Assim, a assunção da assimetria de poder nas relações historicamente instituídas nessas dimensões é o ponto de partida das análises, não sua conclusão.Em seu conjunto, os ensaios deste livro descortinam um leque polifônico no qual as interações entre indivíduos, grupos, instituições e governos sobre os sentidos da saúde, da doença e dos ciclos de vida questionam fronteiras, adquirem múltiplas direções e podem ter resultados distintos, não-antecipados, divergentes, mutáveis e culturalmente contingentes a depender de cada contexto histórico e nacional específico.Por último, a doença e a saúde como objetos nessas dimensões são também recursos analíticos para se abordar de dilemas e questões cruciais da história e das sociedades latino-americanas e caribenhas: o papel do Estado na produção do bem-estar da população, as possibilidades e os modos de inserção da América Latina no mundo moderno e civilizado, as relações com os demais latino-americanos e com os americanos do norte, os padrões de políticas públicas em diferentes ordenamentos constitucionais e políticos, a constituição de movimentos e ideologias nacionalistas, os processos de construção de autoridade pública, de centralização, burocratização e profissionalização, os possíveis arranjos institucionais das ciências, os impactos do autoritarismo e as possibilidades de uma ordem democrática, o papel dos intelectuais e do pensamento científico e a dinâmica das relações raciais.Em especial, a questão que perpassa todas as narrativas do livro, como os desafios do controle, da incorporação e da integração de vastos contingentes populacionais, de imigrantes e de grupos sociais e étnicos.De modo mais direto, o desafio da construção de uma identidade nacional em relação a múltiplos recortes identificadores em meio a sociedades em geral caracterizadas pela desigualdade, pobreza e miscigenação e com marcas históricas de colonialismo, violência e escravidão.A natureza tropical com suas facetas infernais e paradisíacas, a urbe moderna e suas mazelas e esperanças, a doença e suas marcas, o corpo doente e seus fluidos, a morte e os mortos, as crises epidêmicas, as endemias onipresentes e as promessas e possibilidades de sanidade e salubridade e também os esforços dos médicos, da imprensa e das instituições públicas em desqualificar, combater e controlar esses praticantes.Esse convívio fornece indícios da compreensão da população sobre os processos de saúde e de doença e de suas escolhas diante de múltiplas ofertas de assistência e cura.Uma rediscussão das relações entre a filantropia norte-americana e a América Latina e Caribe, objeto de inúmeros trabalhos sobre a história da saúde na região, está no centro do capítulo de Steven Palmer.Ao abordar o encontro das campanhas de combate à ancilostomíase da Fundação Rockefeller com as políticas nacionais de educação e saúde da Costa Rica entre 1914 e 1921, o autor narra como indivíduos, grupos intelectuais e instituições costarriquenhas foram capazes de transformar os esforços da Fundação em um mecanismo de consolidação de um projeto de saúde pública já existente na Costa Rica.A precedência de políticas autóctones significou que setores-chave do governo e da sociedade estivessem mais conscientes do que os norte-americanos sobre o que a campanha contra a ancilostomíase poderia oferecer ao país, permitindo-lhes dela se apropriar e incorporá-la numa matriz institucional desenhada localmente.Em seu ensaio, Luiz A. de Castro-Santos discute os impactos e os significados do movimento sanitarista e das reformas sanitárias no crescimento dos aparelhos de Estado, na sua interiorização e no surgimento de uma ideologia de construção nacional no Brasil da Primeira República.A discussão é construída pela comparação dos processos de reforma dos serviços sanitários em alguns estados brasileiros a partir de variáveis tais como o lugar da política de imigração de trabalhadores e de preservação e reprodução da mão-de-obra nas agendas das elites, a dinâmica políticopartidária e a tradição médica e sanitária.A análise da combinação específica de fatores econômicos, políticos, ideológicos e científicos explica os ritmos, os tempos e os resultados de cada experiência estadual e apresenta um quadro interpretativo do sanitarismo brasileiro com mais nuances, variações e complexidades.As condições e as possibilidades da integração da medicina ocidental com a cultura indígena em programas de saúde pública é o tema do trabalho de Marcos Cueto sobre o Peru.As ações do médico Manuel Núñez Butrón na década de 1930 na região de Puno são analisadas como uma possível e criativa articulação entre conhecimento médico moderno com a cultura e práticas indígenas, resultando no envolvimento comunitário e de povos indígenas em campanhas de educação, de combate ao tifo epidê-Referências Bibliográficas ARMUS, D. Cultura, historia y enfermedad.A modo de introducción, In: ARMUS, D.', '["history of health","history of medicine","disease","Latin America","Caribbean","medicalization","care","control","healing practices","collective health","19th-20th century","Brazil"]', '10.7476/9788575413111', '9788575413111', 'https://books.scielo.org/id/7bzx4', 'https://books.scielo.org/id/7bzx4/pdf/hochman-9788575413111.pdf', NULL, 'https://books.scielo.org/id/7bzx4/cover/cover_thumbnail.jpeg', NULL, 35, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
