E WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7cd3q', '7cd3q', 'Chilean Voices: Activists Describe their Experiences of the Popular Unity Period', NULL, '["Colin Henfrey","Bernardo Sorj"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'en', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Activists describe their experiences of the popular unity period', '["Popular Unity government","Salvador Allende","Chilean socialism","political repression","student movement","1973 coup"]', '10.7476/9788599662847', NULL, 'https://books.scielo.org/id/7cd3q', 'https://books.scielo.org/id/7cd3q/pdf/henfrey-9788599662847.pdf', NULL, 'https://books.scielo.org/id/7cd3q/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7cnwy', '7cnwy', 'Fronteiras da engenharia e ciências ambientais: perspectivas multidisciplinares', NULL, '["Vilanova, Mateus Ricardo Nogueira","Shiino, Marcos Yutaka"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os impactos ambientais decorrentes da ação humana têm se tornado cada vez mais evidentes e intensos, comprometendo o equilíbrio dos ecossistemas e a disponibilidade dos recursos naturais. Nesse contexto, os aspectos sociais e econômicos amplificam a complexidade da tomada de decisões rumo ao desenvolvimento sustentável. Nesse cenário desafiador, as áreas de Engenharia e de Ciência Ambiental são fundamentais para produzir conhecimento e tecnologias capazes de conciliar a proteção ambiental com o bem-estar social e o desenvolvimento econômico. Este livro reúne contribuições de pesquisadores atuantes em diversos campos daquelas duas disciplinas, sendo direcionado, principalmente, para profissionais e alunos de pós-graduação. Além de apresentar aspectos atuais e relevantes dessas áreas, a obra fornece ao leitor uma experiência multidisciplinar da engenharia e da ciência ambiental, destacando a necessidade de integração entre diversas esferas de conhecimento na busca pelo ideal do desenvolvimento sustentável.', '["environmental engineering","environmental science","interdisciplinary research","sustainable development","anthropogenic impacts","natural resource availability","environmental protection","socio-economic development"]', '10.7476/9786557140093', '9786557140093', 'https://books.scielo.org/id/7cnwy', 'https://books.scielo.org/id/7cnwy/pdf/vilanova-9786557140093.pdf', NULL, 'https://books.scielo.org/id/7cnwy/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7cs92', '7cs92', 'Ciranda de sons: práticas criativas em educação musical', NULL, '["Marisa Trench de Oliveira Fonterrada"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Referências bibliográficas 251 ABERTURA Esta ciranda não é minha só, é de todos nós, Ela é de todos nós... (Capiba) Em abril de 2011, o Instituto de Artes da Unesp recebeu, durante três semanas, a visita da pesquisadora e docente Chefa Alonso, musicista espanhola especializada em técnicas de Improvisação Livre, entre as quais se destaca o trabalho sistemático de criação e improvisação com instrumentos, voz e corpo.No período em que esteve em São Paulo, Alonso trabalhou diretamente com o Grupo de Estudos e Pesquisa em Educação Musical (Gepem), no Instituto de Artes da Unesp, conduzindo um "Seminário de Pesquisa em Improvisação Livre", realizado com alunos de graduação e pós-graduação em Música, sob os auspícios da Fundação para o Desenvolvimento da Unesp (Fundunesp) e do Centro Cultural da Espanha em São Paulo (CCE).Entre as atividades desenvolvidas pela pesquisadora espanhola na ocasião, destaque-se a Orquestra de Improvisadores, formada por alunos de graduação e pós-graduação em Música do IA/Unesp, idealizada para dar suporte ao exercício de técnicas especiais dirigidas à improvisação e à criação instrumental, abrindo espaço para o desenvolvimento de investigações nessa área, realizadas tanto nários de Música, mas também em outras cidades, como Salvador (BA), Fortaleza (CE) e Porto Alegre (RS).Embora, à época, essa fosse uma prática bastante difundida, ao menos em alguns redutos importantes ligados à educação musical e à composição, infelizmente não se chegou a perceber fortemente sua influência nas escolas especializadas em música (conservatórios e escolas livres) e nem nas escolas brasileiras de ensino fundamental e médio.Na atual conjuntura brasileira, em que as escolas estão buscando atender à LDBEN nº 9394/96 e, mais recentemente, à Lei nº 11769/2008, que determina a presença obrigatória da música nas escolas, depois de um prolongado tempo de quase completa ausência, as práticas criativas veem-se agora fortalecidas.Isso se dá por parecerem adequadas à introdução ou ao fortalecimento da prática da música nas escolas, pela facilidade de acesso da população escolar a essa linguagem, bem como de pessoas de diferentes faixas etárias, músicos e não músicos.A adesão a essa prática amplia sobremaneira a sua adoção não apenas em escolas, mas, também, em espaços culturais diversos e outros programas formais ou não formais que se dedicam ao ensino e à aprendizagem de música.Além disso, essas práticas promovem trabalhos interativos entre a música e outras linguagens expressivas -teatro, dança, artes plásticas -, além de outras disciplinas do currículo, como Literatura, História, Matemática, Geografia, e outras, o que enriquece a proposta, muito embora se deva cuidar para que não se reintegre aos currículos a discutível prática da polivalência (Lei 5692/71), que já demonstrou suficientemente sua ineficácia para o ensino de Arte.É importante destacar que o tipo de técnica de que trata esta pesquisa prioriza a prática musical em vez da informação de cunho teórico, pois embora os aspectos teóricos sejam importantes, a maneira mais direta de se dominar as técnicas de criação musical e improvisação se dá pela experiência viva ao instrumento, ou com a voz e o corpo.Defende-se, aqui, a importância de tal prática, em especial com alunos dos cursos de licenciatura em Música/Educação Musical, professores de escolas de educação básica e interessados em geral, pesquisa, os objetivos, a metodologia adotada, a fundamentação teórica, a justificativa e as conclusões.Os objetivos iniciais desta pesquisa, aqui apresentados, foram cumpridos da seguinte maneira: em primeiro lugar, realizou-se o "Seminário de Improvisação Livre", ministrado por Chefa Alonso durante três semanas, em setembro de 2012, que atendeu a alunos dos cursos de graduação e pós-graduação do IA/Unesp, além de outros músicos, provenientes de outras instituições.Após essa atividade, cumpriu-se o segundo objetivo da pesquisa (ver página 19): "Levar a Madri resultados preliminares da pesquisa e trazer de lá resultados de trabalhos similares".Para isso, a pesquisadora foi a Madri no período compreendido entre 20 de janeiro e 4 de fevereiro de 2013, quando, a convite da direção do Festival de Improvisadores Hurta Cordel, ministrou um seminário de Práticas Criativas.Como nesse momento ainda não estava terminada a coleta de dados desta pesquisa, difundiu-se o próprio projeto, além de buscar conhecer dados a respeito da presença ou não dessas práticas em escolas espanholas, mediante informações obtidas com participantes do Seminário e realização de entrevistas com duas pessoas: Chefa Alonso, Diretora do Festival Hurta Cordel, e Prof. Ildefonso Rodríguez, Diretor da Escola Municipal de Música de León.As questões a respeito da existência ou não dessa prática em escolas e outros agrupamentos brasileiros foram atendidas mediante uma série de ações: -Verificação, no Banco de Teses do Portal da Capes, das teses e dissertações defendidas nos últimos vinte anos (de 1992 a 2012) que abordam esta temática; -Busca pela presença do tema em artigos nos Anais de Congressos da ANPPOM (Associação Nacional de Pesquisa e Pós-Graduação em Música) e da ABEM (Associação Brasileira de Educação Musical) realizados no País, bem como em revistas científicas brasileiras; -Averiguação de sua presença ou não em escolas brasileiras de educação básica, escolas de música, conservatórios e setembro de 2013, e no III Encontro de Educação Musical promovido pela Universidade Federal de São João Del Rei, ocorrido em outubro do mesmo ano, onde também foi realizada uma palestra a respeito da temática.Além disso, apresentou-se um relato da pesquisa e alguns dados parciais em Fortaleza, na Universidade Federal do Ceará (UFC), a alunos do curso de licenciatura em Música daquela instituição, no dia 3 de dezembro de 2013.A descrição pormenorizada do material encontrado, sua análise e seus resultados serão apresentados no decorrer deste volume.Com essas e outras ações e reflexões propiciadas pela pesquisa, acredita-se poder ampliar o interesse por essa modalidade de Educação Musical e fortalecer sua aplicação no País, além de abrir portas a outras pesquisas.Utilizaram-se, como títulos das partes e capítulos do presente volume, denominações que remetem ao universo da Música que, simbolicamente, reforçam a temática da pesquisa: a presença das práticas criativas na educação musical.Desse modo, além da Abertura, o texto organiza-se em três partes, aqui denominadas Movimentos.No Primeiro Movimento -Invenção a duas vozes -apresentam--se duas temáticas desenvolvidas durante a pesquisa: Capítulo 1, "Improvisação Livre em São Paulo", e Capítulo 2, "Jogos criativos em Madri", nos quais se apresentam as atividades das duas pesquisadoras que intercambiaram experiências nos países que visitaram.O Segundo Movimento -Tema e variações -apresenta os resultados da investigação em duas frentes, a produção acadêmica e a divulgação das pesquisas nos lugares que reconhecidamente abrem espaço para isso.No Capítulo 3, "Práticas criativas na produção acadêmica", apresentam-se as teses e dissertações que trabalharam com a temática.No Capítulo 4, "Práticas criativas na mídia especializada", verificou', '["free improvisation","music education","creative practice","music education policy","music teacher education","Brazilian music education"]', '10.7476/9788568334607', '9788568334607', 'https://books.scielo.org/id/7cs92', 'https://books.scielo.org/id/7cs92/pdf/fonterrada-9788568334607.pdf', NULL, 'https://books.scielo.org/id/7cs92/cover/cover_thumbnail.jpeg', NULL, 25, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7cxjn', '7cxjn', 'Terreiros Egúngún: um culto ancestral afro-brasileiro', NULL, '["José Santanna Sobrinho"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Apresentando ampla pesquisa etnográfica, o livro traz uma investigação profunda da expansão das comunidades terreiros na atualidade, em especial dos Terreiros Egúngún, localizados na Ilha de Itaparica (BA). O livro conta com testemunhos e opiniões de líderes religiosos sobre o fluxo e a expansão das tradições em meio às mudanças que ocorrem na geografia urbana da região, que abriga os primeiros terreiros de culto aos ancestrais desde o século XIX.', '["Afro-Brazilian religions","ancestor veneration","Candomblé","Itaparica Island","religious communities","urban geography","religious leaders"]', '10.7476/9786556304137', '9786556301532', 'https://books.scielo.org/id/7cxjn', NULL, NULL, 'https://books.scielo.org/id/7cxjn/cover/cover_thumbnail.jpeg', 286, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7d5h2', '7d5h2', 'Óptica geométrica', NULL, '["Lilia Coronato Courrol","André Oliveira Preto"]', 'Editora Fap-Unifesp', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Physics and Astronomy', '[RETIRADO/WITHDRAWN] Dividido em sete capítulos, Óptica Geométrica aborda temas fundamentais para compreender o funcionamento dos mais diversos equipamentos relacionados a esta disciplina, como microscópio, telescópio, projetores, leitores de códigos de barras, lasers, detectores, sensores etc. Propondo-se a unir teoria e prática, esta publicação da Editora Fap-Unifesp sugere, por fim, cinco experimentos de laboratório com o intuito de ajudar o aluno no entedimento da teoria proposta, constituindo uma obra relevante a todos que utilizam ou queiram fazer uso da óptica como meio de investigação em experimentos científicos.', '["geometrical optics","optical instruments","microscope","telescopes","projectors","barcode reader","lasers","photodetectors","optical sensors","laboratory experiments"]', '10.7476/9788561673574', '9788561673574', 'https://books.scielo.org/id/7d5h2', NULL, NULL, 'https://books.scielo.org/id/7d5h2/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7dgcr', '7dgcr', 'D. B. Elkonin: vida e obra de um autor da psicologia histórico-cultural', NULL, '["Lucinéia Maria Lazaretti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Neste livro, Lucinéia Maria Lazaretti aborda não somente a perspectiva biográfica de Daniil Borisovich Elkonin (1904–1984), como também apresenta uma formulação sistematizada da dinâmica do desenvolvimento infantil proposta por esse psi­cólogo soviético que contribuiu sobremaneira para as áreas da Psicologia e da Educação. A autora explora com competência a vida e os escritos de Elkonin, um autor clássico da psicologia sócio-histórica, e intro­duz os leitores na obra desse pensador, há até pouco tempo praticamente desconhecido entre profissionais e acadêmicos. Propõe, antes de tudo, um exercício de reflexão para compreen-der suas produções nas áreas da psicologia e da pedagogia infan­tis. Com isso, contribui para a superação da lacuna bibliográfica sobre esse ilustre (des)conhecido no Brasil e fomenta o interes­se entre os pesquisadores em dar continuidade às reflexões aqui desenvolvidas.', '["history of psychology","sociocultural psychology","historical-cultural psychology","child development","child psychology","pedagogy","Soviet psychology","educational psychology"]', '10.7476/9786557145227', '9786557145227', 'https://books.scielo.org/id/7dgcr', 'https://books.scielo.org/id/7dgcr/pdf/lazaretti-9786557145227.pdf', NULL, 'https://books.scielo.org/id/7dgcr/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7f83x', '7f83x', 'História da saúde no Rio de Janeiro: instituições e patrimônio arquitetônico (1808-1958)', NULL, '["Ângela Porto","Gisèle Sanglard","María Rachel Fróes da Fonseca","Renato da Gama-Rosa Costa"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'História da Saúde no Rio de Janeiro: instituições e patrimônio arquitetônico (1808-1958) é fruto de um projeto coletivo que teve por objetivo principal identificar e tornar público o conjunto de bens edificados que compõem o patrimônio cultural da saúde na cidade. Ao realizarmos a pesquisa da história institucional e arquitetônica de hospitais, instituições de assistência médica e institutos de pesquisa científica criados desde o início do século XIX até meados do XX, procuramos contribuir com ações em torno da preservação do patrimônio científico e cultural da saúde. Muitas das instituições aqui relacionadas já tiveram suas edificações tombadas, outras tantas se encontram em processo de tombamento, sem que isso signifique, no entanto, que estejam devidamente preservadas. A maioria delas ainda não teve esse destino e está desprotegida, ou mesmo descaracterizada em relação ao projeto original; outras tiveram a sede transferida ou, como é o caso da Faculdade de Medicina na Praia Vermelha, totalmente demolida. Este estudo partiu de um levantamento realizado em 1994 pelo arquiteto Benedito Tadeu de Oliveira, do Departamento de Patrimônio Histórico da Casa de Oswaldo Cruz (COC), por Jaime Benchimol e por mim, ambos do Departamento de Pesquisa deste mesmo centro de pesquisa, documentação e informação. Naquele momento, tínhamos como objetivo listar e identificar os edifícios tombados ou em processo de tombamento – nas instâncias municipal, estadual e federal – ligados à saúde na cidade do Rio de Janeiro e, sobretudo, aqueles que se encontravam desprotegidos. Esse levantamento inicial partiu da proposta do prof. Paulo José Pardal, pesquisador, membro do Instituto Histórico e Geográfico Brasileiro (IHGB) e do Instituto Estadual de Patrimônio Cultural (Inepac/RJ), defensor incansável do patrimônio histórico desta cidade, a cuja memória dedicamos este trabalho.', '["history of health","health institutions","architectural heritage","cultural heritage preservation","hospitals","medical institutions","scientific research institutes","Casa de Oswaldo Cruz","heritage listing","Rio de Janeiro"]', '10.7476/9788575415993', '9788575415993', 'https://books.scielo.org/id/7f83x', 'https://books.scielo.org/id/7f83x/pdf/porto-9788575415993.pdf', NULL, 'https://books.scielo.org/id/7f83x/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7frtp', '7frtp', 'Bioética, Saúde e Sociedade', NULL, '["Marisa Palácios"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A coletânea organizada por Marisa Palácios, professora titular da Universidade Federal do Rio de Janeiro (UFRJ), apresenta contribuições e diálogos entre a ética e a saúde pública. As muitas mudanças causadas pelas inovações tecnológicas nas áreas de saúde e, especialmente, na saúde coletiva são debatidas no livro, que reúne textos de especialistas de diversas áreas do conhecimento – Direito, Medicina, Farmácia, Ciências Sociais, Filosofia, Enfermagem, Psicologia – em torno de temas atuais e desafiadores para toda a sociedade. O título contempla oito capítulos, que abordam questões como origens e caminhos para a formação em bioética, objetos de estudo da prática bioética, bioética e saúde pública, atenção primária à saúde, emergências sanitárias, epidemias e pandemias, saúde da família, entre outras.', '["bioethics","public health","health technology innovation","bioethics education","primary care","health emergencies","epidemics and pandemics","family health","health and society"]', '10.7476/9786557080719', '9788575416358', 'https://books.scielo.org/id/7frtp', NULL, NULL, 'https://books.scielo.org/id/7frtp/cover/cover_thumbnail.jpeg', 210, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7fxc2', '7fxc2', 'Zika no Brasil: história recente de uma epidemia', NULL, '["Ilana Löwy"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Mais uma publicação da coleção Temas em Saúde, o livro Zika no Brasil: história recente de uma epidemia apresenta, com linguagem acessível e de forma objetiva, o histórico e as informações mais recentes da comunidade científica sobre o zika vírus. Escrita por Ilana Löwy, historiadora das ciências e pesquisadora do Instituto Nacional Científico e de Pesquisa Médica da França (Inserm), a obra mostra, em quatro capítulos, as muitas faces de um vírus cuja recente epidemia vem se tornando um enorme desafio para os profissionais e gestores da saúde pública no Brasil. Löwy discorre sobre as primeiras epidemias de zika fora do país até os primeiros relatórios sobre a chegada da doença ao Nordeste brasileiro e sua relação com casos de microcefalia, além da ação de órgãos como Ministério da Saúde e Organização Mundial da Saúde (OMS). Os enigmas sobre a doença, que virou um fenômeno global, também são levantados, assim como as muitas variáveis e desigualdades - econômicas, de classe, de raça e de gênero - que compreendem a proliferação do vírus. A autora aborda, com dinamismo, o que ela chama de a rápida ascensão e queda do vírus zika e as muitas perguntas e questões deixadas por esse vírus. "A epidemia brasileira de zika de 2015-2016 foi um episódio curto, intenso e assustador. O surto terminou em 2016, mas não a longo prazo, uma vez que o dano produzido por uma infecção pelo zika vírus persiste na nas crianças afetadas", alerta a pesquisadora.', '["Zika virus","Zika virus outbreak","microcephaly","public health administration","Ministry of Health","World Health Organization","health disparities","social class","race","gender","history of science"]', '10.7476/9786557080634', '9788575416389', 'https://books.scielo.org/id/7fxc2', NULL, NULL, 'https://books.scielo.org/id/7fxc2/cover/cover_thumbnail.jpeg', 171, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7gsjx', '7gsjx', 'O império da ordem: guarda nacional, coronéis e burocratas em Minas Gerais na segunda metade do século XIX (1850-1873)', NULL, '["Flávio Henrique Dias Saldanha"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O autor analisa aqui a permanência, após a mudança das normas de nomeação, do prestígio social dos milicianos civis da Guarda Nacional do Município de Mariana (MG), província com a maior população livre e escrava do Brasil durante a Regência. Naquele período, a milícia prestava serviços não remunerados e utilizando recursos próprios, com base na noção de honra social e no sentimento de obrigação para com o soberano, suprindo a falta de funcionários públicos necessários à manutenção da ordem social. O soberano, em troca, concedia dádivas, honras e mercês aos oficiais. Até a segunda metade do século 19, os oficiais eram escolhidos por meio de eleições em que votavam os próprios milicianos. E, para se tornar miliciano, bastava ao pleiteante ter status de cidadão ativo, ou seja, ter a mínima condição financeira para votar e ser votado nas eleições primárias. Tal sistema era duramente criticado pelas autoridades, que o consideravam potencialmente perigoso, uma vez que possibilitava a indivíduos não brancos, destituídos de status social em uma sociedade escravocrata, exercerem postos de liderança. No entanto, a partir da segunda metade do século 19, quando os movimentos “perturbadores da ordem” se enfraquecem e o Império torna-se pacificado, o Exército ganha importância e projeção e os políticos conservadores reformam a Guarda Nacional, por meio da Lei 602, de 19 de setembro de 1850. Entre outras determinações, essa lei abole o sistema eleitoral, de forma que os oficiais, daí em diante, passaram a ser nomeados pelos presidentes das províncias mediante propostas encaminhadas pelos comandantes locais. Mais do que mero capricho jurídico, a nomeação tinha por finalidade romper com o “ranço democrático” da lei anterior e reafirmar a hierarquização no interior da corporação. O autor sugere que, mesmo com a abolição do pleito eleitoral em 1850, os oficiais continuaram a demonstrar carisma, pois o líder deve provar-se como tal perante seus pares, sob pena de descrédito na sua autoridade.', '["social hierarchy","political patronage","Mariana, Minas Gerais","Brazilian Empire","19th century"]', '10.7476/9786557144862', '9786557144862', 'https://books.scielo.org/id/7gsjx', 'https://books.scielo.org/id/7gsjx/pdf/saldanha-9786557144862.pdf', NULL, 'https://books.scielo.org/id/7gsjx/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7gt99', '7gt99', 'Crise do Brasil arcaico', NULL, '["Juárez Rubens Brandão Lopes"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'other', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta monografia trata das relações industriais em duas comunidades da Zona da Mata mineira, analisadas como parte integrante da organização social das mesmas, e das condições que nelas atuam no sentido da alteração daquelas relações.', '["labor relations","Zona da Mata Mineira","social organization","working conditions","social change"]', '10.7476/9788579820045', '9788579820045', 'https://books.scielo.org/id/7gt99', 'https://static.scielo.org/scielobooks/7gt99/pdf/lopes-9788579820045.pdf', NULL, 'https://books.scielo.org/id/7gt99/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7h7yn', '7h7yn', 'Vírus, mosquitos e modernidade: a febre amarela no Brasil entre ciência e política', NULL, '["Ilana Löwy","Irene Ernest Dias"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A autora não se limita a apresentar a história da febre amarela no Brasil, mas uma reflexão sobre uma fase crucial da história da doença. Para melhor ilustrar essa reflexão, o livro mostra sucessivos cenários que permitem demonstrar as dimensões da transferência de conhecimentos e práticas científicas entre ‘centro’ e ‘periferia’, pois era de fato importante examinar as relações entre o saber científico universal e a percepção da doença tanto pelos pacientes quanto pelos médicos.', '["yellow fever","history of medicine","science and politics","mosquitoes","modernity","knowledge transfer","center-periphery relations","scientific knowledge","illness perception","Brazil"]', '10.7476/9788575412398', '9788575412398', 'https://books.scielo.org/id/7h7yn', 'https://static.scielo.org/scielobooks/7h7yn/pdf/lowy-9788575412398.pdf', NULL, 'https://books.scielo.org/id/7h7yn/cover/cover_thumbnail.jpeg', NULL, 46, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7hbdt', '7hbdt', 'Tecnologia Social: contribuições conceituais e metodológicas', NULL, '["Renato Dagnino"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este segundo volume da Série Tecnologia Social deriva do interesse que o tema tem despertado em professores, estudantes, gestores públicos e participantes de movimentos sociais com quem seu autor vem dialogando. E de sua percepção de que a sociedade mais justa, igualitária e ambientalmente sustentável que desejam demanda uma aliança da comunidade de pesquisa que hegemoniza as políticas cognitivas (da Ciência e Tecnologia e do Ensino) e dos trabalhadores que intentam sair da informalidade para a Economia Solidária. Deter a exclusão que penaliza a maioria da população mundial e caminhar na direção de uma sociedade fundamentada numa outra tecnociência são a raiz dos argumentos sintetizados no conceito de Tecnologia Social. Nas palavras do autor, “o livro visa somar-se ao trabalho de um número crescente de latino-americanos que estão construindo a plataforma cognitiva de lançamento - a Tecnologia Social - de uma nova proposta societária - a Economia Solidária”.', '["social technology","solidarity economy","informal workers","social movements","cognitive science","technology and society","social exclusion","Latin American research","social justice","environmental sustainability"]', '10.7476/9788578793272', '9788578793272', 'https://books.scielo.org/id/7hbdt', 'https://books.scielo.org/id/7hbdt/pdf/dagnino-9788578793272.pdf', NULL, 'https://books.scielo.org/id/7hbdt/cover/cover_thumbnail.jpeg', NULL, 104, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7hf6n', '7hf6n', 'A saúde persecutória: os limites da responsabilidade', NULL, '["Luís David Castiel","Carlos Alvarez Dardet"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Os autores, ao cunharem a expressão ´saúde persecutória´, discutem a “complexa tarefa de avaliar a real efetividade das propostas individualistas hegemônicas de promoção em saúde centradas em evidências científicas” e as conseqüências de uma concepção de promoção e prevenção em saúde que, coerente com o liberalismo, minimiza a dimensão pública da responsabilidade pela saúde dos indivíduos.', '["health promotion","individualism","evidence-based health promotion","liberalism","health prevention"]', '10.7476/9788575412336', '9788575412336', 'https://books.scielo.org/id/7hf6n', 'https://books.scielo.org/id/7hf6n/pdf/castiel-9788575412336.pdf', NULL, 'https://books.scielo.org/id/7hf6n/cover/cover_thumbnail.jpeg', NULL, 57, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7htrv', '7htrv', 'Os delírios da razão: médicos, loucos e hospícios (Rio de Janeiro, 1830 - 1930)', NULL, '["Magalí Gouveia Engel"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2001, '2001-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Trata das idéias e vivências da loucura presentes na cidade do Rio de Janeiro entre 1830 e 1930, período em que foi apropriada e transformada pelos alienistas em doença mental. Por meio da narrativa das várias tramas de personagens famosos por sua vesânia e aprisionados nas malhas da doença mental, a autora delineia um panorama histórico da loucura, passando pela análise das condições de enclausuramento às quais grande parte dos indivíduos suspeitos e/ou diagnosticados como doentes mentais ficariam sujeitos a partir da criação do Hospício de Pedro II. Fundamental para leigos e acadêmicos, assinala o momento em que os médicos brasileiros começariam a reivindicar para si a responsabilidade sobre a loucura, defendendo a necessidade da construção de hospícios onde os alienados mentais pudessem ser recolhidos e tratados convenientemente.', '["madness","history of psychiatry","asylum","mental illness","Rio de Janeiro","physicians","institutionalization","19th century","20th century"]', '10.7476/9788575412534', '9788575412534', 'https://books.scielo.org/id/7htrv', 'https://books.scielo.org/id/7htrv/pdf/engel-9788575412534.pdf', NULL, 'https://books.scielo.org/id/7htrv/cover/cover_thumbnail.jpeg', NULL, 53, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7j8bc', '7j8bc', 'A escola de Minas de Ouro Preto: o peso da glória', NULL, '["José Murilo de Carvalho"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Duas instituições de ensino têm importância decisiva na vida de Minas Gerais: o Caraça e a Escola de Minas de Ouro Preto. Elas realizaram, em certa época, trabalho expressivo em matéria de educação, valendo pelo que foi feito no preparo de pessoal e pelo acento de originalidade dado à vida da área. Daí o seu relevo, justificativo de atenções. Mais que simples escolas, são unidades formadoras de determinada marca regional. Seu estudo se impõe e pode contribuir para esclarecimento da realidade tanto como as notas políticas ou econômicas. E ele vem sendo feito, como se vê pelas obras dedicadas à fixação de trajetórias de escolas e cursos, reveladoras de algo mais que resultado de aulas, ou de centros de investigação.', '["history of education","mining education","regional identity","Ouro Preto","Minas Gerais","educational institutions"]', '10.7476/9788579820052', '9788579820052', 'https://books.scielo.org/id/7j8bc', 'https://books.scielo.org/id/7j8bc/pdf/carvalho-9788579820052.pdf', NULL, 'https://books.scielo.org/id/7j8bc/cover/cover_thumbnail.jpeg', NULL, 40, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7j9qb', '7j9qb', 'O sujeito lírico em Dispersão: aspectos da modernidade na obra de Mário de Sá-Carneiro', NULL, '["Ricardo Marques Martins"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Consciente de que tanto a poesia de Mário de Sá-Carneiro bem como o sujeito lírico que (n)ela (se) constitui não se deixam prender, nem se deixam apreender completamente - mesmo porque ambos estão em Dispersão, como o título da obra estudada já anuncia - Ricardo Marques Martins propõe o poema "A Partida", que abre o volume, como porta de entrada para a discussão de temas caros à modernidade e à poética de Sá-Carneiro: o gênio (e os caracteres da diferença, do isolamento e da criatividade), a composição do delírio poético, a busca do sonho, do Ideal, do Absoluto.', '["Mário de Sá-Carneiro","lyric subject","modernity","poetic genius","dreams","the ideal","the Absolute","difference","isolation","creativity","Portuguese poetry"]', '10.7476/9786557145357', '9786557145357', 'https://books.scielo.org/id/7j9qb', 'https://books.scielo.org/id/7j9qb/pdf/martins-9786557145357.pdf', NULL, 'https://books.scielo.org/id/7j9qb/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7jk4p', '7jk4p', 'Sacrificium Laudis: a hermenêutica da continuidade de Bento XVI e o retorno do catolicismo tradicional (1969-2009)', NULL, '["Juliano Alves Dias"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Nesta obra pretende-se estudar as duas formas rituais da liturgia romana, comparando-as e procurando entender os motivos do cisma, ao mesmo tempo em que se pretende abarcar as ações do atual pontífice e as reações no mundo católico e fora dele. Para tanto, usar-se-á como fonte o Missal tridentino de 1570 e o novo Ordo Missæ de Paulo VI de 1969, bem como os catecismos formulados após os Concílios de Trento (1545-1563) e o Vaticano II (1962-1965), tendo por objetivo comparar suas notificações sobre o culto católico e seu significado. Durante o processo de análise tem-se a intenção de vislumbrar o impacto das mudanças no seio da Igreja, pois constata-se uma espécie de endurecimento no final do pontificado de João Paulo II, com a promulgação de documentos litúrgicos que tendem a criar empecilhos para possíveis abusos durante a missa (Ecclesia de Eucharistia, 2003) - há a retomada e destaque do sentido sacrificial do culto católico e uma série de recomendações impostas pela Congregação do Culto Divino para celebração da missa (Redemptionis Sacramentum, 2004). Fato é que, quarenta anos após o mencionado Concílio Vaticano II e quase quatro décadas de utilização do novo rito da missa, é rara qualquer menção específica na historiografia recente da Igreja sobre o andamento de tal tema. A maioria dos livros de história da Igreja que traça um levantamento de fatos até o Vaticano II, apresentam-no como uma espécie de revolução interna da estrutura eclesiástica sem, contudo, aprofundar o tema ou mostrar as crises na Igreja decorrentes deste.', '["liturgical reform","Ordo Missae","liturgical continuity","Pope Benedict XVI","John Paul II","traditional Catholicism","Catholic liturgy","Second Vatican Council","Council of Trent","liturgical history","Catholic Church"]', '10.7476/9788579831249', '9788579831249', 'https://books.scielo.org/id/7jk4p', 'https://books.scielo.org/id/7jk4p/pdf/dias-9788579831249.pdf', NULL, 'https://books.scielo.org/id/7jk4p/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7jqhc', '7jqhc', 'Reticulados via corpos ciclotômicos', NULL, '["Carina Alves","Antonio Aparecido de Andrade"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Mathematics', 'O primeiro capítulo, assim, introduz osconceitos de módulo, inteiro algébrico, norma e traço de um elemento,discriminante, base integral, anel de Dedekind e outros conceitosindispensáveis ao desenvolvimento dos demais capítulos. Estuda ainda as formas quadráticas, as quais se aplicam para determinar o raio de empacotamento da realização geométricade um ideal em questão. O capítulo 2 apresenta um estudo sobre corpos de números, com ênfase nos anéis dos inteiros e discriminantes de corpos quadráticos e ciclotômicos, além de abordar a decomposição de um ideal primo em uma extensão fazendo uso do Teorema de Kummer. As definições de reticulado, empacotamento esférico, volume e densidade de centro são abordadas no terceiro capítulo, que ainda trata do método de Minkowski para obtenção de reticulados via representação geométrica de ideais dos anéis de inteiros algébricos.', '["lattices","cyclotomic fields","number fields","quadratic fields","algebraic integers","quadratic forms","packing radius","Dedekind domains","integral bases","discriminant","Kummer''s theorem","prime ideal decomposition"]', '10.7476/9788568334393', '9788568334393', 'https://books.scielo.org/id/7jqhc', 'https://books.scielo.org/id/7jqhc/pdf/alves-9788568334393.pdf', NULL, 'https://books.scielo.org/id/7jqhc/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7k4ww', '7k4ww', 'Recampesinização e ressignificação do campesinato: histórias de vida no movimento de mulheres camponesas do Paraná (MMC/PR)', NULL, '["Renata Rocha Gadelha"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Nesta obra, a autora analisa as histórias de vida das camponesas integrantes do Movimento de Mulheres Camponesas, residentes no Reassentamento São Francisco de Assis, em Cascavel (PR), e passa a compreender melhor as mudanças que o movimento trouxe em suas vidas, na transformação de suas consciências, levando à transformação de suas práticas. E, nesse sentido, ela buscou identificar se a participação das mulheres no MMC permitiu que elas pudessem manifestar suas percepções agroecológicas e colocá-las em prática em suas unidades produtivas. Historicamente, as mulheres camponesas são tendencialmente relegadas a uma atuação secundária e dependente dos homens no processo produtivo e nas suas decisões. A partir dessa constatação, a autora percebe a necessidade de ressignificação do conceito de campesinato, com vistas à transição agroecológica. A sua abordagem incorpora a necessidade da superação das relações sociais geradoras de preconceito, de alienação e de dominação nele presentes, que pode influenciar no desenvolvimento das forças produtivas no campo. “Recampesinização e ressignificação do campesinato: histórias de vida no movimento de mulheres camponesas do Paraná (MMC/PR)”, além do texto introdutório e das considerações finais, constitui-se de seis capítulos: Mulheres, agroecologia e desenvolvimento rural sustentável; O patriarcado; Como superar o patriarcado?; O MMC e o Reassentamento São Francisco de Assis; Relações de gênero; Formas de produção.', '["campesinato","peasant women","life history (social science method)","agroecology","patriarchy","gender relations","sustainable rural development","peasant resettlement","Paraná"]', '10.7476/9786550190392', '9786550190415', 'https://books.scielo.org/id/7k4ww', 'https://books.scielo.org/id/7k4ww/pdf/gadelha-9786550190392.pdf', 'https://books.scielo.org/id/7k4ww/epub/gadelha-9786550190392.epub', 'https://books.scielo.org/id/7k4ww/cover/cover_thumbnail.jpeg', 160, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7k98w', '7k98w', 'Imagens, micróbios e espelhos: os sistemas imune e nervoso e nossa relação com o ambiente', NULL, '["Cláudio Tadeu Daniel‐Ribeiro","Yuri Chaves Martins"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"O presente livro trata de paradigmas, protoideias e também de estilos de pensamento, pensamentos coletivos e revoluções científicas. Nele dissertamos sobre assuntos que vão desde as origens do homem e a imprevisibilidade da evolução do conhecimento e da ciência até os conceitos e mecanismos de formação de imagens internas (como em um espelho) para o reconhecimento (da imagem) de objetos do mundo real (incluindo os micróbios). Os textos permeiam tanto narrativas históricas – como a da imunologia cognitiva – quanto a descrição do funcionamento do sistema nervoso. Os tópicos expostos em cada capítulo são explicados ao leitor com a ajuda de conceitos de diferentes disciplinas, muitas vezes estranhas ao pensamento coletivo de cientistas de nossas áreas. Assim, algumas ideias, inicialmente protoideias, demandaram amadurecimento através da interação com especialistas nas diversas disciplinas abordadas. Ao fim de cada capítulo, comentários desses peritos analisam as perspectivas e consequências dos temas tratados, muitas vezes proporcionando um olhar diferente ao oferecido por nós. [...] Esperamos, com esta abordagem interdisciplinar, promover o debate sobre diversos temas tratados entre especialistas de diferentes campos do conhecimento e, quem sabe (quem dera também...), instigar o surgimento de novas revoluções científicas. Seja bem-vindo ao mundo dos micróbios, imagens e espelhos!"', '["immune system","nervous system","microorganisms","mirror metaphor","human-environment relationship","scientific revolution","interdisciplinary research","history of immunology"]', '10.7476/9786557082294', '9786557082294', 'https://books.scielo.org/id/7k98w', 'https://books.scielo.org/id/7k98w/pdf/daniel-ribeiro-9786557082294.pdf', NULL, 'https://books.scielo.org/id/7k98w/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7kcnj', '7kcnj', 'Para além das Colunas de Hércules, uma história da paraconsistência: de Heráclito a Newton da Costa', NULL, '["Evandro Luís Gomes","Ítala M. Loffredo D’Ottaviano"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Computer Science', 'Neste livro, os autores historiam o advento e o paulatino estabelecimento da perspectiva paraconsistente no pensamento ocidental. Num estudo inédito, resgatam e reconstroem os principais argumentos de personagens fundamentais para a constituição dessa perspectiva teórica, desde sua “pré-história” – com Heráclito de Éfeso, Aristóteles e os estoicos; Pedro Abelardo, Pedro Hispano, Guilherme de Ockham e muitos outros – até sua plena configuração no século XX. São assim reconstituídas as ideias de Hegel, Vasiliev, Łukasiewicz entre outros precursores da paraconsistência, culminando na exposição detalhada do contexto da lógica contemporânea, no qual se inserem as contribuições efetivas de Stanisław Jaśkowski e Newton da Costa, que estabeleceram definitivamente o paradigma paraconsistente.', '["paraconsistency","history of logic","paraconsistent logic","Heracleitus","Aristotle","Stoics","Peter Abelard","William of Ockham","Hegel","Łukasiewicz","Newton da Costa","modern logic"]', '10.7476/9788526815001', '9788526813830', 'https://books.scielo.org/id/7kcnj', NULL, NULL, 'https://books.scielo.org/id/7kcnj/cover/cover_thumbnail.jpeg', 712, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7kgxk', '7kgxk', 'As selfies do Instagram: os autorretratos na contemporaneidade', NULL, '["Julianna Nascimento Torezani"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2022, '2022-03-08', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Os autorretratos produzidos através de dispositivos digitais circulam nas redes sociais configurando um novo gênero fotográfico que são as selfies. Dos autorretratos do século XIX ao regime visual da pós-fotografia estas imagens certificam a presença das pessoas nos acontecimentos. Entender a estrutura rizomática do Instagram, as questões estéticas de construção de sentidos e a forma de visibilidade vinculada a sociedade de controle possibilita discutir a fotografia algorítmica que tem instruções e intencionalidades definidas para a vigilância das pessoas pela produção imagética.', '["selfies","Instagram","self-portrait","social media photography","visual regimes","post-photography","society of control","surveillance","visibility","photographic aesthetics","rhizome"]', '10.7476/9786586213720', '9786586213676', 'https://books.scielo.org/id/7kgxk', NULL, NULL, 'https://books.scielo.org/id/7kgxk/cover/cover_thumbnail.jpeg', 340, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7krsh', '7krsh', 'Economia, sociedade e paisagens da Capitania de Ilhéus', NULL, '["Marcelo Henrique Dias"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Trata-se de um estudo nos moldes da História Agrária das diferentes freguesias que integravam o território da capitania e comarca de Ilhéus no período colonial. Abrange, assim, uma gama de temas que compõe o universo da produção rural e dos mecanismos de acesso aos bens necessários para tal fim, como a terra, os recursos florestais e a mão de obra. O leitor encontrará descrições e análises das estruturas agrárias, da população e das paisagens, contando com tabelas, gravuras e mapas que auxiliam na compreensão da formação do território e das opções produtivas correspondentes.', '["agricultural history","colonial Brazil","Ilhéus","rural production","land tenure","land access","forest resources","agricultural labor","agrarian structure","population","territorial formation","landscape"]', '10.7476/9786586213249', '9788574555461', 'https://books.scielo.org/id/7krsh', NULL, NULL, 'https://books.scielo.org/id/7krsh/cover/cover_thumbnail.jpeg', 339, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7mj5q', '7mj5q', 'Pensar junto/fazer com: saúde mental na pandemia de covid-19', NULL, '["Mônica (Molije) Lima","Denise Coutinho","Vânia Bustamante","Suely Aires","Rafael Patiño"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'A obra foca em temas cruciais para as discussões em saúde: desigualdades, vulneração social e saúde mental, modos de vida e cotidianidade, formas participativas de produção de conhecimento e estratégias de mobilização para transformação, tendo como problema e contexto a pandemia da covid-19 . Busca fomentar um movimento maior pela produção da saúde plena junto a grupos da população que mais precisam dela para viver com qualidade de vida, dignidade e equidade.', '["mental health","COVID-19 pandemic","social inequality","social vulnerability","lifestyle","everyday life","participatory knowledge production","mobilization strategies","health equity","quality of life","human dignity"]', '10.7476/9786556305219', '9786556305219', 'https://books.scielo.org/id/7mj5q', 'https://books.scielo.org/id/7mj5q/pdf/lima-9786556305219.pdf', NULL, 'https://books.scielo.org/id/7mj5q/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7mkg8', '7mkg8', 'Prisões numa abordagem interdisciplinar', NULL, '["Maria Thereza Ávila Dantas Coelho","Milton Júlio de Carvalho Filho"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro tem como principal objetivo colaborar com as discussões sobre o sistema prisional brasileiro e a reforma iniciada no século XIX. Resultado das reflexões de pesquisadores de diferentes áreas do conhecimento, os artigos deste livro destinam-se aos estudantes, gestores e trabalhadores que lidam, de alguma forma, com a questão do sistema prisional do Brasil. As abordagens passam por campos como o da Medicina, da Administração e da Sociologia, oferecendo ao leitor a possibilidade de conhecer e questionar aspectos históricos, sociais e econômicos do contexto contemporâneo do sistema prisional brasileiro.', '["Brazilian prison system","prison reform","prison history","prison administration","prison sociology","prison health care"]', '10.7476/9788523217358', '9788523217358', 'https://books.scielo.org/id/7mkg8', 'https://books.scielo.org/id/7mkg8/pdf/coelhos-9788523217358.pdf', NULL, 'https://books.scielo.org/id/7mkg8/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7mpy8', '7mpy8', 'Debate educacional nas origens da “Nova República”: a defesa da escola pública em projetos editoriais de 1978 a 1985', NULL, '["Fabiana de Cássia Rodrigues"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, Fabiana Rodrigues investiga um período luminoso das lutas sociais no país em que emergiram novos sujeitos sociais possibilitando, de modo original, uma perspectiva de democracia a partir dos de baixo – mulheres, negros, camponeses, trabalhadores fabris, moradores de periferias. Faz um primoroso estudo das revistas Ande e Educação & Sociedade, nas quais circularam as principais concepções educacionais presentes nas lutas pela democracia, em confronto com a ditadura empresarial-militar. Com brilhantismo, mostra-nos a riqueza dos densos debates educacionais que revitalizaram a educação popular e estabeleceram balizamentos da escola unitária. É uma obra imprescindível para compreender as raízes dos dilemas da educação no complexo contexto do Brasil de hoje. (Roberto Leher)', '["educational debate","New Republic","public schools","popular education","social movements","military dictatorship","concept of education","women","Black people","peasants","industrial workers"]', '10.7476/9788526816435', '9788526815797', 'https://books.scielo.org/id/7mpy8', NULL, NULL, 'https://books.scielo.org/id/7mpy8/cover/cover_thumbnail.jpeg', 207, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7nrc4', '7nrc4', 'Gabriela baiana de todas as cores', NULL, '["Sônia Regina de Araújo Caldas"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Com todo o carinho e amor: Aos meus pais José Joaquim Borges de Araújo Filho (in memoriam) e Risolêta Lopes Pontes de Araújo pela luz que me indicou o caminho do livro.A Oberdan, meu namorado, pelo amor, companheirismo e comunhão sempre.Aos meus queridos filhos Pablo e Rodrigo, por fazerem a minha vida ter um sentido novo a cada dia. PrefácioNo universo de estudos sobre a obra amadiana, muitos deles já reunidos no acervo da Fundação Casa de Jorge Amado, a presente publicação emerge como um importante testemunho de como a obra pode ser recebida em contextos dos mais diversificados.De autoria da pesquisadora e professora, Sonia Regina Caldas, o ensaio "Gabriela, baiana de todas as cores", resultante da tese de doutorado defendida em agosto 2003, na UFBa, vem, certamente, cumprir o papel de proporcionar aos estudiosos de literatura uma visão pormenorizada das ilustrações e das capas de várias edições do romance "Gabriela, cravo e canela", no Brasil e no mundo.A Fundação Casa de Jorge Amado, que tem como finalidade preservar, organizar, manter e divulgar o acervo documental de seu patrono, vem procurando, desde a sua criação em julho de 1986, incentivar estudos e pesquisas sobre o universo amadiano na certeza de assim estar contribuindo para melhor compreensão e reconhecimento de sua obra, especialmente perante as gerações futuras.Nesse viés, a Fundação se tornou um expressivo centro de produção cultural e editorial, mantendo vínculos com instituições representativas nacionais e internacionais.A Divisão de Pesquisa e Documentação, constituída de cerca de 250.000 documentos, busca atender às múltiplas demandas de utilização do acervo, através de projetos específicos sobre literatura e cultura, apoiando desse modo inúmeras pesquisas que resultaram em alentada produção científica.O grande desafio é promover incessantemente um canal de experiências e de intercâmbios culturais, incentivando e sistematizando a produção de estudos, teses e ensaios realizados a partir da obra amadiana, contribuindo dessa maneira para a divulgação de novas idéias e conceitos, estimulando a formação de uma consciência quanto à importância da literatura para a fixação de uma memória cultural.Desse modo acreditamos que a presente publicação, além do objetivo específico de trazer à tona aspectos inusitados sobre o universo das capas e ilustrações nas diversas edições dos livros de Jorge Amado, através da cuidadosa e extensa pesquisa da professora Sonia Regina Caldas, terá o condão de ampliar o catálogo institucional de estudos e pesquisas, elaborados em torno das obras deste grande escritor baiano, produzidos a partir de documentos do acervo que ele deixou como legado de uma vida inteiramente dedicada à literatura.Salvador, 30 de julho de 2009. Myriam Fraga ApresentaçãoNão sei se ouvi ou li em algum lugar, mas a memória registrou."Como saber o valor do presente sem desembrulhar o pacote?" e Sônia Regina oferece aos leitores sua "Gabriela, Baiana de Todas as Cores", presente que traz implícito um grande desafio: como desembrulhar esta Gabriela que vem, há cinquenta anos, viajando pelo mundo e fazendo girar ao contrário as rodas e engrenagens do progresso?Este livro que me foi dada a honra de apresentar, distinção de uma ex-aluna da Análise do Discurso, é um espaço de reflexão e um movimento de pensamento, aberto ao diálogo, para discussão de como a linguagem das capas de Gabriela, Cravo e Canela das edições brasileiras e estrangeiras funcionam no processo de produção de sentidos dos leitores de diferentes culturas.Assim construiu com maestria seu objeto de estudo e com extrema lucidez, deslizando entre a "luz e a sombra", apresenta a leitura do discurso de quarenta e oito capas do livro Gabriela, Cravo e Canela, mostrando sua interferência no "encontro do leitor com o discurso de origem" pela representação plural da personagem.Estas representações de Gabriela, a pluralidade de tipos e modelos, como escreveu a autora, "podem estar enriquecendo-a mediante a possibilidade de uma modificação infinita..."Será que a Gabriela, do inesquecível Jorge Amado, cobiçada por tantos olhares, não é representação do bem-estar subjetivo das experiências de vida dos "não-civilizados", uma possibilidade de resgatar a condição humana, ameaçada pela privação de prazeres e amarrada à racionalidade que exige pensar antes de agir?Não estaria Gabriela entre os seguidores de Epimeteu (mito recriado e interpretado pelo filósofo renascentista Francis Bacon) que satisfazem a sua índole e preferem fruir o prazer do instante, imersos na pura alegria instintiva de viver?Estes discursos que embalam e porque não dizer embrulham Gabriela são provocativos, instigantes e abrem um novo campo de questões sobre o conhecimento da linguagem, sujeitos e sentidos.Ao leitor caberá a produção de sentidos, ao atravessar este arco-íris de cores múltiplas e cambiantes e as divergências de representações desta misteriosa e indecifrável Gabriela.', '["Jorge Amado","Gabriela, cravo e canela","book illustration","book covers","literary reception"]', '10.7476/9788523209339', '9788523209339', 'https://books.scielo.org/id/7nrc4', 'https://books.scielo.org/id/7nrc4/pdf/caldas-9788523209339.pdf', NULL, 'https://books.scielo.org/id/7nrc4/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7nyjg', '7nyjg', 'Tereza Cristina de Bourbon: uma imperatriz napolitana nos trópicos 1843-1889', NULL, '["Aniello Angelo Avella"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Mais do que tecer uma biografia da terceira e última imperatriz do Brasil, o autor procura mostrar como a soberana foi fundamental para a construção das identidades nacionais da Itália e do Brasil, especialmente por meio do apoio à política de migração italiana no final do século XIX, momento em que a escravidão brasileira era abolida e a necessidade de mão de obra livre aumentava. O resultado contribui para a compreensão do presente dos dois países.', '["Italian migration policy","Italian immigrants in Brazil","national identity","abolition of slavery","free labor","Italian national identity","Brazilian national identity","19th century"]', '10.7476/9788575114445', '9788575113295', 'https://books.scielo.org/id/7nyjg', NULL, NULL, 'https://books.scielo.org/id/7nyjg/cover/cover_thumbnail.jpeg', 240, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7p3wt', '7p3wt', 'Democracia no ensino e nas instituições: a face pedagógica do SUS', NULL, '["Tânia Celeste Matos Nunes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Com um objeto de investigação relevante - a questão da educação/saúde/serviço e o quanto as idéias gerais sobre a educação são balizadoras -, a autora trabalha a trajetória histórico-conceitual de como se desenvolveu a formação de especialistas no campo da saúde pública e apresenta não apenas um resgate da história da saúde pública, mas também da própria história no período recortado para análise - 1970 a 1989. O texto, que tem forte ênfase no contexto político, articula as transformações na formação profissional na área da saúde pública às mudanças políticas que ocorreram no país nesse período e recupera uma base original de documentos servindo-se de trabalhos escritos por muitos dos que se dedicaram a conhecer melhor como o ensino da saúde pública foi se consolidando.', '["health education","public health training","Unified Health System (SUS)","democratic education","history of public health","health policy","professional education"]', '10.7476/9788575415306', '9788575415306', 'https://books.scielo.org/id/7p3wt', 'https://books.scielo.org/id/7p3wt/pdf/nunes-9788575415306.pdf', NULL, 'https://books.scielo.org/id/7p3wt/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7q53f', '7q53f', 'Tabu do corpo', NULL, '["José Carlos Rodrigues"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Publicado pela primeira vez em 1979, tornou-se a primeira publicação brasileira a analisar o corpo como sistema simbólico. Desde então, tem sido referência para várias gerações de cientistas sociais. Trata-se de um livro didático e denso que introduz o leitor aos eixos analíticos básicos para a compreensão da sociedade como um sistema de significações. Expõe, com rara clareza, a leitura estrutural das disposições que constituem a relação Natureza e Cultura, base para leituras dos sentidos do sistema social e de outras oposições: o Sagrado e o Profano; o Distante e o Próximo; o Desvio e a Norma; o Consciente e o Inconsciente. Leitura imprescindível para profissionais que têm no corpo a dimensão de seu ofício, conclui que o corpo é uma filosofia que “abriga em nós um inferno que costumamos ver nos outros: a natureza humana que é estranha aos homens.”', '["body and society","nature and culture","sacred and profane","consciousness and unconscious","social meaning"]', '10.7476/9788575413739', '9788575410899', 'https://books.scielo.org/id/7q53f', NULL, NULL, 'https://books.scielo.org/id/7q53f/cover/cover_thumbnail.jpeg', 156, 103, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7qmnz', '7qmnz', 'Adolpho Lutz Dermatologia e Micologia v.1, Livro 3', NULL, '["Jaime Larry Benchimol","Magali Romero Sá"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Integra a coleção: BENCHIMOL, J. L.; SÁ, M. R. (Org.). Adolpho Lutz: obra completa. Rio de Janeiro: Fiocruz, [2004-200-?]. 4 v.', '["dermatology","mycology","skin diseases","fungal infection","Adolpho Lutz"]', '10.7476/9788575412831', '9788575412831', 'https://books.scielo.org/id/7qmnz', 'https://books.scielo.org/id/7qmnz/pdf/benchimol-9788575412831.pdf', NULL, 'https://books.scielo.org/id/7qmnz/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7qphf', '7qphf', 'Imputación objetiva y responsabilidad penal médica', NULL, '["Francisco Bernate Ochoa"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2010, '2010-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra busca plantear una tesis que permita explicar, de manera sistemática y dogmáticamente fundamentada, la atribución de responsabilidad penal a los profesionales de la salud, a partir del análisis de sentencias de diferentes países, y aplicando la moderna teoría de la imputación objetiva. La presente obra es un tratado de responsabilidad penal médica que explica la teoría de la imputación objetiva, su concepto, fundamentos, corrientes actuales y posibilidades de aplicación, para posteriormente ocuparse de la creación y realización de riesgos, como elementos de la imputación objetiva y aplicar los mismos al ámbito de la responsabilidad médica. Para finalmente presentar la posición de garante del profesional de la salud.', '["objective imputation","criminal liability of physicians","healthcare workers","criminal liability","criminal law doctrine","case law analysis"]', '10.7476/9789585003972', '9789585003972', 'https://books.scielo.org/id/7qphf', 'https://books.scielo.org/id/7qphf/pdf/bernate-9789585003972.pdf', NULL, 'https://books.scielo.org/id/7qphf/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7qwrt', '7qwrt', 'Perspectivas del Derecho ambiental en Colombia', NULL, '["Beatriz Londoño Toro","Gloria Amparo Rodríguez","GIOVANNI JOSÉ HERRERA CARRASCAL"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2006, '2006-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este proyecto responde a un momento histórico de gran importancia, que por supuesto no pudo ser más oportuno. Colombia celebra en el año 2006 los quince años de la promulgación de su Constitución Política, y los cambios trascendentales surgidos a partir de su aplicación han sido prolíficos. Particularmente, el tema ambiental ha sobresalido dentro de las grandes transformaciones del país, y por ello no en vano hoy se afirma que tenemos una verdadera Constitución ecológica. De igual forma, la Facultad de Jurisprudencia de la Universidad del Rosario conmemora los diez años de la creación de la Especialización en Derecho Ambiental, y tal coincidencia histórica fue una motivación adicional para proponer la realización de un análisis de la evolución normativa surtida en este decenio, una evaluación de la gestión ambiental colombiana y de sus distintos impactos en una sociedad que cuenta hoy en día con herramientas constitucionales y legales para la defensa de sus derechos e intereses colectivos.', '["environmental law","Colombian Constitution","constitutional environmental protection","environmental management","collective rights"]', '10.7476/9789585005402', '9789588298184', 'https://books.scielo.org/id/7qwrt', 'https://books.scielo.org/id/7qwrt/pdf/londono-9789585005402.pdf', NULL, 'https://books.scielo.org/id/7qwrt/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7r4j3', '7r4j3', 'Outras Histórias da Educação: do Iluminismo à Indústria Cultural (1823-2005)', NULL, '["Sonia Alem Marrach"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O campo da educação vem se ampliando, abrindo-se para novos temas e novas perspectivas de análise. Na esteira dessas novas possibilidades insere-se esta obra, na qual a educação é vista como parte da história da cultura. Abordando a educação do Iluminismo até a era contemporânea, a autora demonstra como a influência da igreja e da universidade foi suplantada pelos meios de comunicação de massa.', '["history of education","Enlightenment","cultural industries","mass media","church and education","education and culture"]', '10.7476/9788539304431', '9788571399099', 'https://books.scielo.org/id/7r4j3', NULL, NULL, 'https://books.scielo.org/id/7r4j3/cover/cover_thumbnail.jpeg', 286, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7s5bm', '7s5bm', 'Velhice &amp; Sexualidade: tramas da diversidade', NULL, '["Raimunda Silva D''Alencar","Monique Borba Cerqueira"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro tem por objetivo problematizar as questões candentes que tocam o universo da velhice em sua interseção com a sexualidade. Traz análises de como a sexualidade é refletida e concretizada nos significativos dilemas do ser humano no seu ciclo e experiências de vida, da mesma forma que coloca em foco as diferentes estratégias que permitem o exercício da sexualidade nas circunstâncias possíveis. Na velhice, especialmente, a sexualidade ainda é uma questão comumente negligenciada pela sociedade em geral, pouco analisada, pouco conhecida e compreendida pela sociedade, incluindo os próprios idosos', '["old age","sexuality","aging","sexual diversity","older adults","sexuality in later life","social attitudes toward aging"]', '10.7476/9786586213607', '9786586213416', 'https://books.scielo.org/id/7s5bm', NULL, NULL, 'https://books.scielo.org/id/7s5bm/cover/cover_thumbnail.jpeg', 342, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7s5ff', '7s5ff', 'Laurindo Almeida: dos trilhos de Miracatu às trilhas em Hollywood', NULL, '["Alexandre Francischini"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A presente dissertação tem por foco a vida e obra do compositor, arranjador e violonista Laurindo Almeida. Como objetivo geral, foi feito um relato biográfico e contextual que vai desde o seu nascimento no litoral sul do Estado de São Paulo, passando pelo Rio de Janeiro das décadas de 30 e 40, quando, no auge da “Era do Rádio”, trabalhou ao lado de músicos como Carmem Miranda, Pixinguinha, Garoto, Radamés Gnattali e tantos outros, até a sua emigração para os EUA, onde se tornou um dos músicos brasileiros de maior renome no exterior. Como objetivos específicos, buscou-se verificar qual, ou quais, os motivos que teriam levado Laurindo Almeida a não ocupar ainda o seu devido lugar na historiografia da música brasileira. E além disso – devido à controvérsia existente entre os pesquisadores acerca da importância do músico na gênese da concepção musical da Bossa Nova –, por meio da análise de seis composições de sua autoria, buscou-se verificar não somente em que medida Laurindo Almeida foi responsável pelo surgimento desta nova concepção musical que ficaria, anos mais tarde, conhecida como característica da Bossa Nova, mas também tentar definir a sua “identidade musical”. Por último, foi feito o levantamento e a catalogação de sua discografia.', '["bossa nova","Brazilian composers","musical identity","discography","Pixinguinha","Radamés Gnattali","Brazilian popular music"]', '10.7476/9788579830358', '9788579830358', 'https://books.scielo.org/id/7s5ff', 'https://books.scielo.org/id/7s5ff/pdf/francischini-9788579830358.pdf', NULL, 'https://books.scielo.org/id/7s5ff/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7s6w4', '7s6w4', 'Imagem contestada: a guerra do contestado pela escrita do diário da tarde (1912-1916)', NULL, '["Karina Janz Woitowicz"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro contribui para recontar os episódios da Guerra do Contestado, dandodestaque para o modo como os atores e forças sociais foram representados pelojornal ao longo do conflito. Assim, desvenda os significados presentes nosdiscursos jornalísticos a partir de diferentes imagens que fizeram a Guerrapelas páginas da imprensa.(2 lugar no Prêmio Jabuti 2015 na categoria: Comunicação)', '["Contestado War","newspaper representation","news discourse","social representations"]', '10.7476/9788577982127', '9788577982127', 'https://books.scielo.org/id/7s6w4', 'https://books.scielo.org/id/7s6w4/pdf/woitowicz-9788577982127.pdf', NULL, 'https://books.scielo.org/id/7s6w4/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7s773', '7s773', 'Impactos econômicos e financeiros da UNESP para os municípios', NULL, '["José Murari Bovo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Disseminada por todo o Estado de São Paulo, a Universidade Estadual Paulista (UNESP) apresenta características bastante peculiares e desempenha um papel fundamental no dinamismo econômico das cidades onde seus campi estão instalados. Basta citar que os serviços ligados ao trabalho acadêmico efetuado nas 25 unidades da UNESP aqui estudadas contribuíram, em 2001, para manter 7.500 empregos diretos e injetaram na economia desses municípios aproximadamente R$ 650 milhões. Este livro apresenta os resultados do impacto econômico e financeiro da presença da UNESP em 14 municípios do Estado de São Paulo. A pesquisa dimensiona, com dados de 2001, o montante de recursos monetários movimentados pelas unidades universitárias da UNESP neles existentes, avaliando a importância da circulação desses recursos para as cidades onde os campi estão instalados.', '["university economic impact","UNESP","municipal economy","higher education and local economy","São Paulo municipalities"]', '10.7476/9788539303151', '9788571394803', 'https://books.scielo.org/id/7s773', NULL, NULL, 'https://books.scielo.org/id/7s773/cover/cover_thumbnail.jpeg', 150, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7ty5k', '7ty5k', 'A Ciência a Caminho da Roça: imagens das expedições científicas do Instituto Oswaldo Cruz ao interior do Brasil entre 1911 e 1913', 'imagens das expedições científicas do Instituto Oswaldo Cruz ao interior do Brasil entre 1911 e 1913', '["Fundação Oswaldo Cruz. Casa de Oswaldo Cruz"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"Prêmio Werner Klatt de excelência gráfica, na categoria Livros Culturais e de Arte" - Bela e criteriosa seleção de imagens das expedições científicas do Instituto Oswaldo Cruz ao interior do Brasil nos anos de 1911-1913. Ao percorrer extensas áreas da Amazônia e da região Nordeste, os expedicionários não só realizaram o levantamento das condições médico-sanitárias de tais populações, como também possibilitaram um minucioso registro de aspectos geográficos, econômicos e socioculturais dos lugares visitados. Proporciona uma reflexão em torno da linguagem fotográfica que, conjugada à pesquisa sobre a evolução das políticas públicas, revela aspectos originais da memória da saúde e das ciências biomédicas no Brasil.', '["Instituto Oswaldo Cruz","scientific expeditions","photographs","Amazon","Northeast Brazil","public health","history of public health","scientific memory"]', '10.7476/9786557082379', '9786557082379', 'https://books.scielo.org/id/7ty5k', 'https://books.scielo.org/id/7ty5k/pdf/fundacao-9786557082379.pdf', NULL, 'https://books.scielo.org/id/7ty5k/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7wcpn', '7wcpn', 'As Pestes do século XX: tuberculose e Aids no Brasil, uma história comparada', NULL, '["Dilene Raimundo do Nascimento"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro traz um estudo, em perspectiva comparada, da tuberculose e da Aids no Brasil, nas primeiras e últimas décadas do século XX. Resgatando a análise de ensaios anteriores sobre a tuberculose na cidade do Rio de Janeiro, a autora constata a existência de analogias evidentes em relação à Aids tanto do ponto de vista do conhecimento científico e das ações institucionais quanto das construções sociais.', '["tuberculosis","AIDS","history of epidemics","20th century","Rio de Janeiro","social construction of illness","public health centers","Brazil"]', '10.7476/9786557081143', '9786557081143', 'https://books.scielo.org/id/7wcpn', 'https://books.scielo.org/id/7wcpn/pdf/nascimento-9786557081143.pdf', NULL, 'https://books.scielo.org/id/7wcpn/cover/cover_thumbnail.jpeg', NULL, 33, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7wnmw', '7wnmw', 'América Andina: integração regional, segurança e outros olhares', NULL, '["Renata Peixoto de Oliveira","Sílvia Garcia Nogueira","Filipe Reis Melo"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'periódicos sobre os temas acima citados.', '["Andean region","regional integration","security","Andean studies"]', '10.7476/9788578791858', '9788578791858', 'https://books.scielo.org/id/7wnmw', 'https://books.scielo.org/id/7wnmw/pdf/oliveira-9788578791858.pdf', NULL, 'https://books.scielo.org/id/7wnmw/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7x379', '7x379', 'Qual literatura? Diferentes perspectivas da produção literária para crianças e jovens na contemporaneidade', NULL, '["Carlos Augusto Novais","Hércules Tôledo Corrêa","Josiley Francisco de Souza","Maria Elisa de Araújo Grossi"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Nesta obra, estão reunidos os textos produzidos para o X Jogo do Livro Infantil e Juvenil: Qual Literatura?, realizado em 2013 pelo Grupo de Pesquisa do Letramento Literário (GPELL) do Centro de Alfabetização, Leitura e Escrita (Ceale), órgão complementar da Faculdade de Educação da Universidade Federal de Minas Gerais (FaE/UFMG) que se interessa pelas práticas sociais de leitura e de escrita presentes em instâncias sociais de produção, circulação e recepção de livros. O evento teve como base a pesquisa “Produção literária para crianças e jovens no Brasil: perfil e desdobramentos textuais e paratextuais”, investigação de âmbito interinstitucional que surgiu a partir da avaliação da produção literária para crianças e jovens divulgada, anualmente, no Brasil. Os textos desta publicação foram produzidos com base no objetivo central do evento: estabelecer uma ampla discussão a respeito do movimento contemporâneo de produção brasileira de textos literários, seus leitores, a multiplicidade de leituras literárias, as pesquisas sobre a literatura e a leitura literária e suas relações com a escola.', '["children''s literature","young adult literature","literary production","contemporary Brazilian literature","literary literacy","reading practices","social practices of reading and writing","paratext","literary readers","literary reception"]', '10.7476/9786558580478', '9786558580089', 'https://books.scielo.org/id/7x379', NULL, NULL, 'https://books.scielo.org/id/7x379/cover/cover_thumbnail.jpeg', 216, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
