INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7y9t3', '7y9t3', 'Polímeros biodegradáveis: tipos, mecanismos, normas e mercado mundial', NULL, '["Guilhermino J. M. Fechine"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Materials Science', '[RETIRADO/WITHDRAWN] Este livro traz, de forma didática e ilustrativa, informações dos diferentes tipos de polímeros biodegradáveis (naturais e sintéticos) e colabora para um maior entendimento a respeito dos biodegradativos sofridos por esses polímeros. Também apresenta as principais normas nacionais e internacionais que avaliam a biodegradabilidade dos polímeros, destacando suas particularidades. Além disso, faz uma avaliação do mercado mundial dos polímeros biodegradáveis.', '["biodegradable polymers","natural polymers","synthetic polymers","biodegradation mechanisms","international standards"]', '10.7476/9788582932605', '9788582932605', 'https://books.scielo.org/id/7y9t3', NULL, NULL, 'https://books.scielo.org/id/7y9t3/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7yddh', '7yddh', 'Políticas de segurança pública no estado de São Paulo: situações e perspectivas a partir das pesquisas do Observatório de Segurança Pública da UNESP', NULL, '["Luís Antônio Francisco de Souza"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Após o processo de retomada da democracia, que ocorreu durante as duas últimas décadas, as sociedades latino-americanas têm experimentado um crescimento preocupante das desigualdades sociais, dos confl itos urbanos e rurais, da luta por direitos.Esse crescimento acompanha de perto o processo de ampliação do repertório de garantias constitucionais e jurídicas oferecidas pelo Estado Democrático de Direito.E mais do que isso, parece que os governos democráticos no subcontinente não têm sido capazes de reverter o quadro histórico de discriminação, pobreza e estagnação econômica existente nesses países.Ao contrário, as agências do poder público parecem oferecer enorme resistência às transformações democráticas.No Brasil, assim como em quase toda a América Latina, segundo Guillermo O''Donnell (1999), encontramos uma inquietante inversão do esquema dos direitos.Os Direitos Políticos (eleições diretas, direito de voto, direito de ser eleito, constituição de partidos e de associações políticas, direito de imprensa) e sociais (direitos trabalhistas, direito à educação, à saúde e à habitação) estão razoavelmente legitimados, a despeito das difi culdades em torno de sua implementação.', '["public security policy","São Paulo state","democratic transition","social inequality","constitutional guarantees","democratic backsliding","Latin America","political rights","social rights"]', '10.7476/9788579830198', '9788579830198', 'https://books.scielo.org/id/7yddh', 'https://books.scielo.org/id/7yddh/pdf/souza-9788579830198.pdf', NULL, 'https://books.scielo.org/id/7yddh/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7yzrw', '7yzrw', 'Impactos da Violência na Saúde', NULL, '["Kathie Njaine","Simone Gonçalves de Assis","Patrícia Constantino"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Todos nós brasileiros somos carne da carne daqueles pretos e índios supliciados.Todos nós brasileiros somos, por igual, a mão possessa que os supliciou.A doçura mais terna e a crueldade mais atroz aqui se conjugaram para fazer de nós a gente sofrida que somos e a gente insensível e brutal, que também somos.Descendentes de escravos e de senhores de escravos seremos sempre servos da malignidade destilada e instalada em nós, tanto pelo sentimento da dor intencionalmente produzida para doer mais, quanto pelo exercício da brutalidade sobre homens, sobre mulheres, sobre crianças convertidas em pasto de nossa fúria.', '["violence","slavery","racism","racial inequality"]', '10.7476/9788575415887', '9788575415887', 'https://books.scielo.org/id/7yzrw', 'https://books.scielo.org/id/7yzrw/pdf/njaine-9788575415887.pdf', NULL, 'https://books.scielo.org/id/7yzrw/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7z56d', '7z56d', 'Algumas abordagens da educação sexual na deficiência intelectual', NULL, '["Lília Maria de Azevedo Moreira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Esta obra apresenta questões importantes e discute tabus sobre o desenvolvimento sexual de pessoas com deficiência intelectual. Acreditando na prática interdisciplinar, busca contribuir para uma melhoria na prevenção, qualidade de vida e adaptação social da pessoa com deficiência mental. Para sua elaboração, a autora contou com algumas referências bibliográficas pertinentes ao tema, relatos de experiências pedagógicas diversas e a própria experiência adquirida ao longo de sua carreira acadêmica.', '["sex education","intellectual disability","mental disability","sexual development","taboos","prevention","quality of life","social adaptation","interdisciplinary approach"]', '10.7476/9788523211578', '9788523211578', 'https://books.scielo.org/id/7z56d', 'https://books.scielo.org/id/7z56d/pdf/moreira-9788523211578.pdf', NULL, 'https://books.scielo.org/id/7z56d/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7zp2y', '7zp2y', 'Narrativas em Saúde Coletiva: memória, método e discurso', NULL, '["Roger Flores Ceccon","Carlos García","João Matheus Acosta Dallmann","Virgínia de Menezes Portes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-07-06', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro ressalta a importância da produção narrativa no campo da saúde coletiva, especialmente no contexto brasileiro. Escrita por quatro pesquisadores da Universidade Federal de Santa Catarina (UFSC), a obra se propõe a ampliar a reflexão de temas em saúde, fornecendo um panorama de conceitos e conteúdos para reafirmar a importância das narrativas no âmbito do trabalho e da educação em saúde coletiva. Em seis capítulos, os autores apostam na potência das narrativas como prática social e individual, destacando também dois componentes fundamentais no ato de narrar experiências e acontecimentos: memória e discurso. "No âmbito da pesquisa científica em saúde coletiva, o modo de narrar pode auxiliar na compreensão dos problemas relacionados a necessidades da população", afirmam.', '["health narratives","collective health","memory","discourse","health education","social practices"]', '10.7476/9786557081617', '9786557081242', 'https://books.scielo.org/id/7zp2y', NULL, NULL, 'https://books.scielo.org/id/7zp2y/cover/cover_thumbnail.jpeg', 128, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-7zrvf', '7zrvf', 'Sonhos da diamba, controles do cotidiano: uma história da criminalização da maconha no Brasil republicano', NULL, '["Jorge Emanuel Luz de Souza"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A cannabis sativa, chamada popularmente de maconha, tem hoje seu cultivo e consumo proibidos no Brasil. Sua legalização vem sendo discutida em diversos meios de comunicação, entre juristas e médicos, políticos e eleitores. Neste livro, o autor revira arquivos históricos, a fim de investigar a forma com que a guerra às drogas e a proibição da erva afetou a sociedade brasileira na história recente. O texto reflete a política higienista adotada pelos governos ao longo dos anos, reavaliando o pensamento proibicionista da droga.', '["cannabis","drug prohibition","war on drugs","drug policy history","hygienism","Brazilian Republic","cannabis legalization","everyday life"]', '10.7476/9788523220235', '9788523220235', 'https://books.scielo.org/id/7zrvf', 'https://books.scielo.org/id/7zrvf/pdf/souza-9788523220235.pdf', NULL, 'https://books.scielo.org/id/7zrvf/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-82r9t', '82r9t', 'O judiciário em debate', NULL, '["Maria Tereza Sadek"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A pesquisa foi realizada no segundo semestre de 1993 por uma equipe coordenada por Maria Tereza Sadek e integrada por Rogério Bastos Arantes, Maria da Glória Bonelli, Gessé Marques Jr. e Fábio José Kerche Nunes. Foram entrevistados cerca de 20% dos juízes em cinco estados – São Paulo, Rio Grande do Sul, Paraná, Goiás e Pernambuco – e mais 41 da Justiça Federal, totalizando 570 entrevistas, observando-se rigorosa proporcionalidade em relação à distribuição dos mesmos entre as instâncias e entrâncias existentes em cada estado. A escolha daqueles cinco estados teve como objetivo representar a diversidade regional do país e eventuais singularidades na composição ou na atuação da magistratura.', '["judiciary","judges","court composition","judicial behavior","federal courts","state courts","regional variation"]', '10.7476/9788579820342', '9788579820342', 'https://books.scielo.org/id/82r9t', 'https://books.scielo.org/id/82r9t/pdf/sadek-9788579820342.pdf', NULL, 'https://books.scielo.org/id/82r9t/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8327j', '8327j', 'Iluminismo e Império no Brasil: O Patriota (1813-1814)', NULL, '["Lorelai Kuri"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra é composta por cinco artigos de renomados historiadores nacionais sobre O Patriota, primeiro jornal brasileiro a publicar artigos literários, políticos e mercantis nos anos de 1813 e 1814. Além do livro, o leitor recebe o CD-ROM com a coleção integral de O Patriota.', '["Brazilian Empire","political journalism","literary journalism","Brazilian independence"]', '10.7476/9788575416037', '9788575416037', 'https://books.scielo.org/id/8327j', 'https://books.scielo.org/id/8327j/pdf/kury-9788575416037.pdf', NULL, 'https://books.scielo.org/id/8327j/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-83c95', '83c95', 'Governança de territórios em desenvolvimentos desiguais: uma análise crítica', NULL, '["Élson Luciano Silva Pires"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O presente livro trata de compreender o conceito de governança territorial e propor uma comparação do funcionamento de governança encontradas em São Paulo com as similares praticadas nos estados de Minas Gerais e Bahia, a partir de uma análise precisa, documentada, circunstanciada e atualizada da situação, para debater as estratégias adotadas e os desafios encontrados nesses estados, com foco na coordenação subnacional de processos desiguais de desenvolvimento local e regional, que se esperava fossem integrados e sustentáveis. Ao valorizar as entrevistas e ouvir os posicionamentos de técnicos de secretarias estaduais e municipais, mormente dos atores sociais e agentes econômicos sobre a efetiva participação dos agentes na governança, este livro pode contribuir para uma avaliação menos dicotômica entre forças e fraquezas, avanços e retrocessos, na medida em que permite enfatizar a complexidade em torno de projetos distintos de desenvolvimento que se entrecruzam nas diferentes modalidades de governança estudadas.', '["territorial governance","uneven development","local and regional development","sustainable development","social participation","São Paulo","Minas Gerais","Bahia","development projects","state and local government"]', '10.7476/9786559542529', '9786559542529', 'https://books.scielo.org/id/83c95', 'https://books.scielo.org/id/83c95/pdf/pires-9786559542529.pdf', NULL, 'https://books.scielo.org/id/83c95/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-83rmh', '83rmh', 'Rumores de festa: o sagrado e o profano na Bahia', NULL, '["Ordep José Trindade Serra"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esse livro aborda o cambiante movimento das festas populares baianas, um fenômeno que hoje suscita grande interesse de estudiosos e do público em geral. Ele chama a atenção para transformações, fazendo referências a etapas anteriores e esboçando tentativas de sondar desenvolvimentos futuros. Preenche importante lacuna na bibliografia acerca do tema abordado.', '["popular festivals","Bahia","sacred and profane","religious festivals","festival transformation","popular culture","Afro-Brazilian religions"]', '10.7476/9788523212315', '9788523212315', 'https://books.scielo.org/id/83rmh', 'https://books.scielo.org/id/83rmh/pdf/serra-9788523212315.pdf', NULL, 'https://books.scielo.org/id/83rmh/cover/cover_thumbnail.jpeg', NULL, 35, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-83xzk', '83xzk', 'Dramaturgias de desvio', NULL, '["João Alberto Lima Sanches"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'João Sanches discute nesta obra as estratégias de autores contemporâneos a partir da análise de 100 peças encenadas no Brasil no início do século XXI. Baseando-se na noção de desvio-formulação de Jean-Pierre Sarrazac que, por sua vez, inspira-se na proposta de leveza do escritor Italo Calvino - Sanches desenvolve uma reflexão original sobre a diversidade da dramaturgia contemporânea. Seu texto dedica-se sobretudo à compreensão das práticas artísticas que não se enquadram nos padrões estabelecidos em qualquer contexto histórico e social. Reconhecendo o desvio (a autorreflexão, a diferença, a mudança de perspectiva) como estratégia de construção da intriga, mas também como alegoria da relação do artista com a realidade, este livro aponta para uma multiplicidade de tradições, formas e possibilidades do drama.', '["dramaturgy","deviation","Jean-Pierre Sarrazac","Italo Calvino","lightness","self-reflexivity","difference","perspective","plot construction"]', '10.7476/9786556308906', '9786556305448', 'https://books.scielo.org/id/83xzk', NULL, NULL, 'https://books.scielo.org/id/83xzk/cover/cover_thumbnail.jpeg', 350, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-84pyk', '84pyk', 'Dramaturgos, críticos e ratos: reflexões sobre o teatro em Edgar Allan Poe', NULL, '["Jéssica Cristina Jardim"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Bernard Shaw perguntou, certa vez, se os Estados Unidos de Edgar Allan Poe alguma vez já existiram ou se foram tão-somente elaborados pela extraordinária imaginação poética do escritor. Autor de obra singular em seu tempo, célebre pelos contos detetivescos, de terror e de morte e pela notável obra poética, como o célebre poema “O corvo”, Poe é abordado neste livro em sua faceta menos conhecida: o crítico de teatro e dramaturgo. Jéssica Cristina Jardim discorre sobre as influências que a arte dramática teria exercido na obra e no pensamento do escritor, revisitando momentos centrais da história do teatro nos Estados Unidos e localizando a produção artística e intelectual do autor como afluente dos nacionalismos que se formam no curso do século XIX. Em muitos momentos, a produção crítica de Poe busca responder à pergunta: afinal, como conciliar as heranças culturais inevitavelmente vindas da Inglaterra com a formação de uma literatura e de um teatro nacionais? Assim, se por um lado, os Estados Unidos presentes em sua obra ficcional foram, talvez, insuperáveis em termos imaginativos, não podemos, por outro lado, negar a Poe seu engajamento com uma das inquietações mais importantes de seu tempo.', '["Edgar Allan Poe","American theater","theatre criticism","dramaturgy","national identity","nationalism","national literature"]', '10.7476/9786557140130', '9786557140130', 'https://books.scielo.org/id/84pyk', 'https://books.scielo.org/id/84pyk/pdf/jardim-9786557140130.pdf', NULL, 'https://books.scielo.org/id/84pyk/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8532r', '8532r', 'Diplomas e decá: identificação religiosa de membros de classe média no candomblé', NULL, '["Luciana Duccini"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'de classe média no candomblé / Luciana Duccini.', '["Candomblé","religious identity","middle class","Afro-Brazilian religions","religious affiliation"]', '10.7476/9788523220112', '9788523220112', 'https://books.scielo.org/id/8532r', 'https://books.scielo.org/id/8532r/pdf/duccini-9788523220112.pdf', NULL, 'https://books.scielo.org/id/8532r/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-85fqc', '85fqc', 'Educação ambiental e valores na escola: buscando espaços, investindo em novos tempos', NULL, '["Dalva Maria Bianchini Bonotto","Maria Bernadete Sarti da Silva Carvalho"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Este livro apresenta o resultado de parte dos trabalhos desenvolvidos que têm se voltado à formação continuada de professores com a finalidade de subsidiar práticas pedagógicas que contribuam com o trabalho educativo vinculado à temática da Educação Ambiental e o trabalho com valores. Articulada a essa tarefa, nos propomos a investigar como se dá tal formação e a prática docente no contexto da escola pública e das reais condições de trabalho do professor. Ao envolver os professores da universidade, da escola de educação básica e também graduandos e pós-graduandos, o desenho do projeto vem propiciando um entrelaçamento profícuo de experiências entre esses diferentes protagonistas e, portanto, a formação de todo o grupo. Essa publicação é fruto das atividades realizadas pelo grupo constituído no ano de 2013, abrangendo os projetos de ensino desenvolvidos durante o processo formativo e reflexões realizadas a partir dessa experiência. Com ela ressaltamos nossa luta pelo resgate do professor como um profissional autônomo, crítico, criativo, que se dispõe a aprender com as reflexões sobre a prática que inventa e não somente reproduz.', '["environmental education","values education","continuing teacher education","teaching practice","public schools","teacher working conditions","teacher autonomy","reflective practice","university-school partnership","educational project"]', '10.7476/9788579837623', '9788579837623', 'https://books.scielo.org/id/85fqc', 'https://books.scielo.org/id/85fqc/pdf/bonotto-9788579837623.pdf', NULL, 'https://books.scielo.org/id/85fqc/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-85pnz', '85pnz', 'Abastecimento alimentar: redes alternativas e mercados institucionais', NULL, '["Julian Perez-Cassarino","Rozane Márcia Triches","José Giacomo Baccarin","Carla Rosane Paz Arruda Téo"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra trata do tema “abastecimento alimentar”, buscando enfatizar as redes alimentares alternativas que vêm se constituindo como um contramovimento ao sistema agroalimentar dominante. Os textos que a constituem envolvem pesquisas realizadas pelos organizadores e autores, os quais representam a Universidade Federal da Fronteira Sul (UFFS), a Universidade de Cabo Verde (Uni-CV) e a Universidad de la República Uruguay (Udelar), além de outras instituições brasileiras. A obra divide-se em três partes: a primeira introduz as discussões sobre a sustentabilidade do sistema alimentar, as formas alternativas de abastecimento e as políticas brasileiras para o setor; a segunda aborda os mercados institucionais, principalmente o caso do Programa Nacional de Alimentação Escolar e o do Programa de Aquisição de Alimentos, assim como experiências nesse sentido em Cabo Verde e no Uruguai; a terceira parte apresenta experiências brasileiras e uruguaias de redes alternativas de abastecimento alimentar e de consumo responsável e comercialização de produtos orgânicos/agroecológicos.', '["food supply","alternative food networks","institutional markets","food system sustainability","agri-food systems","National School Feeding Program","food acquisition program","responsible consumption","organic products","agroecology","food policy","Brazil"]', '10.7476/9788564905726', '9788564905726', 'https://books.scielo.org/id/85pnz', 'https://books.scielo.org/id/85pnz/pdf/perez-9788564905726.pdf', NULL, 'https://books.scielo.org/id/85pnz/cover/cover_thumbnail.jpeg', NULL, 24, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-85v2w', '85v2w', 'Própolis e geoprópolis: uma herança das abelhas', NULL, '["José Maurício Sforcin","Bruno José Conti","Karina Basso Santiago","Eliza de Oliveira Cardoso","Fernanda Lopes Conte","Lucas Pires Garcia Oliveira","Maria José Abigail Mendes Araújo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'As abelhas são observadas pelo ser humano desde a Antiguidade. Elas atuam como agentes determinantes na polinização de muitas espécies vegetais e, desse modo, desempenham papel fundamental na preservação da diversidade de plantas floríferas e asseguram a produção mundial de alimentos. Atualmente, elas também têm importância econômica, pois são essenciais para a apicultura. Neste livro, diversos especialistas apresentam novas investigações sobre o potencial biológico de dois importantes produtos dessa indústria: a própolis e a geoprópolis. A própolis é um material resinoso, produzido por abelhas africanizadas e por abelhas sem ferrão (meliponíneos) e apresenta inúmeras propriedades biológicas. A geoprópolis é produzida por abelhas indígenas ou sem ferrão e é ainda pouco conhecida pela comunidade geral. O leitor acadêmico ou leigo encontrará aqui reunidas informações sobre essas abelhas e atividades biológicas, efeitos colaterais, recomendações de uso, versões comerciais disponíveis e novas estratégias terapêuticas desses produtos.', '["propolis","geopropolis","bees","Africanized honey bees","stingless bees","beekeeping","pollination","plant diversity conservation","adverse effects","treatment options","honey bee products"]', '10.7476/9788595461819', '9788595461819', 'https://books.scielo.org/id/85v2w', 'https://books.scielo.org/id/85v2w/pdf/sforcin-9788595461819', NULL, 'https://books.scielo.org/id/85v2w/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-87nk8', '87nk8', 'Asociatividad territorial: enfoque comparado y análisis en el nuevo contexto de la organización territorial colombiana', NULL, '["Liliana Estupiñán Achury","Manuel Alberto Restrepo Medina"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2013, '2013-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"La presente obra colectiva contiene un análisis del concepto de asociatividad territorial, tanto desde una perspectiva comparada como dentro del nuevo contexto de la organización territorial del Estado colombiano, a propósito de la expedición de la Ley 1454 de 2011. La mirada comparada da cuenta del desarrollo del principio de asociatividad en diversos Estados europeos, tanto federales, regionales y unitarios, así como su impulso en algunos Estados latinoamericanos. Por su parte, el componente colombiano profundiza en el concepto de asociatividad territorial desde distintas miradas: histórica, constitucional y legal, y presenta diversos escenarios para su desarrollo y concreción. Sin duda, es una obra original e innovadora que aporta significativamente al entendimiento de la organización del territorio en Colombia."', '["territorial organization","comparative constitutional law","territorial associations","federalism","regionalism","Colombian constitutional law"]', '10.7476/9789587842098', '9789587384048', 'https://books.scielo.org/id/87nk8', NULL, NULL, 'https://books.scielo.org/id/87nk8/cover/cover_thumbnail.jpeg', 337, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-87st3', '87st3', 'A língua espanhola na Fronteira Sul: trajetórias de ensino, pesquisa, extensão e cultura', 'trajetórias de ensino, pesquisa, extensão e cultura', '["Marilene Aparecida Lemos","Naiane Carolina Menta Três"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Organizado em quatro seções – Práticas de ensino da língua espanhola; Projetos e interações com a comunidade; Nossas pesquisas em/sobre língua espanhola; A língua espanhola no campus Realeza: reflexões de egressos – que se constituem de 11 capítulos, este livro foi planejado como uma forma de publicização de práticas desenvolvidas ao longo dos mais de dez anos de história do Curso de Graduação em Letras Português e Espanhol – Licenciatura, da Universidade Federal da Fronteira Sul (UFFS) Campus Realeza (PR). Apresenta também o texto "La vivencia de la interrelación fronteriza: construir un futuro a partir de la experiencia del intercambio", da convidada especial Maria Soledad Neis e a homenagem póstuma a Leila Carla Lassig, cuja autoria é das organizadoras, Marilene Aparecida Lemos e Naiane Carolina Menta Tres. "A língua espanhola na Fronteira Sul: trajetórias de ensino, pesquisa, extensão e cultura", segundo suas organizadoras, oportuniza ao(à) leitor(a) conhecer e/ou aprofundar-se em inquietações inerentes à docência da língua espanhola no Brasil, aproximando-se dessa fronteira na e sobre a qual foi pesquisado.', '["Spanish language teaching","borderlands","Universidade Federal da Fronteira Sul","community participation","university extension","language studies","alumni reflections","border experience","cultural exchange"]', '10.7476/9786550191061', '9786550191054', 'https://books.scielo.org/id/87st3', 'https://books.scielo.org/id/87st3/pdf/lemos-9786550191061.pdf', NULL, 'https://books.scielo.org/id/87st3/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-886qz', '886qz', 'Psicologia e práticas sociais', NULL, '["Andréa Vieira Zanella","Maria Juracy Toneli Siqueira","Louise Amaral Lhullier","Susana Inês Molon"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Nos dias 29, 30 e 31 de agosto de 1996 realizou-se, em Florianópolis, na Universidade Federal de Santa Catarina, o VI Encontro Regional-Sul da ABRAPSO (Associação Brasileira de Psicologia Social), encontro este que teve como tema central: “Psicologia e Práticas Sociais”. Foram efetivadas, aproximadamente, 400 inscrições, sendo que 150 trabalhos foram apresentados nos diversos G.Ts. (Grupos de Trabalho) ou no formato de pôsteres. Estes números, bem como o total de artigos (60) enviados para análise com finalidade de publicação no presente livro, ultrapassaram as expectativas da Comissão Organizadora, atestando a credibilidade conquistada pela ABRAPSO no contexto da Psicologia contemporânea. [trecho retirado da Apresentação do livro]', '["social psychology","social practices","Florianópolis"]', '10.7476/9788599662878', '9788599662878', 'https://books.scielo.org/id/886qz', 'https://books.scielo.org/id/886qz/pdf/zanella-9788599662878.pdf', NULL, 'https://books.scielo.org/id/886qz/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-889m2', '889m2', 'Epidemiologia, serviços e tecnologias em saúde', NULL, '["Maurício L. Barreto","Naomar de Almeida Filho","Renato Peixoto Veras","Rita Barradas Barata"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1998, '1998-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'APRESENTAÇΓO A epidemiologia tem se mostrado, ao longo de sua história, um impor tante e potente instrumento para identificar e solucionar os problemas de saúde das populaçυes.Fazem parte deste movimento a definição de necessi dades, o planejamento e a avaliação dos serviços de saúde.Todo este esforço de organizar serviços e desenvolver novas tecnologias pode ser entendido como a forma encontrada pelas sociedades para compreender suas doenças e montar as estratégias para enfrentá-las.Os serviços de saúde devem ser vistos como um conjunto de esforços socialmente organizados para enfrentar os fatores geradores das doenças ou, pelo menos, minimizar seus males.Entre tanto, ao longo da história, acumula-se um profícuo debate sobre o verdadei ro resultado destes esforços em, efetivamente, modificar as condiçυes de saú de das populaçυes.Hoje está claro que parte das atividades realizadas no siste ma de saúde tem baixa ou nenhuma efetividade (quando não efeitos negati vos).Outra parte, ainda que possa ser efetiva, necessita de permanentes ade quaçυes para amplificar os seus efeitos.O sistema de saúde é um complexo que inclui intensos esforços de desenvolvimento científico e tecnológico, passando pelo processo de produ ção industrial e, por fim, pela organização dos seus produtos em unidades (simples ou complexas) prestadoras de serviços ŕs sociedades.Na perspectiva epidemiológica, deve ser entendido como um potencial modificador das con diçυes de saúde da população.Apesar de buscar sempre efeitos benéficos, não raras vezes gera efeitos indesejáveis.Neste contexto, a função da epidemiolo gia pode ser dividida em duas grandes perspectivas: contribuir para os ajustes internos do sistema -atuando na seleção de tecnologias e processos com maior efetividade, ajudando, também, a ampliá-la -e auxiliar na compreensão de problemas e necessidades de saúde que este sistema deve priorizar, medin do seu impacto sobre a saúde global das populaçυes.Umas das críticas ŕ epidemiologia está calcada em suas relaçυes com as práticas da saúde publica.Verificou-se que parte do conhecimento produzido sobre as populaçυes é inadequado, invalidando as proposiçυes de prevenção dele derivadas.Apesar de desempenhar um papel primordial na pesquisa so bre saúde da população, a epidemiologia nem sempre foi alicerce para desen volver os conhecimentos necessários para fundamentar as práticas de promo ção a saúde, tampouco para conduzir mudanças necessárias na organização dos serviços de saúde (Dean & Kuster, 1996).No campo da avaliação, as contribuiçυes da epidemiologia, apesar de relevantes, tκm ainda muitas limitaçυes.A capacidade de produzir e colocar em uso novas tecnologias voltadas para o cuidado ŕ saúde (drogas, aparelhos, procedimentos e sistemas organizacionais para a atenção ŕ saúde) tem cresci do exponencialmente.Ao lado do potencial de cura ou de prevenção (nem sempre confirmado) e dos efeitos indesejáveis destas tecnologias estão seus altos e crescentes custos, razão de preocupação de todos aqueles com alguma responsabilidade sobre a saúde dos indivíduos ou das populaçυes.Há, na vi são de progresso social, a idéia equivocada de que ele seja conseqüκncia da assimilação de novas tecnologias, deixando-se de lado, inclusive, os seus efei tos diretos como geradoras de doenças.No campo da saúde, pairam grandes dúvidas sobre a importβncia destas tecnologias como modificadoras das condiçυes de saúde das popu laçυes.Tκm-se buscado várias estratégias para demonstrar o quanto as tecnologias, açυes e serviços de saúde podem ser eficazes ou efetivas.Po rém, há evidκncias de que parte importante delas, apesar de em uso cor rente, não foi adequadamente avaliada.Os fatores que contribuem para isto são: a imensa e exponencialmente crescente quantidade de tecnologi¬ as disponíveis, altos custos de um adequado processo de avaliação, falta de interesse dos produtores, incertezas sobre a extrapolação dos estudos de efi cácia para outras populaçυes e insuficiκncias de ordem metodológicascomo a falta de desenhos que permitam avaliaçυes objetivas de certas tec nologias (United States, 1994).Os ensaios aleatorizados, a mais elaborada avaliação disponível (Power, Tunis & Wagner, 1994) -para alguns, o mo delo de referκncia na investigação epidemiológica -apresentam, com freqüκncia, resultados discordantes, mesmo quando tκm como base dese nhos e tamanhos amostrais que lhes garantiriam confiabilidade.Metódos observacionais e os quase-experimentos disponíveis nem sempre conse guem responder ŕs questυes apresentadas.Mesmo com todo o esforço de avaliação, ainda não foi possível superar os problemas inerentes ŕ definição da eficácia das tecnologias.As limitaçυes relativas ŕ avaliação da efetividade são ainda maiores.Mesmo tendo níveis aceitáveis de eficácia, quando analisadas isoladamente, muitas das tecnologias são pouco efetivas quando utilizadas como parte rotineira de açυes, progra mas e serviços de saúde.', '["epidemiology","health services","health technology","health system effectiveness","health needs assessment","health planning and evaluation","health care reform","public health","health policy","health system equity"]', '10.7476/9788575412626', '9788575412626', 'https://books.scielo.org/id/889m2', 'https://books.scielo.org/id/889m2/pdf/barreto-9788575412626.pdf', NULL, 'https://books.scielo.org/id/889m2/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-88gjv', '88gjv', 'Gênese da saúde global: a Fundação Rockefeller no Caribe e na América Latina', NULL, '["Steve Palmer"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, as autoras abordam a complexa relação entre saúde e desastres inserida em um modelo de desenvolvimento econômico que cria e agrava cenários de risco, nos quais alguns grupos populacionais se tornam cada vez mais vulneráveis. A obra procura demonstrar, por meio de exemplos de desastres ocorridos no Brasil, os principais impactos produzidos, as consequências para a saúde e qualidade de vida das populações atingidas. Busca, ainda, discutir a importância das diferentes áreas de conhecimento e saberes acumulados para a produção de pesquisa básica e aplicada como suporte a ações e políticas para redução de riscos. Ao final, as autoras apresentam os avanços em ações e políticas direcionadas à redução de risco de desastres, nos âmbitos internacional e nacional, e os novos e velhos desafios a serem enfrentados pela saúde coletiva, considerando a complexidade dos processos naturais e sociais que envolvem os desastres em cenários atuais e futuros.', '["global health","Rockefeller Foundation","Caribbean","Latin America","disaster risk reduction","economic development","population vulnerability","quality of life","collective health","disaster research","health policy"]', '10.7476/9786557081167', '9788575414576', 'https://books.scielo.org/id/88gjv', NULL, NULL, 'https://books.scielo.org/id/88gjv/cover/cover_thumbnail.jpeg', 421, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-88pgx', '88pgx', 'Epidemiologia e clínica da coinfecção Trypanosoma cruzi e vírus da imunodeficiência adquirida', NULL, '["Eros Antônio de Almeida"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O livro encontra-se embargado pela Editora e por esse motivo, o capítulo do livro está em acesso restrito. Fonte: https://books.scielo.org/id/88pgx', '["Trypanosoma cruzi","Chagas disease","HIV","co-infection","epidemiology","clinical features"]', '10.7476/9788526815018', '9788526812796', 'https://books.scielo.org/id/88pgx', NULL, NULL, 'https://books.scielo.org/id/88pgx/cover/cover_thumbnail.jpeg', 328, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-88vqx', '88vqx', 'A Guerra Fria', NULL, '["Sidnei José Munhoz","José Victor de Lara"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro narra de modo conciso uma instigante história da Guerra Fria. Isso foi efetuado por meio da combinação de uma escrita corrente, mas refinada; da associação de uma narrativa ora circunspecta, ora candente, mas balanceada e atenta aos primados históricos. A obra problematiza a temática de modo a descortinar outras possibilidades interpretativas e a instigar o interesse do público por leituras correlatas. No seu desenrolar, o livro aborda as origens da Guerra Fria, a constituição de blocos de poder, as disputas travadas em diferentes campos, tais quais a corrida armamentista, a competição aeroespacial, as olimpíadas, o cinema, o rádio, a TV e a música. O livro aborda ainda os conflitos emergentes durante o período e as negociações entre as potências globais. Por fim, a obra trata da crise soviética, do fim da Guerra Fria e das suas reverberações em nosso tempo presente.', '["Cold War","Cold War origins","arms race","space race","Olympic Games","cinema","radio","television","music","international negotiations","end of the Cold War"]', '10.7476/9786587626161', '9786586383287', 'https://books.scielo.org/id/88vqx', NULL, NULL, 'https://books.scielo.org/id/88vqx/cover/cover_thumbnail.jpeg', 240, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-88zyx', '88zyx', 'Políticas Internacionais de Saúde na Era Vargas: o Serviço Especial de Saúde Pública, 1942-1960', NULL, '["André Luiz Vieira de Campos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra analisa o Sesp enquanto agência responsável pela institucionalização das políticas públicas de saúde no Brasil. Para tanto, divide-se em três partes: a primeira conta com dois capítulos e fala sobre a origem do Sesp no contexto das relações internacionais entre Brasil e EUA e da Segunda Guerra Mundial; a segunda divide-se em quatro capítulos que dissertam sobre o controle da malária nas bases americanas no Brasil (Belém, Recife e Natal), a política sanitária exercida na Amazônia (por conta das migrações para o esforço de guerra na colheita da borracha), no Vale do Rio Doce e nas regiões produtoras de mica em Minas Gerais; e a última, com três capítulos, expõe as estratégias de sobrevivência e transformações do Sesp no pós-guerra, seu papel na administração sanitária e colaboração na expansão do poder público na década de 50.', '["Vargas era","health policy","public health centers","Brazil–United States relations","World War II","malaria control","US military bases","rubber plantations","Vale do Rio Doce","mica mining","Minas Gerais","postwar period"]', '10.7476/9786557081006', '9786557081006', 'https://books.scielo.org/id/88zyx', 'https://books.scielo.org/id/88zyx/pdf/campos-9786557081006.pdf', NULL, 'https://books.scielo.org/id/88zyx/cover/cover_thumbnail.jpeg', NULL, 52, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8938t', '8938t', 'Histórias das ciências, epistemologia, gênero e arte: ensaios para a formação de professores', NULL, '["Bruna Bertasso Teixeira de Moura","Thaís Cyrino de Mello Forato"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A melhoria da formação de professores no Brasil tem sido um objetivo constante de boa parcela das propostas que emergem das pesquisas em ensino de ciências. Esses pesquisadores concordam que é preciso romper com a visão tradicional do professor de ciências como mero transmissor do conhecimento, aquele que simplesmente repassa os conteúdos básicos de sua área ao aluno, em um processo puramente mecânico. O professor pode e deve ser muito mais que isso. Nessa direção, educadores têm apontado a relevância de introduzir em contextos de formação de professores de ciências, discussões não apenas ligadas ao arcabouço conceitual da ciência, mas também sobre sua construção, seus aspectos internos e externos, suas influências, sua natureza. Ao inserir esses temas, o professor se mune de maior criticidade e poder de transformação, tornando-se não um transmissor de conhecimento, mas um mediador. É ele que trará ao aluno as ferramentas para compreender a ciência como um empreendimento humano, e por isso, produto de sua cultura. A proposta do livro “História das Ciências, Epistemologia, Gênero e Arte: ensaios para a formação de professores” é oferecer subsídios para fomentar a introdução de perspectivas como essas. Dessa maneira, com esse livro, o professor de ciências terá, em um só material, uma fonte diversificada de informações e discussões, que pode construir novos caminhos para o um ensino de ciências mais dinâmico, atual e transformador.', '["history of science","epistemology","gender","art","science teacher education","science education","teacher mediation","nature of science","critical pedagogy"]', '10.7476/9788568576847', '9788568576847', 'https://books.scielo.org/id/8938t', 'https://books.scielo.org/id/8938t/pdf/moura-9788568576847.pdf', NULL, 'https://books.scielo.org/id/8938t/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-895sg', '895sg', 'A saúde no Brasil em 2030: desenvolvimento, Estado e políticas de saúde - Vol. 1', NULL, '["Fundação Oswaldo Cruz"]', 'Fiocruz/Ipea/Ministério da Saúde/Secretaria de Assuntos Estratégicos da Presidência da República', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'PrefácioA Fundação Oswaldo Cruz (Fiocruz), em sua condição de instituição pública estratégica para a Saúde, é agente da dinâmica do desenvolvimento do Estado brasileiro e assim se apresenta ao governo e à sociedade.Essa dimensão estratégica é referência para seu planejamento, sua inserção nas políticas governamentais e seus compromissos com a sociedade.Este livro é fruto do projeto Saúde Brasil 2030, desenvolvido no bojo do acordo de cooperação técnica assinado pela Fiocruz com a Secretaria de Assuntos Estratégicos da Presidência da República (SAE) e o Instituto de Pesquisa Econômica Aplicada (Ipea) e de convênio pactuado com o Ministério da Saúde.O projeto Saúde Brasil 2030 tem como principal objetivo a constituição de uma rede permanente de prospectiva estratégica no campo da saúde.Os textos resultantes dessa iniciativa, aqui apresentados em sua versão integral, especulam sobre a probabilidade de futuros para a Saúde em 2030, com referência ao ano de 2022, quando se comemora o bicentenário da Independência do Brasil.Diante dos desafios que o futuro traz, cabe ao Estado articular e induzir políticas econômicas e sociais, no interesse do desenvolvimento com equidade, fomentando o acesso e a inclusão de camadas excluídas, expandindo e assegurando direitos sociais às parcelas significativas da população ainda marginalizadas e sem os ganhos advindos do progresso e da riqueza.O setor Saúde contribui de forma crescente para o dinamismo econômico das sociedades, e sua integração com outros setores, como Ciência e Tecnologia, Educação, Comércio Exterior e Política Industrial, entre outros, pode influir decisivamente no modelo de desenvolvimento de nosso país.É imperioso planejar em prazos mais longos, dada a complexidade do setor Saúde e dos nítidos processos de transformação e inovação em curso nas suas diversas áreas de atuação.Não se trata apenas de criar imagens de futuro, mas, especialmente, de auxiliar na gestão estratégica, mediante diretrizes para o alinhamento das ações com um cenário de futuro desejável para nosso país.Os textos aqui apresentados são o ponto de partida do esforço prospectivo, e não seu resultado.São lançados a debate público por especialistas a partir de sua conclusão.Com isso a Fiocruz contribui para a formulação de políticas públicas em saúde, educação, ciência e tecnologia e inovação em saúde, reafirmando sua posição na defesa e fortalecimento do Sistema Único de Saúde (SUS), por seu desenvolvimento e alcance de padrão sustentável, assegurando a realização plena de seus princípios e possibilitando as necessárias conquistas sociossanitárias.Paulo Gadelha Presidente da Fiocruz Apresentação Este volume, Desenvolvimento, Estado e Políticas de Saúde, objetiva desenhar um pano de fundo para os outros capítulos diretamente voltados para a questão da saúde.Abrange os seguintes temas: cenários de desenvolvimento para 2022-2030, os eixos para o desenvolvimento do país, a saúde na política nacional de desenvolvimento, a gestão pública no Século XXI, e o Brasil na arena internacional como nação soberana e cooperativa.O esforço inicial do projeto Saúde Brasil 2030 consistiu em percorrer os temas mais relevantes para o desenho de horizontes futuros do sistema de prestação de cuidados à saúde no Brasil, tendo como ano de referência 2030.Nesta primeira etapa, esses temas foram organizados em blocos e, para cada um deles, identificados com base no conhecimento já produzido e acumulado os elementos essenciais que os compõem e que permitem o desenvolvimento do exercício prospectivo, bem como as lacunas de conhecimento a serem preenchidas.O produto desta etapa é publicado e divulgado para debate público, orientando a conformação de redes de conhecimento que serão constituídas para as etapas subsequentes do projeto.Adotou-se como metodologia a chamada prospecção estratégica, que teve suas origens, nos anos 1980, no campo da administração e foi empregada, posteriormente, no domínio das políticas públicas (HABEGGER, 2010).Para esse autor, a prospecção estratégica pode ser definida como uma tentativa deliberada de alargar as "fronteiras da percepção" e expandir a capacidade de atenção em relação a temas e situações emergentes.A prospecção estratégica, de acordo com Habegger, citando uma proposta de Müller, integra as perspectivas, procedimentos e ferramentas tanto das pesquisas de tendências quanto dos estudos de futuros.De um lado, a pesquisa de tendências lida com a detecção precoce e interpretação nos campos econômico, político, social e tecnológico e objetiva avaliar o impacto das mudanças tanto na sociedade como nos indivíduos.Os estudos de futuro, por outro lado, capturam e antecipam desenvolvimentos futuros nesses domínios, de modo a gerar visões de como a sociedade evolui e das opções de políticas que estão disponíveis para se modelar um futuro desejado.Para Habegger, o processo de prospecção estratégica pode ser conceituado e implementado de várias maneiras, mas a maioria dos estudiosos segue uma lógica bastante semelhante que divide tal processo em três fases:• a detecção precoce e a análise da informação;• a geração de conhecimento prospectivo;• o desenvolvimento das opções (de políticas) futuras.A primeira fase envolve a identificação e o monitoramento contínuo dos temas, tendências, desenvolvimento e mudanças dos processos em estudo.A segunda fase implica a avaliação e entendimento dos desafios para a implementação das diferentes políticas.E a terceira assenta-se na formulação dos futuros desejados e das ações políticas necessárias para alcançá-los.Isso implica explorar diversos "futuros" ou cenários alternativos.Neste contexto prospectivo, assumimos três cenários alternativos:• cenário desejável e possível;• cenário inercial e provável;• cenário pessimista e plausível.Impôs-se às categorias de "futuros" desejáveis a condição de possibilidade, isto é, a capacidade de concretização no horizonte temporal contemplado.Este esquema (Figura 1), em que os horizontes possíveis foram estabelecidos apenas como diretrizes de políticas desejáveis, é inspirado por Voros.Figura 01.Cone de "Futuros" Fonte: Voros, J.A generic foresight process framework, Foresight 5 (3) (2003) 10-21, citado por Habegger B. Strategic foresight in public policy: Reviewing the experiences of the UK, Singapore, and the Netherlands.Futures 42 (2010) 49-58.Tempo Agora Potencial Provável Preferível Plausível PossívelNos estudos procurou-se especular, com razoável fundamentação, sobre a probabilidade desses futuros.Consistem em textos de partida para o esforço prospectivo, e não o seu resultado.Devem ser considerados, assim, como termos de referência em torno dos quais se prolongará a prospecção estratégica para cada um dos domínios abordados, através da constituição de uma rede de conhecimento para ampliação e amplificação do debate e dos estudos futuros que serão desencadeados a partir desta aventura inicial.O Volume 2 -População e Perfil Sanitário -, analisa os determinantes sociais, econômicos e ambientais da Saúde, abordando o cenário sociodemográfico em 2022 e 2030, a distribuição territorial da população, traçando um diagnóstico do comportamento atual dos fenômenos demográficos no país e refletindo a respeito das tendências futuras desses processos.Examina-se, ainda, o perfil epidemiológico no horizonte temporal proposto, assinalando-se os problemas de saúde que vêm se agravando, como a violência, a dengue, o diabetes, a obesidade, ao lado das doenças transmissíveis, endemias, epidemias e pandemias que configuram riscos sanitários para o país no futuro próximo.No Volume 3 são tratados temas relacionados à Organização e Gestão do Sistema de Saúde, assinalando-se os princípios do sistema de saúde brasileiro.Inicialmente, aborda-se a gestão do nível federal do sistema (administração direta, agências reguladoras, fundações nacionais, empresas públicas nacionais) na condução da política nacional e na gestão do sistema de saúde no Brasil.No capítulo "A coordenação federativa ', '["health policy","state development","health and development","health equity","social rights","strategic foresight","health system planning","health and economy"]', '10.7476/9788581100159', '9788581100159', 'https://books.scielo.org/id/895sg', 'https://books.scielo.org/id/895sg/pdf/noronha-9788581100159.pdf', NULL, 'https://books.scielo.org/id/895sg/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-89kx6', '89kx6', 'Tudo pelo trabalho livre! Trabalhadores e conflitos no pós-abolição (Bahia, 1892-1909)', NULL, '["Rogério Santos Souza"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Robério Souza aborda a vida dos trabalhadores ferroviários (negros, em sua maioria) no período pós-abolição e nos anos iniciais do período republicano. Acompanha a luta pelos direitos e conquistas sociais, os movimentos trabalhistas, os conflitos e a organização da classe. Apesar de ter como ponto de partida o contexto baiano, na construção da estrada de ferro da Bahia ao São Francisco, esta obra traz reflexões globais sobre o fim do escravismo e a liberdade dos trabalhadores.', '["free labor","abolition of slavery","railway workers","Black workers","labor movement","workers'' rights","social struggles","class organization","Brazilian Republic","Bahia"]', '10.7476/9788523212377', '9788523208035', 'https://books.scielo.org/id/89kx6', NULL, NULL, 'https://books.scielo.org/id/89kx6/cover/cover_thumbnail.jpeg', 182, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-89prc', '89prc', 'Sociolinguística e funcionalismo: vertentes e interfaces', NULL, '["Cristina dos Santos Carvalho","Norma da Silva Lopes","Angélica Rodrigues"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '', '["sociolinguistics","functionalism","theoretical approaches","language and society"]', '10.7476/9786588211328', '9786588211250', 'https://books.scielo.org/id/89prc', 'https://books.scielo.org/id/89prc/pdf/carvalho-9786588211328.pdf', 'https://books.scielo.org/id/89prc/epub/carvalho-9786588211328.epub', 'https://books.scielo.org/id/89prc/cover/cover_thumbnail.jpeg', 350, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-89yjz', '89yjz', 'Faculdade de Medicina de Botucatu: 60 anos em 60 depoimentos', '60 anos em 60 depoimentos', '["Martha Martins de (Org.) [UNESP] Morais","Maria Cristina Pereira Lima"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta é uma obra que registra e comemora as seis décadas da Faculdade de Medicina de Botucatu (FMB/Unesp), completadas em abril de 2023. Produzida pelo seu Centro de Memória (CMFMB), a obra possui uma abordagem editorial memorialista, reunindo relatos diversos de autores convidados e imagens históricas da instituição, além de duas entrevistas com personalidades que vivenciaram os primeiros anos da então Faculdade de Ciências Médicas e Biológicas de Botucatu (FCMBB) e acompanharam de perto o surgimento da Unesp. Ao todo, o livro possui mais de 60 autores, visto que alguns textos foram escritos a quatro mãos — e até mesmo a mais — o que contribui para a diversidade de abordagens e olhares para as histórias aqui contadas, registrando os momentos e as mudanças ocorridas na instituição ao longo das suas seis décadas de existência.', '["history of medical education","medical school anniversary","oral history","institutional memory","UNESP","history of medicine"]', '10.7476/9786559544592', '9786559544592', 'https://books.scielo.org/id/89yjz', 'https://books.scielo.org/id/89yjz/pdf/morais-9786559544592.pdf', NULL, 'https://books.scielo.org/id/89yjz/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8b9n4', '8b9n4', 'Cadastro e gestão territorial: uma visão luso-brasileira para a implementação de sistemas de informação cadastral nos municípios', NULL, '["Amilton Amorim","Marcos Aurélio Pelegrina","Rui Pedro Sousa Pereira Monteiro Julião"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Nesta obra é abordada a Gestão Territorial com o objetivo de compreender sua relevância e seus principais desafios, bem como as reais necessidades de obtenção de dados e recursos para seu êxito. Apresenta-se o paradigma do Cadastro Territorial Multifinalitário, seus conceitos fundamentais e o modo como ele é abordado em várias regiões e em vários países. Além disso, trata-se da Infraestrutura de Dados Espaciais (IDE), considerada essencial para o desenvolvimento de projetos relativos à produção, gestão e exploração de dados geográficos e cadastrais, em contextos compartilhados por vários serviços do Estado. Finalmente, é apresentada uma análise dos requisitos e modelos para a Gestão Territorial, baseada no Cadastro Territorial Multifinalitário e com a utilização da IDE, com particular destaque para o Land Administration Domain Model (LADM). Por fim, é apresentada uma análise da situação do desenvolvimento dos sistemas cadastrais e sua aplicação na Gestão Territorial no Brasil e em Portugal.', '["territorial management","cadastral information system","spatial data infrastructure","Land Administration Domain Model","spatial data management","Portugal","Brazil"]', '10.7476/9788595462823', '9788595462823', 'https://books.scielo.org/id/8b9n4', 'https://books.scielo.org/id/8b9n4/pdf/amorim-9788595462823.pdf', NULL, 'https://books.scielo.org/id/8b9n4/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8b9v3', '8b9v3', 'Discurso e texto: multiplicidade de sentidos na ciência da informação', NULL, '["Nádea Regina Gaspar","Lucília Maria Sousa Romão"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] O campo da Análise do Discurso vem sendo pesquisado na França desde os anos 1960; no Brasil, esses estudos começam em torno dos anos 1980 e proliferam com intensidade nas Ciências Humanas, particularmente na área da Linguística e, de modo mais amplo, nos estudos das linguagens. O que se objetivou com esse livro foi demonstrar algumas possibilidades de recorrer às teorias da análise do discurso como subsídio metodológico e analítico, aplicáveis também ao campo da Ciência da Informação. Nesta obra, que tem o formato de coletânea, é possível encontrar diversos mirantes teóricos da análise do discurso mobilizados para investigação e interpretação em vários gêneros textuais, instigando e convidando, aos que atuam no campo da documentação e da informação, a levarem em conta o lugar teórico do discurso como multiplicidade de efeitos de sentidos e instância ideológica do dizer.', '["discourse analysis","information science","multiple meanings","ideology","textual genres","discourse theory","language studies"]', '10.7476/9788576003700', '9788576003700', 'https://books.scielo.org/id/8b9v3', NULL, NULL, 'https://books.scielo.org/id/8b9v3/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8bbds', '8bbds', 'Del este de Europa al sur de América: migraciones soviéticas y postsoviéticas a la ciudad de Bucaramanga, Santander', NULL, '["Mayra Alejandra Umaña Cifuentes"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'El objetivo principal de esta obra es reconstruir los procesos migratorios que llevaron a los migrantes de la ex Unión de Repúblicas Socialistas Soviéticas, a residir en Bucaramanga (Colombia). Así mismo, se indaga sobre la falsa creencia de que en Colombia no existe la inmigración y el vacío en la producción académica frente a este tema, que suele centrarse en las personas que dejan el país y no en quienes llegan. Por otro lado, se indaga sobre el hecho de que la literatura sobre el tema obedece más a investigaciones de tipo histórico. Metodológicamente, este estudio se sustentó en el uso de historias de curso de vida basados en los supuestos de Howard Becker, donde el uso de historias de vida permite aproximarse a cuestiones subjetivas de los investigados, sus experiencias, sus motivaciones y la interpretación que estos tienen de su realidad. Cuestiones que sólo pueden ser entendidas desde el punto de vista de quien vivió una experiencia y que de no ser así se podría incurrir en suposiciones y conjeturas.', '["Soviet migration","post-Soviet migration","Bucaramanga","immigrant life histories"]', '10.7476/9789587385953', '9789587385953', 'https://books.scielo.org/id/8bbds', 'https://books.scielo.org/id/8bbds/pdf/umana-9789587385953.pdf', NULL, 'https://books.scielo.org/id/8bbds/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8crb5', '8crb5', 'Alebrijes anárquicos: anarquía, praxis anticolonial y autonomía en América Latina', 'anarquía, praxis anticolonial y autonomía en América Latina', '["Gaya Makaran","Cássio Brancaleone"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Alebrijes anárquicos es un libro para habitar y navegar en es­pacios de fricción, encontrando en esta energía los impulsos que potencian la mancomunión de resistencias y autonomías. Su resultado es toda una fauna ácrata que escapa de los cá­nones que dividieron la naturaleza en reinos jerárquicos y ta­xonomías estáticas, y que surge de una lectura en torno a las prácticas anárquicas en el ámbito de la historia social y popular de las personas, comunidades y pueblos de América Latina. Asimismo, tras su lectura, se comprenderá que las prácticas anarquistas crecen en la medida en que se diversifican, desbor­dando cierto sentido “prístino” del anarquismo en tanto teoría moderna de la emancipación, para pensarlo, en cambio, como sustrato de la autonomía comunitaria en el complejo entrama­do de las relaciones socioambientales e interculturales. A través de los cinco capítulos que componen el recorrido, se urden voces pretéritas y contemporáneas, articulando relatos y transmitiendo enseñanzas que nos inspiran a imaginar nues­tros propios alebrijes, a sumar otros colores y piezas al vasto y enrevesado hummus de las resistencias anticolonialistas y de las prácticas anárquicas que han pululado en América Latina y que continúan emergiendo con la fuerza de aquellos/as sem­bradores/as que desde otrora nos recuerdan: no estamos so­los/as, la lucha continúa.', '["anarchism","anti-colonialism","community autonomy","public opposition","Latin America","intercultural relations","socio-environmental relations","emancipation","indigenous peoples"]', '10.7476/9786550191849', '9786550191030', 'https://books.scielo.org/id/8crb5', 'https://books.scielo.org/id/8crb5/pdf/makaran-9786550191849.pdf', NULL, 'https://books.scielo.org/id/8crb5/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8czx4', '8czx4', 'Inovação em saúde: dilemas e desafios de uma instituição pública', NULL, '["Nara Azevedo","Carlos Augusto Grabois Gadelha","Carlos Fidelis Ponte","Claudia Trindade","Wanda Hamilton"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Os 30 anos do Instituto de Tecnologia em Imunobiológicos (Biomanguinhos) – unidade da Fiocruz que fabrica vacinas e testes para diagnóstico – são o mote deste livro, que oferece reflexões sobre a ciência e a tecnologia no país, com ênfase na biotecnologia e na inovação em saúde. Dividida em três partes – História e imunização no Brasil; Registros da memória: depoimentos sobre Biomanguinhos, e Dinâmica industrial e estratégias de inovação em vacinas –, a obra analisa a trajetória e os desafios de uma instituição que já contribuiu para a erradicação da poliomielite, controle do sarampo e da febre amarela e o enfrentamento da meningite, entre outras conquistas.', '["healthcare innovation","Fiocruz","vaccine production","diagnostic testing","biotechnology","polio eradication","measles control","yellow fever","meningitis","public research institutions","industrial dynamics","innovation strategy"]', '10.7476/9786557080795', '9788575411346', 'https://books.scielo.org/id/8czx4', NULL, NULL, 'https://books.scielo.org/id/8czx4/cover/cover_thumbnail.jpeg', 424, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8d9nb', '8d9nb', 'Geografia das telecomunicações no Brasil', NULL, '["Paulo Fernando Jurado da Silva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'O livro trata da telecomunicação no Brasil, abordando inicialmente o desenvolvimento dos estudos da área em nosso país para, só então, inserir o problema de pesquisa da obra, que consiste em relacionar o estudo das telecomunicações com sua compreensão por meio de três pilares de sustentação: a telefonia celular, a internet e a televisão.', '["Brazil","mobile telephony","internet","television","telecommunications development"]', '10.7476/9788579836701', '9788579836701', 'https://books.scielo.org/id/8d9nb', 'https://books.scielo.org/id/8d9nb/pdf/silva-9788579836701.pdf', NULL, 'https://books.scielo.org/id/8d9nb/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8dtt4', '8dtt4', 'Políticas, planejamento e gestão em saúde: abordagens e métodos de pesquisa', NULL, '["Tatiana Wargas de Faria Baptista","Creuza da Silva Azevedo","Cristiani Vieira Machado"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Reúne alguns dos principais nomes da área de planejamento em saúde no país e apresenta um conjunto rico e diversificado de reflexões teórico-metodológicas, o que resulta em contribuições fundamentais para o incremento da área. Questões como desenvolvimento de estudos e formação de pesquisadores também estão presentes. Dividida em três partes, a coletânea analisa os desafios metodológicos em pesquisas do campo da saúde coletiva; aborda a questão da multidisciplinaridade e de como os estudos em saúde coletiva têm dialogado com outras áreas de conhecimento (como a história, a ciência política, a filosofia, a sociologia, entre outras); e traz reflexões sobre questões tais como o lugar da saúde nas relações internacionais, a promoção da saúde, a produção acadêmica relacionada à gestão do trabalho e da educação em saúde e, por fim, o acesso a medicamentos.', '["health planning","health policy","health management","research methodology","multidisciplinarity","health promotion","health education","work management","access to medicines","research training"]', '10.7476/9788575415207', '9788575414590', 'https://books.scielo.org/id/8dtt4', NULL, NULL, 'https://books.scielo.org/id/8dtt4/cover/cover_thumbnail.jpeg', 378, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8dtt5', '8dtt5', 'De que se queixa o adolescente hoje: clínica psicanalítica e contemporaneidade', NULL, '["Eliane Maria Vasconcelos do Nascimento","Rita de Cássia Fagundes Gonzales"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Dentre todas as fases do desenvolvimento humano, talvez a mais intrigante de todas seja a adolescência. É nela em que o sujeito experimenta estratégias que o tornarão autônomo, o que gera um período de crise e turbulência. É a respeito deste tema que as autoras Eliane Nascimento e Rita Gonzales discorrem, ao longo de seis artigos, usando conceitos extraídos da psicanálise, sobre questões como o uso de drogas, a relação da adolescência com a contemporaneidade e a escolha da carreira profissional, momento vivido comumente durante a fase adolescente.', '["adolescence","psychoanalytic clinic","autonomy","adolescent crisis","drug use","contemporary adolescence","career choice","psychoanalytic concepts"]', '10.7476/9788523218799', '9788523214395', 'https://books.scielo.org/id/8dtt5', NULL, NULL, 'https://books.scielo.org/id/8dtt5/cover/cover_thumbnail.jpeg', 197, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8fcfr', '8fcfr', 'Etnografia e educação: conceitos e usos', NULL, '["Carmem Lúcia Guimarães de Mattos","Paula Almeida de Castro"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Delineando os caminhos de uma etnografia da educação, este livro provoca os leitores a refletir sobre os processos de escolarização numa sociedade marcada pelo profundo desconhecimento dos mecanismos que cotidianamente se empregam para perpetuar a desigualdade social. O livro, fruto de uma aprimorada aplicação do conceito de etnografia em pesquisas educacionais, reúne trabalhos que desenham os conceitos e usos da etnografia como uma paradigma teórico-epistemológico nas pesquisas qualitativas.', '["ethnography of education","educational research","qualitative research","epistemology of ethnography","social inequality","schooling process","theoretical paradigms"]', '10.7476/9788578791902', '9788578791902', 'https://books.scielo.org/id/8fcfr', 'https://books.scielo.org/id/8fcfr/pdf/mattos-9788578791902.pdf', NULL, 'https://books.scielo.org/id/8fcfr/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8fmv5', '8fmv5', 'A miragem da pós-modernidade: democracia e políticas sociais no contexto da globalização', NULL, '["Sílvia Gerschman","Maria Lucia Werneck Vianna"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1997, '1997-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Oferece uma nova dimensäo às relaçöes entre democracia e questäo social, entre políticas de ajuste e reformas governamentais, conduzindo ao urgente "re-pensar" acerca das possibilidades e alcances do Estado em gerar o bem-estar da sociedade e dos indivíduos num mundo globalizado.', '["postmodernity","democracy","social policy","globalization","structural adjustment programs","government reform","role of the state","social welfare"]', '10.7476/9788575413975', '9788575413975', 'https://books.scielo.org/id/8fmv5', 'https://books.scielo.org/id/8fmv5/pdf/gerschman-9788575413975.pdf', NULL, 'https://books.scielo.org/id/8fmv5/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8fsbm', '8fsbm', 'Impacto en procesos de resocialización con población carcelaria. Sistematización de experiencias en tres establecimientos penitenciarios del Suroccidente colombiano', NULL, '["Alicia del Carmen Torres","Lady Gómez Ramírez","Juan Diego Castrillón Cordovez"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Colombia', 'SciELO Books', 'books', 2017, '2017-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La sistematización que se ofrece en este documento se refiere a experiencias concretas de trabajo con población carcelaria de los municipios del occidente colombiano, Cali, Santander de Quilichao y Puerto Tejada. Su sentido es mostrar qué es fundamental en los procesos de resocialización que se promueva la autorreflexión en cada interno, el ejercicio narrativo de reconocimiento de los propios valores y de la reconstrucción discursiva de la propia identidad como persona libre para sacudirse del pesado fardo del estigma social de "ex condenado" o "ex condenada" por el sistema judicial. Sin esta perspectiva, se dificulta el éxito de programas enfocados en la humanización y resocialización, en función del trabajo, del estudio, de la conducta y del comportamiento. El eje de la sistematización lo constituyen los aspectos positivos, exitosos, de orden personal, social e institucional de estos talleres. Optar por este eje de la sistematización no impidió reseñar las limitaciones que se tuvieron en su organización y realización, Esta visión se propuso como alternativa a las condiciones represivas del sistema penitenciario en diferentes escenarios de encierro: patios de reclusión de delincuencia común, patios de narcotráfico, patios de las denominados autodefensas o paramilitares, patios de la guerrilla, etc.', '["prisoner resocialization","penitentiary system","self-reflection","identity reconstruction","rehabilitation programs","prison workshops","Cali","Santander de Quilichao","Puerto Tejada"]', '10.7476/9789586190060', '9789588994475', 'https://books.scielo.org/id/8fsbm', NULL, NULL, 'https://books.scielo.org/id/8fsbm/cover/cover_thumbnail.jpeg', 220, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8fygn', '8fygn', 'Ao revés do ‘pós’: variações sobre temas de arte e educação', NULL, '["Rita Luciana Berti Bredariolli"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Dentre o conjunto de edições do Festival de Inverno de Campos de Jordão, tradicionalmente dedicado à música erudita e à formação de jovens concertistas, a edição de 1983 destacou-se como “dissonância” e particularizou-se por ter sido dedicada a professores de Educação Artística da rede pública de ensino do estado de São Paulo. Em quarenta anos de vida dos festivais, sua décima quarta versão – organizada por Cláudia Toni, Ana Mae Barbosa e Gláucia Amaral – foi singular pela concepção, pela programação e pela relação com o entorno político e educacional de sua época. Por meio do programa do festival, dos discursos de professores nele proferidos, de textos de jornais, cartas e relatos e de imagens, Rita Bredariolli dedica-se à análise dessa edição do festival e faz uma avaliação da importância do programa pedagógico e da concepção de ensino de arte enunciados no XIV Festival de Inverno de Campos de Jordão.', '["art education","music education","art teachers","public schools","pedagogical program","cultural festivals","São Paulo state"]', '10.7476/9786557144794', '9786557144794', 'https://books.scielo.org/id/8fygn', 'https://books.scielo.org/id/8fygn/pdf/bredariolli-9786557144794.pdf', NULL, 'https://books.scielo.org/id/8fygn/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8g3m3', '8g3m3', 'Álcool e direção: beber ou dirigir: um guia prático para educadores, profissionais da saúde e gestores de políticas públicas', NULL, '["Sérgio Dualibi","Pinsky, Llana","Ronaldo Laranjeira","Ligia Duailibi","José Florentino dos Santos","Rosangela Pommorsky Vilma Leyton","Julio de Carvalho Ponde","Gabriel Andreuccetti","Débora Golçalves de Carvalho","Raquel Zanelatto","L.A. Oliveira"]', 'Editora Fap-Unifesp', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', '[RETIRADO/WITHDRAWN] Este guia apresenta o resultado de estudos levados a cabo em diversas cidades do Brasil. Para tanto, os investigadores lançaram mão de um questionário e da aplicação de bafômetros em motoristas que circulavam nas grandes vias de tráfego dos municípios avaliados, entabulando resultados e estabelecendo estatísticas esclarecedoras sobre o comportamento em questão. Os primeiros capítulos abordam os problemas associados à legislação nacional e apresentam os dados provenientes da pesquisa, elucidando os aspectos metodológicos que a nortearam e comparando os resultados obtidos antes e depois da Lei Seca. São analisados, em seguida, os dados sociodemográficos dos entrevistados e seu comportamento e conhecimento da legislação específica, apresentando os índices de aceitação das medidas preventivas. Por fim, os anexos trazem o Questionário da Pesquisa Nacional Beber e Dirigir, utilizado na obtenção de dados, os Folhetos Educativos da Pesquisa Nacional Beber e Dirigir, e a Redação da Lei 11.705, a Lei Seca.', '["drunk driving","alcohol and driving","dry law","traffic law","breath test","driver behavior","sociodemographic factors","preventive measures","public policy","health education"]', '10.7476/9788561673543', '9788561673543', 'https://books.scielo.org/id/8g3m3', NULL, NULL, 'https://books.scielo.org/id/8g3m3/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8ghnw', '8ghnw', 'COVID-19: respuestas desde la ingeniería y la inteligencia artificial', NULL, '["Christian Salamea"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', '¿Cómo actúa nuestro cuerpo para defenderse? ¿Cómo funcionan las vacunas? ¿Cómo se diagnostica la enfermedad? ¿Puede la ingeniería y la inteligencia artificial dar una respuesta al diagnóstico? Estas preguntas sirvieron de base para el desarrollo de una investigación que permitió evaluar la respuesta de la inteligencia artificial frente a la pandemia. En estas páginas se describen conceptos fundamentales que se utilizaron para reconocer patrones relacionados con la tos COVID y de las capacidades reales de los sistemas inteligentes para detectarla. Esta obra tiene un enfoque de difusión científica, con un lenguaje cercano y amigable para los lectores y contribuye a los avances logrados alrededor del mundo.', '["COVID-19 pandemic","artificial intelligence","engineering","COVID-19 diagnosis","machine learning detection","immune response","vaccines"]', '10.7476/9789978108185', '9789978108185', 'https://books.scielo.org/id/8ghnw', 'https://books.scielo.org/id/8ghnw/pdf/salamea-9789978108185.pdf', NULL, 'https://books.scielo.org/id/8ghnw/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8h47w', '8h47w', 'Segurança do paciente: conhecendo os riscos nas organizações de saúde', NULL, '["Paulo Jorge dos Santos Sousa","Walter Vieira Mendes Junior"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Rio de Janeiro (Unirio); pós-graduação em prevenção', '["patient safety","patient safety risks","health care organization","risk management","patient safety culture"]', '10.7476/9788575415955', '9788575415955', 'https://books.scielo.org/id/8h47w', 'https://books.scielo.org/id/8h47w/pdf/sousa-9788575415955.pdf', NULL, 'https://books.scielo.org/id/8h47w/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8h678', '8h678', 'A vida no feeling do momento', 'esse alegre ter entre os que bebem excessivamente', '["Paulo Rogers Ferreira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '“A vida no feeling do momento” uma contribuição antropológica ao conceito de feeling do momento no consumo excessivo de álcool em coletivo. Trata-se de uma proposta alternativa à compreensão do beber socialmente em excesso, tendo como local etnográfico a região de Beauce, Quebec, Canadá. No lugar de considerar o consumo de uma série de cervejas como um problema social ou sanitário, Paulo Rogers buscou compreender como e por que se bebia excessivamente naquela região. Fazendo parte de inúmeros encontros, seja em garagens, em bares, em cabanas na floresta, no vestiário dos jogadores de hóquei amador ou durante partidas de boliche, Rogers se deixou afetar pela sensação presente e pelos contraditos pronunciados, logo que os que bebiam excessivamente experimentavam o que eles chamavam de feeling do momento.', '["excessive alcohol consumption","social drinking","beer consumption"]', '10.7476/9786556309071', '9786556307558', 'https://books.scielo.org/id/8h678', 'https://books.scielo.org/id/8h678/pdf/ferreira-9786556309071.pdf', NULL, 'https://books.scielo.org/id/8h678/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8hp3p', '8hp3p', 'Patrimônio, povos do campo e memórias: diálogos com a cultura, a arte e a educação', NULL, '["Gerciane Maria da Costa Oliveira","Kyara Maria de Almeida Vieira"]', 'EdUFERSA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra é a culminância do projeto “Para além das fazendas em pedra e cal: um estudo sobre o Patrimônio Rural (Ambiental e Cultural) do Semiárido Nordestino”, financiado pelo Edital Universal MCTI/CNPq Nº 01/ 2016. Com o objetivo de problematizar a abrangência do conceito de patrimônio rural, esta proposta investigativa se inscreve nas ações do Grupo de Estudos, Pesquisa e Ensino de Sociologia e Ciências Humanas (UFERSA). O livro conta com os textos derivados de pesquisas de Iniciação Científica (PIBIC/PICI-UFERSA) e TCCs do curso de Licenciatura Interdisciplinar em Educação do Campo (LEDOC/UFERSA), dissertações de mestrado vinculadas ao Programa Interdisciplinar em Cognição, Tecnologias e Instituições (PPGCTI/UFERSA) e ao Programa de Pós-Graduação em Sociologia (PPGS/UECE), bem como reflexões de convidados/as nacionais e internacionais que contribuíram ao longo da realização do projeto. Três eixos norteiam a obra: o primeiro, está mais diretamente relacionado às discussões que pensam o patrimônio nas suas interfaces com os aspectos da memória e identidade; o segundo, reflete sobre a articulação do patrimônio com a cultura e identidade dos povos do campo; o terceiro se detém sobre assuntos que tangenciam o tema do patrimônio e/ou das ruralidades, enfocando diferentes dimensões tais como a economia, a cultura e a arte.', '["rural heritage","cultural heritage","environmental heritage","rural identity","memory","rural population","rural culture","rural art","rural education","Northeastern Brazilian semi-arid region","rural economy"]', '10.7476/9786587108605', '9786587108605', 'https://books.scielo.org/id/8hp3p', 'https://books.scielo.org/id/8hp3p/pdf/oliveira-9786587108605.pdf', NULL, 'https://books.scielo.org/id/8hp3p/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8hygr', '8hygr', 'Diferentes maneras de conocer: las experiencias recientes de la Escuela Intercultural de Diplomacia Indígena', NULL, '["Santamaría, Ángela","Rojas Oliveros, Pedro"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'El texto que presentamos a ustedes, queridos lectores, no solo recoge el producto de algo más de un año de intenso trabajo de la Escuela Intercultural, estas páginas también intentan mostrar los sentimientos, emociones, propuestas, luchas, limitaciones, errores y energías que ese periodo de tiempo ha traído como enseñanza. Nuestra apuesta académica, laboral y política tiene su punto cero en la confianza en la interculturalidad. La interculturalidad como posibilidad de relacionamiento respetuoso, sí, pero ante todo consciente, de diferentes maneras de conocer, de vivir, de resolver desde la cotidianidad, las injusticias que afectan a la mayoría de los y las colombianas. Confiamos en la educación, en su ejercicio, pero sobre todo en su problematización y reinvención, en la necesidad de construir un conocimiento más humano, donde los discursos y sus categorías no sirvan como mera legitimidad disciplinaria, sino como mecanismo de construcción. Construir un mundo donde quepan todos los mundos, con sus tensiones, antagonismos, disputas y competencias.', '["interculturality","Indigenous diplomacy","intercultural education","ways of knowing","indigenous peoples","education as political act","Colombian indigenous peoples","social injustice"]', '10.7476/9789587386189', '9789587386172', 'https://books.scielo.org/id/8hygr', NULL, NULL, 'https://books.scielo.org/id/8hygr/cover/cover_thumbnail.jpeg', 345, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8jms4', '8jms4', 'As múltiplas faces do PROFCIAMB: impactos nas Ciências Ambientais', NULL, '["Joselisa Maria Chaves","Marjorie Csekö Nolasco","André Luiz Brito Nascimento","Maria Cláudia Silva do Carmo"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'O ProfCiamb, com associadas nas cinco regiões brasileiras, visa a dialogar com os diferentes atores da sociedade objetivando compreender e minimizar os efeitos antrópicos, além de capacitar docentes das redes pública e privada do Ensino Básico para que sejam multiplicadores e despertem nos adolescentes e jovens a responsabilidade com o ambiente. O resultado de todo este esforço, diálogo, pesquisa-ação-extensão resulta na produção de artigos científicos, material de divulgação científica, livros e capítulos de livros que transbordam a transversalidade do conhecimento, seja em projetos agroflorestais, discussões teóricas sobre o tema, ações em meio terrestre e aquático. A pluralidade temática dos capítulos demonstra a riqueza de diversos temas abordados neste livro.', '["environmental science","anthropogenic impacts","teacher professional development","environmental education","youth environmental awareness","agroforestry","action research","science dissemination","interdisciplinary knowledge"]', '10.7476/9786589524946', '9786589524946', 'https://books.scielo.org/id/8jms4', 'https://books.scielo.org/id/8jms4/pdf/chaves-9786589524946.pdf', NULL, 'https://books.scielo.org/id/8jms4/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8jp5s', '8jp5s', 'Pandemia desde la academia: experiencias transdisciplinarias de la universidad cuencana en tiempos de COVID-19', NULL, '["Andrea De Santis-Piras","Álvarez-Rodas, Luis","Jara-Cobos, Victoria","Verdugo-Sánchez, Adriana"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2021, '2021-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Pandemia es una palabra con origen profundo que en el tiempo se ha cargado con la historia de pueblos y naciones, alcanzando su plena expresión en nuestra sociedad globalizada. No solamente por las estadísticas que atraen la atención de todo el mundo y nos obligan a razonar de manera lógico-numérica, cuantitativa, olvidando que muchas veces los números son personas, y no rinden la justa cuenta de todos aquellos seres humanos que representan estas cifras. Una pandemia logra su máxima expresión al alcanzar el mayor número de personas, esto refleja en su etimología proveniente del griego pan (todo) y demos (pueblo) y desde sus orígenes ha significado principalmente una cosa, la “reunión del pueblo”. Dicha noción invita a reflexionar sobre el porqué de las medidas sanitarias, del aislamiento y confinamiento, y, más aún, nos recuerda la importancia de la unión como decisión ancestral al origen de nuestras sociedades, columna portante de la familia, fortaleza de cualquier sistema en desequilibrio. Reconociendo esto, se evidencia la capacidad de transformar juntos las debilidades en fortalezas, de saber demostrar nuestro mejor impulso a la solidaridad y colaboración cuando sentimos que nos necesitan, que permite terminar con alegría un capítulo con la seguridad de que el próximo será mucho mejor. Este espíritu es responsable de la iniciativa de quienes enfrentamos los desafíos del contexto desde la unión, con la aspiración de formar seres humanos en un espacio compartido de generación de conocimiento y conformación de valores humanos y sociales que llamamos Universidad.', '["COVID-19 pandemic","university response to pandemic","transdisciplinary research","higher education","social solidarity","knowledge production"]', '10.7476/9789978106792', '9789978106792', 'https://books.scielo.org/id/8jp5s', 'https://books.scielo.org/id/8jp5s/pdf/de-9789978106792.pdf', NULL, 'https://books.scielo.org/id/8jp5s/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8k3mr', '8k3mr', 'Testamento de André Vidal de Negreiros (1678) - Volume 2', NULL, '["Victória Santana da Silva Araújo","Mariana Fagundes de Oliveira Lacerda","Alícia Duhá Lose","Zenaide de Oliveira Novais Carneiro","Lara da Silva Cardoso"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Foi a partir de 2017 que o projeto Corpus Eletrônico de Documentos Históricos do Sertão (CE-DOHS), do Núcleo de Estudos de Língua Portuguesa (NELP) da Universidade Estadual de Feira de Santana (UEFS), já tendo disponibilizado signicativo material de sua primeira fase de execução (pós-colonial), começou a investir na constituição de corpus ilustrativo do período colonial brasileiro, intensicando a parceria com a Paleograa, com a Diplomática e com a Filologia, para o tratamento de textos de épocas ainda mais recuadas. Destaca-se a parceria com o projeto Modus Scribendi — Grupo de Pesquisas Paleográcas, Diplomáticas, Codicológicas, Filológicas e Históricas, da Universidade Federal da Bahia (UFBA). O trabalho de constituição do corpus colonial do CE-DOHS/NELP representa, entre outros, junto ao Projeto Nacional para a História do Português Brasileiro (PHPB), um avanço de sua agenda de corpus históricodiacrônico, tanto em razão da ampliação do banco de textos — fazendo uma melhor cobertura das fases da periodização da história sociolinguística do Brasil — como em razão do diálogo, com maior grau de maturidade, com a Paleografia, a Diplomática e a Filologia. O ingente trabalho de organização de corpora histórico-diacrônicos é condição sine qua non para desenvolver pesquisas de base empírica, tendo em vista uma melhor compreensão da história do português no/do Brasil e a discussão de questões teóricas solidamente fundamentadas.', '["wills","historical corpora","paleography","diplomatics","17th century"]', '10.7476/9788555921889', '9788555921339', 'https://books.scielo.org/id/8k3mr', NULL, NULL, 'https://books.scielo.org/id/8k3mr/cover/cover_thumbnail.jpeg', 93, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8kf92', '8kf92', 'À sombra do Plátano: crônicas de história da medicina', NULL, '["Joffre Marcondes de Rezende"]', 'Editora Fap-Unifesp', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Carlos da Silva Lacaz pioneiros e incentivadores dos estudos de história da medicina no BrasilPREFáCio E ste livro é mais uma contribuição que o prof.Joffre Marcondes de Rezende, professor emérito da Faculdade de Medicina da Universidade Federal de Goiás, dá à cultura de nosso país.Trata-se de uma coletânea de crônicas sobre história da medicina que o autor escreveu ao longo de sua vida e que mostra uma outra face de seus pendores e de suas atividades, além da prática clínica e da docência em gastroenterologia.Algumas delas são inéditas e muitas outras já publicadas em diferentes órgãos de divulgação.Dado o valor que estas crônicas têm, seria uma lástima se permanecessem dispersas no tempo e no espaço.Reunidas agora neste livro, o leitor terá a oportunidade de desfrutar de todas elas, sem a necessidade de procurá-las individualmente em veículos de publicação que podem ser de difícil acesso e com a tranquilidade de que, em sendo de história, jamais se desatualizam.As crônicas que o leitor vai encontrar neste livro abordam variados temas históricos de todas as épocas, desde a Antiguidade até a atualidade, sendo dignas de nota aquelas referentes à medicina brasileira, algumas com a participação do próprio autor.o livro contém, também, vários relatos -14 -biográficos, inclusive os de personagens com as quais o autor conviveu ou teve relações de amizade.o título que foi escolhido para a obra é muito sugestivo, pois, anuncia o seu conteúdo evocando a figura de Hipócrates.À semelhança do pai da medicina que, à sombra do plátano ainda existente na pequena praça no centro da cidade grega de Cós, ensinava aos seus discípulos, no século v a.C., a surgente medicina baseada na racionalidade, o mestre Joffre conta ao leitor uma série de tópicos de história da medicina que o ajudam a compreender como o saber médico se formou, e a conhecer pontos fascinantes e até curiosos das descobertas que determinaram inequívocos progressos nesta área do conhecimento.não faltam temas polêmicos e de defesa da classe médica, bem como, os modismos que muitas vezes a medicina adotou.Em sua leitura, o leitor poderá verificar muitos exemplos de como fatos e conceitos longamente arraigados na mente das pessoas, mesmo as mais brilhantes, podem dificultar a aceitação dos avanços trazidos pelas novas descobertas, acomodando-se, incondicionalmente, com a "verdade" estabelecida e refutando, insensatamente, a novidade que a contraria.não vou tecer nenhum comentário sobre qualquer das crônicas para que o leitor possa, por si, ter o prazer de desvendar seus conteúdos sem qualquer ideia preconcebida e para não interferir com minha opinião no juízo crítico que fará.opino, entretanto, que são pontos altos deste trabalho, pela felicidade com que o autor transmite o entendimento dos temas e pela sua originalidade, os capítulos "Dos Quatro Humores às Quatro Bases", "Úlcera Péptica e a ilusão do Conhecimento: Um Exemplo de Falácia das Evidências em Medicina" e "Mal de Engasgo e Doença de Chagas: A Solução de um Quebra-cabeças".À Sombra do Plátano é um livro de História da Medicina não no estilo tradicional de descrição longitudinal ou transversal da evolução de conceitos e progressos havidos, seguindo uma trajetória mais ou menos contínua através do tempo.Também, não é com a leitura deste livro que o leitor vai conhecer toda a história da medicina, uma vez que são feitas apenas crônicas sobre eventos isolados ou sobre marcantes personagens desta ciência.E não há necessidade de ler suas cinquenta crônicas na sequência proposta pelo autor, pois uma pode não ter nada a ver com a precedente e nem com a subsequente.o leitor pode escolher os assuntos que lhe pareçam mais interessantes e, sem prejuízo do conjunto, desfrutar da leitura.-15 -Sugiro ao leitor que quando ler À Sombra do Plátano imagine que todas as palavras contidas em cada crônica serão sussurradas em seus ouvidos pelo próprio Hipócrates; como cenário ideal, aconselho que encontre a tranquilidade da sombra de uma árvore, talvez um plátano em uma pequena praça, mas, se isso não for possível, qualquer sombra propícia, até mesmo aquela da sua costumeira sala de leitura.nestas circunstâncias imaginárias, como um discípulo de Hipócrates que dele recebia lições de medicina em situação similar, absorva as coisas de ciência médica que lhe serão contadas.É possível aprender um pouco de medicina conhecendo-se sua história.Se o leitor é médico, estudante de medicina, profissional ou estudante de qualquer área ligada à saúde, este livro ser-lhe-á de melhor compreensão.Se estiver fazendo um curso de história da medicina, a motivação e o aproveitamento serão particularmente grandes.Mas, se o leitor for um simples curioso interessado nas coisas médicas ou em história geral, digo-lhe que, mesmo assim, este livro fará muito bem à sua cultura geral.o autor destas crônicas de história da medicina é médico clínico e professor de medicina com muitos anos de prática e experiência com pacientes e com inestimável acervo de contribuições para o conhecimento da forma digestiva da doença de Chagas, forma esta originalmente por ele denominada e caracterizada.É entusiasmado cultor e pesquisador da história da medicina, um dos fundadores da Sociedade Brasileira de História da Medicina e figura presente e participante em todos os congressos desta entidade.Sua cultura geral e seus sólidos conhecimentos linguísticos aparecem em todas as crônicas contidas neste livro.nele revela-se, também, um exímio contador de histórias pela forma clara de exposição e pela leitura fácil que proporciona, prendendo fortemente a atenção do leitor.o exacerbado humanismo de que é possuidor, no sentido que este termo tem de melhor, revela-se em "A árvore de Hipócrates" quando enuncia os valores perenes da medicina.não diz, mas afirmo que ele sempre os seguiu: a busca da verdade, o respeito à vida, o amor à arte médica, a solidariedade humana, o desejo de servir, a conduta digna, o interesse sincero pelos que sofrem.Conhecendo-o há muitos anos, acrescentaria,', '["history of medicine","Hippocrates","medical education","medical profession","gastroenterology"]', '10.7476/9788561673635', '9788561673635', 'https://books.scielo.org/id/8kf92', 'https://books.scielo.org/id/8kf92/pdf/rezende-9788561673635.pdf', NULL, 'https://books.scielo.org/id/8kf92/cover/cover_thumbnail.jpeg', NULL, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8kg4p', '8kg4p', 'Como pensam as imagens', NULL, '["Etienne Samain"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Uma afirmação nos parece suficientemente estabelecida: toda imagem nos faz pensar. Etienne Samain desdobra essa constatação óbvia numa questão mais complexa: Será que podemos aprofundar esse dado no sentido não tanto de saber “por que” ela nos permite pensar, e sim “como” nos faz pensar? Finalmente, ele chega à pergunta inquietante que lança a si mesmo e a outros nove pesquisadores: Como pensam as imagens?', '["visual cognition","image thinking","philosophy of image","visual perception"]', '10.7476/9788526814738', '9788526809611', 'https://books.scielo.org/id/8kg4p', NULL, NULL, 'https://books.scielo.org/id/8kg4p/cover/cover_thumbnail.jpeg', 239, 48, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8ks9h', '8ks9h', 'Rupturas e encontros com desafios da reforma psiquiátrica brasileira', NULL, '["Sílvio Yasui"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Urquiza, Tiana, Emiron e tantos outros e outras que fizeram e fazem real aquele sonho.Ali pude acompanhar a sua sensibilidade clínica e de reabilitação psicossocial, plenamente articuladas.Seu violão bem afinado atraía pessoas, harmonizava espíritos, estabilizava delírios e alucinações, que o seu estilo zen de escuta tratava de ouvir e decifrar, para transformar temores em modos de viver a vida.Estivemos juntos na primeira iniciativa de aproximar "fazejamento" e "pensação", como sempre quis o nosso David Capistrano, descrevendo, avaliando e produzindo teoria em serviço comunitário de saúde mental no país."Avaliação de serviço de atenção médico-psicossocial a usuários de sistema de saúde no município de São Paulo", 1990, foi um projeto de pesquisa financiada pelo Banco Mundial para avaliar serviços de saúde.Abrigado no Departamento de Medicina Preventiva da Faculdade de Medicina da Universidade de São Paulo (FM-USP), foi também a chance de conhecer outro Silvio Yasui, arguto e persistente indagador de métodos e técnicas de investigação que nos fizessem desvendar os mistérios de uma prática recente que tanto nos inquietava: lidar com a loucura fora do manicômio.O dilema ''quali-quanti'' nos motivava ao debate, nas sessões noturnas, nas jornadas estendidas de trabalho de um técnico que não se satisfazia com as atividades assistenciais que estavam prescritas no seu contrato de trabalho e dedicava o tempo livre ao desafio do conhecimento.A vocação docente-assistencial desse Caps sempre o colocou no lugar de mestre-aprendiz, acolhendo, compartindo, aprendendo, ensinando... APRESENTAÇÃODos muitos modos possíveis para se iniciar este livro, optei pelo caminho da poesia.Não sou nordestino, embora tenha por eles uma boa dose de admiração.O que tenho em comum com o início deste belo poema de João Cabral de Melo Neto é que sou filho de imigrantes e desejo me apresentar e introduzir este trabalho, que é fruto de uma tese de doutorado defendida em 2006, na Escola Nacional de Saúde Pública Sergio Arouca da Fundação Oswaldo Cruz (Ensp/Fiocruz), no Rio de Janeiro.Trata-se de um trabalho que tem o sentido de alguém que se movimenta, que transita, se desloca em busca de algo.Severino foi à busca do mar e encontrou a pobreza, a morte, a dor, mas também a esperança no espetáculo da vida; vendo-a desfiar seu fio que teimosamente se fabrica; vendo-a brotar em uma nova vida que explodia, ainda que franzina, ainda que de mais uma vida severina.Já este que se apresenta ao leitor, com certeza, não tem esse suave dom da poesia, embora, para contar das coisas duras da vida, tenha a teimosa persistência dos que caminham.E como somos muitos os caminhantes nas veredas destes sertões, de muitas sinas e destinos -e se me permitem a ousadia e certo excesso, gostaria de apresentar o meu caminho, que resultou neste trabalho.Comecei a me interessar pelo campo da saúde mental em 1976, no segundo ano do curso de Psicologia, quando tive a oportunidade de realizar um estágio voluntário em um hospital psiquiátrico.Conheci cedo a dura realidade da instituição psiquiátrica, dos maus-tratos, do abandono.Um dos primeiros pacientes com quem tive contato me marcou profundamente.Era um homem de uns 45 anos, com uma bela voz.Estava ensaiando uma pequena peça de teatro e solicitei a ele que fosse o narrador da história.De pronto, pegou o microfone, ajeitou-se e encantou a todos com uma possante e bonita voz.Perguntei-lhe o que fazia antes de ser internado, e ele me contou que era locutor de uma importante rádio de São Paulo.Estava quase um ano internado.O motivo: alcoolismo.Ele assegurava que estava bem, que já podia e queria sair, mas o "doutor" não autorizava.Soube, mais tarde, que esse era um procedimento comum nos hospitais psiquiátricos, manter os pacientes alcoolistas, pois, em abstinência, eram excelentes para as tarefas cotidianas do hospital e acabavam sendo utilizados como mão de obra barata.Percebi, com a peça de teatro, que aqueles a quem se nomeavam loucos, doidos, doentes mentais, eram pessoas interessantes, agradáveis, com histórias de vida intensas e, apesar das crises que apresentavam, vez ou outra, mantinham um contato pessoal e afetivo.E precisavam de pouco: serem reconhecidos e respeitados.Essa experiência marcou profundamente minha vida.Ainda que de uma forma não muito clara, decidi ali com o que gostaria de trabalhar.Poucos anos após minha formatura, ao final de 1983, assumi a função de psicólogo no Departamento Psiquiátrico II, nacionalmente conhecido como Hospital Psiquiátrico de Juqueri (São Paulo).Meu primeiro contato foi com o diretor clínico do hospital, que me contava sobre os diferentes projetos que estavam iniciando, um pouco para me seduzir com um deles, chamado "Lar abrigado", que acabei por integrar.Aquele foi um importante encontro.Havia uma expectativa de diversos médicos para que eu fosse trabalhar com os residentes, aplicando testes projetivos e realizando psicoterapia nos pacientes por eles indicados, como forma de ampliar as discussões clínicas psiquiátricas.Embora pressionado, o diretor clínico sustentou minha escolha em trabalhar no "Lar abrigado''.Começava ali uma trajetória profissional, a qual me remeteria a construir/inventar uma forma diferente de atuar.Aqueles eram tempos diferentes.Um governo estadual eleito democraticamente, um sanitarista como secretário da Saúde.Vários profissionais recém-contratados, imbuídos do espírito de trabalhar para mudar e transformar.O clima de mudança e participação estava presente na cena brasileira naqueles anos.Em 1984, houve a campanha das Diretas-Já, que resgatou nossa capacidade coletiva de participação em eventos políticos grandiosos.Depois, veio a eleição indireta de Tancredo Neves e a sua morte.Então, assumiu seu vice, José Sarney, dando início à Nova República.A verdadeira desinstitucionalização em Psiquiatria tornou-se na Itália um processo social complexo que tende a mobilizar como atores os sujeitos sociais envolvidos, que tende a transformar as relações de poder entre os pacientes e as instituições, que tende a produzir estruturas de Saúde Mental que substituam inteiramente a internação no Hospital Psiquiátrico e que nascem da desmontagem e reconversão dos recursos humanos e materiais que estavam ali depositados.(Rotelli, Leonardi & Mauri 2001: 18) Esse processo envolve, ainda, desinstitucionalizar o paradigma psiquiátrico, ou seja, reconstruir a complexidade do objeto, desmontando o conceito de doença, retomando o contato com a existência e o sofrimento do sujeito e sua ligação com o corpo social, não mais para curar, mas para a produção de vida, de sentidos, de sociabilidade e de espaços coletivos de convivência.Amarante (2003) toma emprestado esse conceito e aplica-o ao processo de transformação da assistência em saúde mental, isto é, a Reforma Psiquiátrica.Embora a palavra ''reforma'' não contemple a amplitude de tal processo, podendo ser associada a mudanças meramente superficiais, ou mudanças para não mudar, é um conceito consagrado que guarda estreita e profunda ligação histórica com o Movimento Sanitário e a Reforma Sanitária.Em comum, ideais e utopias, problemas e dilemas, contradições e desafios.Ao analisar a prática científica da Reforma Sanitária, Dâmaso (1995: 73) ressalta, a propósito das limitações do termo ''reforma'': "Em que pese a sua ameaça reformista, o conceito de Reforma Sanitária tem, todavia, um sentido "forte": trata-se de conceber e fazer da saúde o fundamento revolucionário de uma transformação setorial, com ressonâncias estruturais sobre o conjunto da sociedade".O termo ''forte'' é igualmente empregado por Rotelli, Leonardi e Mauri (2001) para definir um serviço inteiramente substitutivo à internação, que responde à complexidade das necessidades, antes absorvidas pelo asilo psiquiátrico.Nessa perspectiva, pretendo contribuir para a construção de uma conceituação ''forte'' da Reforma Psiquiátrica, ou seja, superar a ideia de um reformismo simplista, restrito a uma mudança técnica ou administ', '["psychiatric reform","community mental health services","psychosocial rehabilitation","psychiatric hospitalization","deinstitutionalization","mental health services evaluation","qualitative and quantitative research","João Cabral de Melo Neto","immigrant identity"]', '10.7476/9788575413623', '9788575413623', 'https://books.scielo.org/id/8ks9h', 'https://books.scielo.org/id/8ks9h/pdf/yasui-9788575413623.pdf', NULL, 'https://books.scielo.org/id/8ks9h/cover/cover_thumbnail.jpeg', NULL, 57, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8kw7f', '8kw7f', 'Autoritarismo e Corporativismo no Brasil: (Oliveira Vianna &amp; Companhia)', NULL, '["Evaldo Amaro Vieira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro situa-se na linha dos estudos críticos sobre o corporativismo e o autoritarismo. Oliveira Vianna desenvolve sua obra entre 1918 e 1951, assistindo a dois momentos conjunturais da industrialização brasileira: 1918 e 1937. Sua obra constitui, como bem acentua Evaldo Vieira, na Conclusão, uma tentativa de sistematização ideológica dos princípios de uma revolução conservadora, entendida como uma "revolução burguesa retardada". Dentro desse ideário, o "Estado Corporativo é a essência deste projeto de contrarrevolução", já que Oliveira Vianna rejeita a transformação social, limitando-se a um projeto de reformas para evitar mudanças estruturais. Seus escritos são uma resposta à Revolução de 1930, que leva a uma crise de hegemonia, somente resolvida após o Golpe de Estado de 1937, dado por Getúlio Vargas. O que Oliveira Vianna pretende é a transformação da classe dirigente em classe dominante.', '["Oliveira Vianna","corporatism","authoritarianism","conservative revolution","Estado Novo","Getúlio Vargas","industrialization","class hegemony","Brazilian political thought"]', '10.7476/9788539304318', '9788539300020', 'https://books.scielo.org/id/8kw7f', NULL, NULL, 'https://books.scielo.org/id/8kw7f/cover/cover_thumbnail.jpeg', 162, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8m665', '8m665', 'Uma ciência da diferença: sexo e gênero na medicina da mulher', NULL, '["Fabíola Rohden"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2001, '2001-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Citem-se como exemplos os trabalhos de Laget (1982), Knibiehler e Fouquet (1983), Gélis (1984), Thébaud (1986) e Fay-Sallois (1997).5 Aqui está se falando do debate em torno da chamada ''história das mulheres'' ou de uma história que assuma radicalmente a perspectiva relacional implicada nos estudos de gênero.', '["gender","sex","women''s medicine","women''s history","gender studies","relational approach","women''s health"]', '10.7476/9788575413999', '9788575413999', 'https://books.scielo.org/id/8m665', 'https://books.scielo.org/id/8m665/pdf/rohden-9788575413999.pdf', NULL, 'https://books.scielo.org/id/8m665/cover/cover_thumbnail.jpeg', NULL, 85, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8m7zk', '8m7zk', 'Práticas de modelagem matemática na educação matemática', NULL, '["Lourdes María Werle de Almeida","Jussara de Loiola Araújo","Eleni Bisognin"]', 'Educação Matemática em Revista', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] Tendo como foco a formação de professores, ações em sala de aula, tecnologias de informática, a Modelagem Matemática em espaços extracurriculares e a Modelagem Matemática na perspectiva da Educação Matemática Crítica, a obra representa uma valiosa contribuição para repensar e construir um novo sentido para o ensino e a aprendizagem da Matemática.', '["mathematical modeling","mathematics education","teacher professional development","extracurricular activities","critical mathematics education","information technology in mathematics teaching","teaching practice"]', '10.7476/9788572166508', '9788572166508', 'https://books.scielo.org/id/8m7zk', NULL, NULL, 'https://books.scielo.org/id/8m7zk/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8m95t', '8m95t', 'Desenvolvimentismo: o conceito, as bases teóricas e as políticas', NULL, '["Ricardo Dathein"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'O livro busca contribuir na discussão teórica e de políticas sobre o desenvolvimento econômico, partindo das concepções sobre o desenvolvimentismo e o Estado desenvolvimentista, analisando suas diferentes e possíveis bases teóricas atuais, que, muitas vezes, são complementares. Assim, em seus capítulos, estudam-se as abordagens institucionalistas, as concepções evolucionárias ou neoschumpeterianas, a teoria keynesiana e a visão marxista, sempre levando em conta as experiências internacionais e a história do desenvolvimento. O desenvolvimento econômico continua sendo um desafio essencial para o Brasil, assim como para a maioria dos países. Apesar das melhorias sociais e do desempenho econômico dos últimos anos, depois de mais de duas décadas de semiestagnação, o país ainda está longe de diminuir para níveis adequados suas principais contradições. Os principais fatores estruturais que impedem o desenvolvimento continuam presentes no país, e alguns, inclusive, têm se acentuado. É por isso que o desenvolvimentismo continua atual e essencial para o futuro da sociedade brasileira. A sedução do liberalismo, com sua ideologia individualista, é muito forte, mas não é o caminho para o desenvolvimento econômico e social.A concentração de renda, a pobreza, a heterogeneidade estrutural e a inserção econômica internacional continuam em padrões longe dos apropriados. Nos indicadores de desempenho econômico e social, o Brasil costuma se posicionar em níveis ainda muito distantes dos alcançados por países desenvolvidos, e mesmo também dos atingidos por outros países em processo de desenvolvimento. Além disso, a existência de uma cultura conservadora entre as elites e o surgimento de evidências de desindustrialização podem significar uma perda de perspectiva de superação do subdesenvolvimento ou de adiamento para o longo prazo do catching up, ao contrário do que ocorre em alguns países que têm, em poucas décadas, superado o subdesenvolvimento.', '["developmentalism","developmental state","economic development policy","institutionalism","evolutionary economics","Schumpeterian economics","Keynesian economics","Marxist theory","income concentration","poverty","structural heterogeneity","catching up"]', '10.7476/9788538603825', '9788538603825', 'https://books.scielo.org/id/8m95t', 'https://books.scielo.org/id/8m95t/pdf/dathein-9788538603825.pdf', NULL, 'https://books.scielo.org/id/8m95t/cover/cover_thumbnail.jpeg', NULL, 43, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8mp76', '8mp76', 'Geografía rural latinoamericana: temas de investigación y perspectivas de futuro', NULL, '["Meylin Alvarado Sánchez"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'O livro é fruto do convênio entre a UERJ e a Universidade Nacional da Costa Rica (UNA), com o objetivo de trazer a público a dinâmica dos estudos no âmbito da geografia rural da região latino-americana. As abordagens da relação entre campo e cidade na América Latina ganharam novos contornos a partir da tendência dos espaços rurais de se desenvolverem também na área do turismo, agronegócios, agroindústrias rurais e em outros serviços, sem se restringirem a atividades agrícolas. Esse panorama afetou o cenário do campo e o espaço urbano, ocasionando diferentes critérios teóricos e metodológicos de pesquisa acadêmica, assim como a descoberta de novos objetos de estudo, revelados nesta coletânea. A publicação integra pesquisadores dos países da América Latina, e o conjunto de capítulos evidencia a diversidade e a relevância dos estudos realizados.', '["rural geography","Latin America","urban-rural relations","rural tourism","agribusiness","rural agroindustry","rural development","future research directions"]', '10.7476/9786587949321', '9786587949321', 'https://books.scielo.org/id/8mp76', 'https://books.scielo.org/id/8mp76/pdf/marafon-9786587949321.pdf', NULL, 'https://books.scielo.org/id/8mp76/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8n3jz', '8n3jz', 'Histórias de africanos e seus descendentes no sul da Bahia', NULL, '["Cristiane Batista da Silva Santos"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Como viviam os africanos e seus descendentes no Sul da Bahia entre o final do século XIX e início do XX? Este livro é um convite para conhecer o cotidiano de trabalho, festas, lutas judiciais, práticas culturais e religiosas. Tomando como marco a abolição, recorre a variadas fontes, analisando duas décadas anteriores e posteriores desvelando centelhas de experiências e reivindicando um lugar para esses sujeitos na Historiografia Regional.', '["African descendants","southern Bahia","abolition of slavery","everyday life","work","festivals","cultural practices","religious practice","regional historiography","late 19th century","early 20th century"]', '10.7476/9786586213218', '9786586213218', 'https://books.scielo.org/id/8n3jz', 'https://books.scielo.org/id/8n3jz/pdf/santos-9786586213218.pdf', NULL, 'https://books.scielo.org/id/8n3jz/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8n5gr', '8n5gr', 'No tempo da in-presença: relato das práticas de criação em Letras e Artes', NULL, '["Rękawek, Jolanta"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro O Tempo da In-Presença é o relato sobre os processos criativos desenvolvidos pelos membros da comunidade universitária da UEFS, a qual, apesar da necessidade do distanciamento social, continuou o seu labor de ensino, pesquisa e extensão. A obra do Coletivo Criativo Bandoleiros de Arcádia é uma mensagem de vida no tempo da morte que enviam ao mundo os arteviventes: os escritores e artistas visuais que sobreviveram à pandemia, salvos pelo vínculo que criaram juntos através da arte.', '["COVID-19 pandemic","social distancing","creative practice","university community","teaching, research and extension","creative groups","artists and writers","art and survival"]', '10.7476/9786589524991', '9786589524137', 'https://books.scielo.org/id/8n5gr', NULL, NULL, 'https://books.scielo.org/id/8n5gr/cover/cover_thumbnail.jpeg', 221, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8n5rh', '8n5rh', 'O hospício da praia vermelha: do Império à República (Rio de Janeiro, 1852-1944)', NULL, '["Venancio, Ana Teresa A.","Teixeira, Allister"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-12-05', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Os pesquisadores Ana Teresa Venancio e Allister Dias se cercaram de um grupo seleto e muito rico de especialistas para levar a cabo um de esses trabalhos específicos e concretos. Esta história do Hospital Nacional de Alienados (anteriormente Hospício de Pedro II), assim como trabalhos prévios de alguns dos autores participantes, situa-se em uma linha de investigação com repercussão internacional. Como os próprios coordenadores do livro indicam, a emblemática instituição brasileira já tem sido objeto de numerosos estudos, mas, neste caso, as contribuições tanto metodológicas como de conteúdo fazem deste livro coletivo um produto novo e original.', '["psychiatric hospitals","history of psychiatry","institutionalization of the mentally ill","Rio de Janeiro","Brazilian Empire","Brazilian Republic"]', '10.7476/9786557081723', '9786557081389', 'https://books.scielo.org/id/8n5rh', NULL, NULL, 'https://books.scielo.org/id/8n5rh/cover/cover_thumbnail.jpeg', 552, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8n8gb', '8n8gb', 'Travessias pela literatura portuguesa: estudos críticos de Saramago a Vieira', NULL, '["Aldinida Medeiros"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Vieira e a alegoria dos teólogos e do Renascimento Marcelle Ventura Carvalho 12Portuguesas seja a sua única obra conhecida, esta costuma ser olvidada pela crítica.Conceição Flores assina o primeiro estudo, intitulado «Viagem à Ilha (Des)conhecida», que analisa um Saramago menos abordado, o autor de contos, centrando-se na narrativa O Conto da Ilha Desconhecida, texto de 1997.Também a contemporânea Lídia de Jorge, sobremaneira afamada como romancista, é analisada enquanto contista: o terceiro ensaio, intitulado «Ser e ainda não ser: oscilação e iniciação em "O Belo Adormecido" antecedido de "A Arte do Conto" de Lídia Jorge -considerações», da autoria de Tiago Aires, aborda uma narrativa breve de Lídia Jorge dada à estampa em 2004.O artigo que parece escapar mais a este padrão é o segundo do volume, de título «A metanarrativa em António Lobo Antunes», da autoria de Rosângela de Melo Rodrigues, e que se debruça sobre os romances Que Cavalos São Aqueles que Fazem Sombra no Mar?(2009) e Os Cus de Judas (1979).Se este último é um óbvio, isto é, um incontornável na produção de Lobo Antunes, pela fama e pelos prêmios que granjeou, já em relação ao primeiro romance, não houve a mesma euforia da crítica e do público e nem existe ainda o distanciamento temporal necessário para se aferir da sua canonicidade, além de que o cotejo feito por Rosângela de Melo Rodrigues entre as duas narrativas de Lobo Antunes é de uma fina agudeza, lançando um novo olhar sobre este autor.Portanto, parece haver um padrão que consiste na procura de facetas originais ou menos conhecidas de autores portugueses de reconhecida qualidade literária.O quarto artigo, intitulado «Livro do Desassossego: um evangelho por escrever», de Cláudia Sousa, debruça-se sobre a obra do semi-heterônimo 14 Alcoforado era ela própria uma figura que, na sua época, tinha de ombrear com nomes como D. Francisco Manuel de Melo ou Padre António Vieira.O artigo que encerra este volume é dedicado à oratória deste último.Intitula-se «Vieira e a alegoria dos teólogos e do Renascimento», com autoria de Marcelle Ventura Carvalho.Fica assim escrupulosamente cumprida a sintagmática do subtítulo desta obra ensaística, que começa em Saramago e termina em Vieira.O trabalho de Ventura Carvalho debruça-se sobre cinco sermões do brilhante orador jesuíta, e não apenas sobre os dois mais propalados e que manifestam a marca da sua genialiadade: para além do Sermão de Santo António aos Peixes e do Sermão da Sexagésima, são abordados o Sermão da Terceira Dominga da Quaresma, o Sermão dos Bons Anos e o Sermão da Degolação de São João Baptista.Ao longo desta elencagem e sucinta apresentação de cada um dos artigos que compõem o ensaio Travessias pela Literatura Portuguesa: estudos críticos de Saramago a Vieira penso ter ficado comprovada a aposta séria em facetas menos divulgadas de grandes autores portugueses de épocas diversas -esse o fio condutor do livro -, o que traduz uma grande mais-valia para os seus estudiosos, não só no Brasil, mas também neste Portugal de onde escrevo.Abrindo agora um pouco mais o véu a cada um desses artigos, para suscitar o gosto da sua leitura, Conceição Flores em «Viagem à Ilha (Des)conhecida», evoca com grande agudeza Camões para dar o sentido da subversão patente no texto saramaguiano O Conto da Ilha Desconhecida, encomendado para a Expo 98 de Lisboa, cujo tema era «Oceanos: um patrimônio para o futuro»:', '["Portuguese literature","literary criticism","José Saramago","Vieira","Lídia Jorge","António Lobo Antunes","short stories","metanarrative","Renaissance","Os cus de Judas"]', '10.7476/9788578792794', '9788578792794', 'https://books.scielo.org/id/8n8gb', 'https://books.scielo.org/id/8n8gb/pdf/medeiros-9788578792794.pdf', NULL, 'https://books.scielo.org/id/8n8gb/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8nbc4', '8nbc4', 'Reuniões dialógicas de Redes Sociais: formas de dialogismo no trabalho psicossocial', NULL, '["Jaakko Seikkula","Tom Erik Arnkil"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A leitura deste livro certamente será apreciada por um público que transcende os círculos formados pelos profissionais da saúde e pelos que trabalham em dispositivos de assistência social ou de educação, de participação social de construção de práticas coletivas em geral. Além dos Diálogos Abertos, protagonizados fundamentalmente por Jaakko Seikkula, o livro nos apresenta os Diálogos Antecipatórios, desenvolvidos por Tom Erik Arnkil; duas inovações que, além de terapêuticas, demarcam uma nova forma de pensar sujeitos coletivos e com eles lidar. Por esse e outros motivos, já foi traduzido em mais de 15 idiomas diferentes, o que nos dá uma ideia da sua enorme receptividade e de sua amplitude política e acadêmica.', '["social networks","dialogism","psychosocial work","collective subject","social assistance","social participation (health and rehabilitation)"]', '10.7476/9786557080818', '9786557080221', 'https://books.scielo.org/id/8nbc4', NULL, NULL, 'https://books.scielo.org/id/8nbc4/cover/cover_thumbnail.jpeg', 260, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8nq45', '8nq45', 'Reforma radical en el estado de Santander, 1850-1885', NULL, '["Juan Gonzalo Zapata Giraldo"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A lo largo del siglo xix el país se vio obligado a definirse en favor o en contra de tres modelos políticos que tenían grandes diferencias entre sí. Por supuesto, uno de estos era el radical, que finalmente fue derrotado por uno mucho más fuerte, que logró imponerse durante un periodo muy largo. Sin embargo, durante los años radicales se vivieron una expansión económica y un progreso social importantes que poco se han valorado, pues a lo largo de casi treinta años del siglo xix el discurso y la política nacional yregional se movieron alrededor de las reformas radicales. Así, este extenso periodo de Gobierno conocido como la hegemonía radical permite mostrar en este libro cuáles fueron las políticas abanderadas por este grupo político y cuál fue su impacto tanto en el Gobierno Federal como en las regiones, pues su influencia en algunas fue permanente, pese al interés de los conservadores por anularlas. Un ejemplo de esta hegemonía es Santander, un estado que construirían los radicales, parte de una federación, laico, con vocación de estimular la actividad económica y donde s reconocía el papel que deberían desempeñar los empresarios y los comerciantes para lograr el anhelado progreso económico. Este libro permitirá conocer en detalle la puesta en marcha de las reformas en algunos sectores, analizar sus fuentes de financiamiento y los criterios para canalizar los recursos a algunos sectores del gasto público que consideraron prioritario y entender las novedosas herramientas administrativas utilizadas por los radicales, y con ello emitir un juicio final sobre sus políticas.', '["radical reform","Colombian political history","19th-century Colombia","regional government","public finance","economic development","federalism","secularism","public spending priorities","administrative tools","conservative opposition"]', '10.7476/9789587387049', '9789587387032', 'https://books.scielo.org/id/8nq45', NULL, NULL, 'https://books.scielo.org/id/8nq45/cover/cover_thumbnail.jpeg', 364, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8nwvg', '8nwvg', 'Potencialidades da fotografia hoje', NULL, '["Eriel Araujo","Michel de Oliveira","Renata Voss Chagas"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A coletânea Potencialidades da fotografia hoje reúne o pensamento crítico-criativo de sete pesquisadoras e pesquisadores da fotografia, que apresentam como ponto de contato a relação crítico-criativa, pois, além de se dedicarem à pesquisa e análise formal, se dedicam às possibilidades criativas do fazer fotográfico, como artistas ou na prática da curadoria. Os capítulos reunidos nesta obra destacam como a fotografia é multifacetada, possibilitando abordagens criativas, críticas, políticas, estéticas e sociais, proporcionando uma visão abrangente e crítica do papel da fotografia na sociedade atual. Ao mergulhar nas reflexões apresentadas na coletânea, os leitores e leitoras são convidados(as) a expandirem essas ideias em suas próprias experiências e vivências.', '["photography","critical and creative thinking","photographic practice","photography as art","curation","photography and society","photographic aesthetics","photography and politics"]', '10.7476/9786556309316', '9786556307701', 'https://books.scielo.org/id/8nwvg', 'https://books.scielo.org/id/8nwvg/pdf/araujo-9786556309316.pdf', NULL, 'https://books.scielo.org/id/8nwvg/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
