excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8pk8p', '8pk8p', 'Visões do Brasil: estudos culturais em geografia', NULL, '["Francine Barthe-Deloizy","Ângelo Serpa"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta é a tradução para português dos artigos que compuseram o número especial da revista francesa Géographie et Cultures, intitulado Vu du Brésil. Explora a dinâmica da pesquisa em Geografia Cultural desenvolvida no Brasil, bem como questionamentos que permeiam esta produção, ainda pouco conhecida na França. Temas como hibridismo cultural, transculturação, multiterritorialidade, “maritimidade”, fronteiras sociais e territoriais, assim como temáticas específicas do contexto cultural brasileiro – o futebol, as festas juninas, a capoeira e o fandango – são abordados com o objetivo de aquecer o debate acerca da questão identitária brasileira.', '["cultural geography","Brazilian cultural identity","cultural hybridity","transculturation","multiterritoriality","maritimity","football","capoeira","fandango"]', '10.7476/9788523212384', '9788523212384', 'https://books.scielo.org/id/8pk8p', 'https://books.scielo.org/id/8pk8p/pdf/barthe-9788523212384.pdf', NULL, 'https://books.scielo.org/id/8pk8p/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8pmmy', '8pmmy', 'A saúde no Brasil em 2030: população e perfil sanitário - Vol. 2', NULL, '["Fundação Oswaldo Cruz"]', 'Fiocruz/Ipea/Ministério da Saúde/Secretaria de Assuntos Estratégicos da Presidência da República', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'PrefácioA Fundação Oswaldo Cruz (Fiocruz), em sua condição de instituição pública estratégica para a Saúde, é agente da dinâmica do desenvolvimento do Estado brasileiro e assim se apresenta ao governo e à sociedade.Essa dimensão estratégica é referência para seu planejamento, sua inserção nas políticas governamentais e seus compromissos com a sociedade.Este livro é fruto do projeto Saúde Brasil 2030, desenvolvido no bojo do acordo de cooperação técnica assinado pela Fiocruz com a Secretaria de Assuntos Estratégicos da Presidência da República (SAE) e o Instituto de Pesquisa Econômica Aplicada (Ipea) e de convênio pactuado com o Ministério da Saúde.O projeto Saúde Brasil 2030 tem como principal objetivo a constituição de uma rede permanente de prospectiva estratégica no campo da saúde.Os textos resultantes dessa iniciativa, aqui apresentados em sua versão integral, especulam sobre a probabilidade de futuros para a Saúde em 2030, com referência ao ano de 2022, quando se comemora o bicentenário da Independência do Brasil.Diante dos desafios que o futuro traz, cabe ao Estado articular e induzir políticas econômicas e sociais, no interesse do desenvolvimento com equidade, fomentando o acesso e a inclusão de camadas excluídas, expandindo e assegurando direitos sociais às parcelas significativas da população ainda marginalizadas e sem os ganhos advindos do progresso e da riqueza.O setor Saúde contribui de forma crescente para o dinamismo econômico das sociedades, e sua integração com outros setores, como Ciência e Tecnologia, Educação, Comércio Exterior e Política Industrial, entre outros, pode influir decisivamente no modelo de desenvolvimento de nosso país.É imperioso planejar em prazos mais longos, dada a complexidade do setor Saúde e dos nítidos processos de transformação e inovação em curso nas suas diversas áreas de atuação.Não se trata apenas de criar imagens de futuro, mas, especialmente, de auxiliar na gestão estratégica, mediante diretrizes para o alinhamento das ações com um cenário de futuro desejável para nosso país.Os textos aqui apresentados são o ponto de partida do esforço prospectivo, e não seu resultado.São lançados a debate público por especialistas a partir de sua conclusão.Com isso a Fiocruz contribui para a formulação de políticas públicas em saúde, educação, ciência e tecnologia e inovação em saúde, reafirmando sua posição na defesa e fortalecimento do Sistema Único de Saúde (SUS), por seu desenvolvimento e alcance de padrão sustentável, assegurando a realização plena de seus princípios e possibilitando as necessárias conquistas sociossanitárias. Paulo Gadelha Presidente da Fiocruz ApresentaçãoEste volume, População e Perfil Sanitário -, analisa os determinantes sociais, econômicos e ambientais da Saúde, abordando o cenário sociodemográfico em 2022 e 2030, a distribuição territorial da população, traçando um diagnóstico do comportamento atual dos fenômenos demográficos no país e refletindo a respeito das tendências futuras desses processos.Examina-se, ainda, o perfil epidemiológico no horizonte temporal proposto, assinalando-se os problemas de saúde que vêm se agravando, como a violência, a dengue, o diabetes, a obesidade, ao lado das doenças transmissíveis, endemias, epidemias e pandemias que configuram riscos sanitários para o país no futuro próximo.O esforço inicial do projeto Saúde Brasil 2030 consistiu em percorrer os temas mais relevantes para o desenho de horizontes futuros do sistema de prestação de cuidados à saúde no Brasil, tendo como ano de referência 2030.Nesta primeira etapa, esses temas foram organizados em blocos e, para cada um deles, identificados com base no conhecimento já produzido e acumulado os elementos essenciais que os compõem e que permitem o desenvolvimento do exercício prospectivo, bem como as lacunas de conhecimento a serem preenchidas.O produto desta etapa é publicado e divulgado para debate público, orientando a conformação de redes de conhecimento que serão constituídas para as etapas subsequentes do projeto.Adotou-se como metodologia a chamada prospecção estratégica, que teve suas origens, nos anos 1980, no campo da administração e foi empregada, posteriormente, no domínio das políticas públicas (HABEGGER, 2010).1 Para esse autor, a prospecção estratégica pode ser definida como uma tentativa deliberada de alargar as "fronteiras da percepção" e expandir a capacidade de atenção em relação a temas e situações emergentes.A prospecção estratégica, de acordo com Habegger, citando uma proposta de Müller, integra as perspectivas, procedimentos e ferramentas tanto das pesquisas de tendências quanto dos estudos de futuros.De um lado, a pesquisa de tendências lida com a detecção precoce e interpretação nos campos econômico, político, social e tecnológico e objetiva avaliar o impacto das mudanças tanto na sociedade como nos indivíduos.Os estudos de futuro, por outro lado, capturam e antecipam desenvolvimentos futuros nesses domínios, de modo a gerar visões de como a sociedade evolui e das opções de políticas que estão disponíveis para se modelar um futuro desejado.Para Habegger, o processo de prospecção estratégica pode ser conceituado e implementado de várias maneiras, mas a maioria dos estudiosos segue uma lógica bastante semelhante que divide tal processo em três fases:• a detecção precoce e a análise da informação;• a geração de conhecimento prospectivo;• o desenvolvimento das opções (de políticas) futuras.A primeira fase envolve a identificação e o monitoramento contínuo dos temas, tendências, desenvolvimento e mudanças dos processos em estudo.A segunda fase implica a avaliação e entendimento dos desafios para a implementação das diferentes políticas.E a terceira assenta-se na formulação dos futuros desejados e das ações políticas necessárias para alcançá-los.Isso implica explorar diversos "futuros" ou cenários alternativos.Neste contexto prospectivo, assumimos três cenários alternativos:• cenário desejável e possível;• cenário inercial e provável;• cenário pessimista e plausível.Impôs-se às categorias de "futuros" desejáveis a condição de possibilidade, isto é, a capacidade de concretização no horizonte temporal contemplado.Este esquema (Figura 1), em que os horizontes possíveis foram estabelecidos apenas como diretrizes de políticas desejáveis, é inspirado por Voros.Figura 01.Cone de "Futuros" Fonte: Voros, J.A generic foresight process framework, Foresight 5 (3) (2003) 10-21, citado por Habegger B. Strategic foresight in public policy: Reviewing the experiences of the UK, Singapore, and the Netherlands.Futures 42 (2010) 49-58.Tempo Agora Potencial Provável Preferível Plausível PossívelNos estudos procurou-se especular, com razoável fundamentação, sobre a probabilidade desses futuros.Consistem em textos de partida para o esforço prospectivo, e não o seu resultado.Devem ser considerados, assim, como termos de referência em torno dos quais se prolongará a prospecção estratégica para cada um dos domínios abordados, através da constituição de uma rede de conhecimento para ampliação e amplificação do debate e dos estudos futuros que serão desencadeados a partir desta aventura inicial.O volume 1, Desenvolvimento, Estado e Políticas de Saúde, objetiva desenhar um pano de fundo para os outros capítulos diretamente voltados para a questão da saúde.Abrange os seguintes temas: cenários de desenvolvimento para 2022-2030, os eixos para o desenvolvimento do país, a saúde na política nacional de desenvolvimento, a gestão pública no Século XXI, e o Brasil na arena internacional como nação soberana e cooperativa.No Volume 3 são tratados temas relacionados à Organização e Gestão do Sistema de Saúde, assinalando-se os princípios do sistema de saúde brasileiro.Inicialmente, aborda-se a gestão do nível federal do sistema (administração direta, agências reguladoras, fundações nacionais, empresas públicas nacionais) na condução da política nacional e na gestão do sistema de saúde no Brasil.No capítulo "A coordenação federativ', '["health system planning","population projections","health profile","strategic foresight","health policy","health equity","health care financing","health technology innovation","health system resilience","health system integration"]', '10.7476/9788581100166', '9788581100166', 'https://books.scielo.org/id/8pmmy', 'https://books.scielo.org/id/8pmmy/pdf/noronha-9788581100166.pdf', NULL, 'https://books.scielo.org/id/8pmmy/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8q677', '8q677', 'Álcool e outras drogas: diálogos sobre um mal-estar contemporâneo', NULL, '["Sergio Arciniegas Alarcón","Marco Aurélio Soares Jorge"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Psicólogos, enfermeiros, assistentes sociais, médicos, terapeutas ocupacionais, nutricionistas: ao todo, 28 autores com variados perfis e experiências produziram os 16 capítulos deste livro, cujas análises, muitas vezes, põem em xeque o senso comum. “Senso comum que insiste em tingir com alarmismo apocalíptico as drogas, investindo-as de um caráter metafísico maléfico que estão longe de possuir”, escreve o médico psiquiatra e doutor em saúde pública Sergio Alarcon, organizador da coletânea juntamente com o também médico psiquiatra e doutor em saúde pública Marco Aurélio Soares Jorge. O livro é resultado do Curso de Atualização para a Atenção ao Uso Abusivo de Álcool e Outras Drogas, oferecido anualmente pela Escola Politécnica da Fiocruz. Contudo, a obra se dirige não só aos trabalhadores da saúde e da saúde mental, mas a qualquer pessoa interessada pelo assunto: afinal, as drogas, por seu crescente consumo e pelas tentativas frustradas de combatê-lo, ocupam hoje o centro das preocupações da sociedade.', '["alcohol consumption","drug use","substance abuse","public health","healthcare workers","mental health","drug policy"]', '10.7476/9788575415399', '9788575415399', 'https://books.scielo.org/id/8q677', 'https://books.scielo.org/id/8q677/pdf/alarcon-9788575415399.pdf', NULL, 'https://books.scielo.org/id/8q677/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8q7yj', '8q7yj', 'História do ensino da literatura infantil na formação de professores no estado de São Paulo (1947-2003)', NULL, '["Fernando Rodrígues de Oliveira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Ao discutir a instituição da literatura infantil como objeto de ensino na formação de professores, Fernando Rodrigues de Oliveira apresenta a trajetória histórica de construção da disciplina “Literatura infantil” e sua intrínseca relação com a formulação de um saber escolar.', '["children''s literature","children''s literature education","teacher professional development","history of education","São Paulo state","teacher education curriculum","curriculum history","history of reading instruction","history of education in Brazil"]', '10.7476/9788579836688', '9788579836688', 'https://books.scielo.org/id/8q7yj', 'https://books.scielo.org/id/8q7yj/pdf/oliveira-9788579836688.pdf', NULL, 'https://books.scielo.org/id/8q7yj/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8s5m4', '8s5m4', 'Os sentidos da saúde e da doença', NULL, '["Dina Czeresnia","Elvira Maria Godinho de Seixas Maciel","Rafael Antônio Malagón Oviedo"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Pergunte a várias pessoas o que significa ter saúde ou estar doente e, certamente, cada uma delas terá uma resposta diferente. Embora saúde e doença sejam conceitos com os quais lidamos no dia a dia, não é simples tentar defini-los. A elaboração conceitual, linguística, não consegue apreender toda a complexidade da experiência do adoecimento. O fato de sentir-se bem não assegura a inexistência de disfunções ou lesões. E há aqueles que, mesmo reconhecendo-se portadores de doenças crônicas, mantêm uma atitude de grande positividade. Por outro lado, pode-se experimentar um mal-estar que, por não enquadrar-se em uma categoria diagnóstica, não chega a ser visto pela medicina como doença. Saúde e doença, então, podem não ser definidas do mesmo modo na perspectiva da medicina e na daqueles que as experimentam? Refletir sobre questões como essa é o objetivo deste livro. Os autores não consideram satisfatórias definições de saúde e doença estritamente científicas, fundamentadas apenas no conhecimento médico e biológico, e em parâmetros quantitativos. Ao longo do livro, a saúde é apresentada como uma capacidade para lidar com a existência, salientando-se que uma vida saudável não pode excluir tensões. Logo, a saúde é uma potência para que se criem estratégias de adaptação ao meio e, nesse sentido, aprender com a experiência da doença é também um sinal de saúde. Pensar os sentidos da saúde, portanto, exige uma reflexão sobre ética e uma articulação com dimensões políticas, artísticas e filosóficas. As transformações dos conceitos de saúde e de doença ao longo do tempo também são analisadas na obra.', '["concept of health","concept of disease","illness experience","chronic disease","adaptation to adversity","history of health concepts","philosophy of medicine","ethics of health"]', '10.7476/9788575415269', '9788575414330', 'https://books.scielo.org/id/8s5m4', NULL, NULL, 'https://books.scielo.org/id/8s5m4/cover/cover_thumbnail.jpeg', 119, 24, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8skrw', '8skrw', 'Compósitos madeira-cimento: um produto sustentável para o Futuro', NULL, '["Vinícius Gomes de Castro"]', 'EdUFERSA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Tijolo, concreto, aço, gesso, o que estes produtos tradicionais de construção possuem em comum? Todos continuam a emitir gás carbônico durante suas vidas úteis. A construção civil é hoje responsável por quase 40% do carbono na nossa atmosfera. Por isso é importante que os produtos que hoje usamos para construir sejam repensados. Compósitos madeira cimento é uma das alternativas promissoras neste sentido. Estes compósitos são formados pela mistura de partículas de madeira, que não só emitem baixo teor de gás carbônico em uso, mas também armazena o carbono durante seu processo de formação enquanto árvore, e cimento, material comum, aceito e de fácil acesso em todo o mundo. A combinação destes produtos geram um compósito com características positivas de ambas as partes, por exemplo, ao mesmo tempo que resistem ao ataque de fungos e cupins, por causa do cimento, são mais leves e elásticos, por causa da madeira. Porém ainda há desafios para a popularização deste material, sendo o principal deles a seletividade da espécie de madeira usada que pode interferir na pega do cimento. Assim, essa obra busca levantar o estado da arte dos estudos sobre esse material para servir de base e inspiração para o desenvolvimento de novas pesquisas e inovações tecnológicas.', '["wood-cement composites","sustainable construction materials","carbon sequestration","construction carbon emissions","wood species selection","cement bonding","lightweight composites"]', '10.7476/9786587108612', '9786587108612', 'https://books.scielo.org/id/8skrw', 'https://books.scielo.org/id/8skrw/pdf/castro-9786587108612.pdf', NULL, 'https://books.scielo.org/id/8skrw/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8sn3x', '8sn3x', 'De la Constitución de 1991 a la realidad. Debates políticos, jurídicos, territoriales e internacionales', NULL, '["Karen Nathalia Cerón Steevens","Walter Orlando Arévalo-Ramírez"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este libro presenta las reflexiones que sobre los efectos de la Constitución de 1991 y sus modificaciones han hecho profesores e investigadores de las facultades de Ciencia Política y Gobierno de la Universidad del Rosario, así como de la Facultad de Jurisprudencia de esta misma institución, expertos del Centro Colombiano de Derecho Procesal Constitucional y personalidades reconocidas de la vida nacional, en cuanto al equilibrio de poderes y el poder de reforma, las políticas públicas y la participación política, el Estado Social de Derecho, la perspectiva de nuestras relaciones internacionales y el ordenamiento territorial. Como todo texto jurídico-político, la Constitución Política de 1991 cobra vida y revela sus complejidades a través de su aplicación material día a día, práctica mucho más compleja que la original enunciación de sus contenidos escritos. Dos décadas del nuevo ordenamiento constitucional, de su ejecución dentro del propósito de impulsar el Estado Democrático Constitucional Social de Derecho, nos permiten reflexionar acerca de múltiples logros pero también de las enormes inquietudes y discusiones que hemos expuesto, las cuales serán revisadas y profundizadas a lo largo del presente estudio.', '["Colombian Constitution of 1991","constitutional reform","separation of powers","public policy","political participation","social rule of law","constitutional law","international relations","territorial organization","democratic constitutional state","constitutional implementation"]', '10.7476/9789587385540', '9789587385533', 'https://books.scielo.org/id/8sn3x', NULL, NULL, 'https://books.scielo.org/id/8sn3x/cover/cover_thumbnail.jpeg', 508, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8synr', '8synr', 'Nebulosas do pensamento urbanístico: tomo I – modos de pensar', NULL, '["Jacques, Paola Berenstein","Pereira, Margareth da Silva"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'es', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'sob a coordenação de Ricardo Trevisan, na Universidade Federal de Minas Gerais (UFMG), sob a coordenação de Rita Velloso, e, a partir de 2017, a nova equipe formada na Universidade Estadual de Campinas (UNICAMP), sob a coordenação de Josianne Cerasoli.Nebulosas do pensamento urbanístico: modos de pensar é o primeiro tomo que foca nas questões teóricas e metodológicas da pesquisa.Deverá se seguir de um segundo tomo, Modos de fazer, reunindo as contribuições particulares das diferentes equipes -incluindo também os estudantes: bolsistas de iniciação científica, mestrado e doutorado -ao usar a Cronologia do Pensamento Urbanístico como instrumento.Neste tomo, Modos de pensar, os autores são os pesquisadores em atividade nas diferentes equipes, e no segundo tomo, Modos de fazer, os trabalhos em andamento na pesquisa nas diferentes universidades serão apresentados pelas respectivas equipes completas.Os 11 textos reunidos neste primeiro tomo em forma de coletânea, apresentam seus modos de pensar por: associações, atlas, biografias, constelações, dados, imagens, margens, montagens, nebulosas e pluralidades, buscando mostrar formas diferentes, porém complementares, de pensar a história e, em particular, a história do pensamento urbanístico.Apesar da noção de nebulosas, presente no título da publicação, predominar em nossos atuais modos de fazer na pesquisa coletiva, decidimos, nesta publicação, não hierarquizar os diferentes modos de pensar aqui reunidos e apresentá-los em forma aleatória -no caso, alfabética -, para que o leitor possa fazer suas próprias articulações e atravessamentos, assim como perceber melhor tanto as ressonâncias quanto as diferenças entre as propostas e análises apresentadas.Pretendemos, com esse esforço editorial em dois tomos, melhor situar nosso esforço investigativo dos últimos anos, tanto dentro do N O TA 1 Ver: <http://www.cronologiadourbanismo.ufba.br>.importantes reflexões.Escolhi dois poemas de Baudelaire trazidos por Benjamin para dizer por imagens contrapostas e associadas a condição do ser urbano: Cada um, nos acotovelando sobre a calçada escorregadia, Egoísta e brutal, passa e nos enlameia, Ou, para correr mais rápido, distanciando nos empurra.Em toda parte, lama, dilúvio, escuridão do céu: Negro quadro com que teria sonhado o negro Ezequiel.(BAUDELAIRE apud BENJAMIN, 1989, p. 120) Contraposto a esse outro poema em que o poeta fala dos sentidos do urbanita tão atentos com o que vê e que o emociona, é o tempo que foge num espaço nebuloso, tempo e espaço deslizam, se esvaem, sem se fixarem:A rua em torno era um frenético alarido.Toda de luto, alta e sutil, dor majestosa, Uma mulher passou, com sua mão suntuosa Erguendo e sacudindo a barra do vestido.Pernas de estátua, era-lhe a imagem nobre e fina Qual bizarro basbaque, afoito eu lhe bebia No olhar, céu lívido onde aflora a ventania, A doçura que envolve o prazer que assassina.Que luz... e a noite após! -Efêmera beldade Cujos olhos me fazem nascer outra vez, Não mais hei de te ver senão na eternidade?(BAUDELAIRE apud BENJAMIN, 1989, p. 117)', '["history of urban thought","urban studies","collective research","research methodology","associations","constellations","montage","images","margins","plurality","Charles Baudelaire","Benjamin"]', '10.7476/9788523220327', '9788523220327', 'https://books.scielo.org/id/8synr', 'https://books.scielo.org/id/8synr/pdf/jacques-9788523220327.pdf', NULL, 'https://books.scielo.org/id/8synr/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8t823', '8t823', 'Educação e sua diversidade', NULL, '["Arlete Ramos dos Santos","Júlia Maria da Silva Oliveira","Lívia Andrade Coelho"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A Série Movimentos Sociais e Educação visa contribuir com debate acerca dos movimentos sociais na atualidade. Neste volume, são apresentados textos que passam pela Educação de Jovens e Adultos (EJA), educação em espaços não escolares, Direito, educação nas relações étnico-raciais, dentre outros temas relacionados à educação, seja no campo ou na cidade.', '["social movements","youth and adult education","non-formal education","diversity in education"]', '10.7476/9788574554891', '9788574554891', 'https://books.scielo.org/id/8t823', 'https://books.scielo.org/id/8t823/pdf/santos-9788574554891.pdf', NULL, 'https://books.scielo.org/id/8t823/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8td4k', '8td4k', 'Economia selvagem', NULL, '["César Gordon"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', '', '["informal economy","illegal economy"]', '10.7476/9788539302970', '9788571396661', 'https://books.scielo.org/id/8td4k', NULL, NULL, 'https://books.scielo.org/id/8td4k/cover/cover_thumbnail.jpeg', 456, 72, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8tz73', '8tz73', 'Medicalização em psiquiatria', NULL, '["Fernando Freitas","Paulo Amarante"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', '“Estaríamos ficando cada vez mais doentes? Ou estaríamos a cada dia ficando mais saudáveis, já que gastamos mais com saúde?” Os autores partem desse questionamento para discutir a problemática da medicalização, sobretudo no que se refere ao sofrimento psíquico. Eles chamam atenção para o fato de que experiências comuns e naturais da nossa existência têm sido consideradas passíveis de serem ''tratadas'' e ''resolvidas'' com medicamentos. As consequências individuais e sociais desse problema são analisadas pelos autores, que também fazem um alerta sobre os prejuízos causados por uma nefasta aliança entre a psiquiatria e a indústria farmacêutica. Com linguagem acessível, esta obra objetiva ampliar o debate sobre a medicalização do sofrimento psíquico, incluindo, em especial, aqueles que sofrem com ela.', '["medicalization","mental illness","psychological suffering","pharmaceutical industry","mental health","medication overuse","health care costs"]', '10.7476/9788575415788', '9788575414989', 'https://books.scielo.org/id/8tz73', NULL, NULL, 'https://books.scielo.org/id/8tz73/cover/cover_thumbnail.jpeg', 148, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8v2y2', '8v2y2', 'Tecnologia e gestão pública municipal: mensuração da interação com a sociedade', NULL, '["Ricardo César Gonçalves Sant’Ana"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Grande parte dos problemas sociais que enfrentamos atualmente poderia ser minimizada com a destinação, e principalmente, com a aplicação mais eficiente dos recursos públicos disponíveis. Faz-se necessário que a sociedade acompanhe de perto o processo de gestão das administrações públicas, começando pela mais próxima, a municipal. Esta tarefa vem sendo facilitada pelo uso de recursos de Tecnologia da Informação que podem propiciar um ambiente mais transparente e acessível, permitindo um olhar da sociedade sobre as ações e decisões da gestão pública. Com isso se abre a possibilidade de acompanhar e cobrar maior esforço dos gestores públicos para ampliar a disponibilidade de opções de acesso aos dados e serviços públicos. Governos realmente transparentes podem estimular a participação popular, a cidadania e a construção de uma sociedade mais justa. Neste livro são analisados os aspectos envolvidos no processo de construção de um ambiente desse tipo e propostos diversos elementos a serem identificados na busca pela mensuração do nível com que esta interação esta sendo propiciada. Trata-se de um tema de grande atualidade e relevância', '["municipal public management","information technology in public administration","government transparency","citizen participation","public service delivery","e-government"]', '10.7476/9788579830105', '9788579830105', 'https://books.scielo.org/id/8v2y2', 'https://books.scielo.org/id/8v2y2/pdf/santana-9788579830105.pdf', NULL, 'https://books.scielo.org/id/8v2y2/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8vq58', '8vq58', 'Mania de liberdade: Nise da Silveira e a humanização da saúde mental no Brasil', NULL, '["Felipe Sales Magaldi"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Livro que destaca o legado da psiquiatria rebelde de Nise da Silveira (1905-1999). A obra é um desdobramento da premiada pesquisa de doutorado desenvolvida pelo antropólogo Felipe Magaldi no Programa de Pós-Graduação em Antropologia Social do Museu Nacional da Universidade Federal do Rio de Janeiro (PPGAS/MN/UFRJ). Ganhador do Prêmio Capes de Tese 2019, nas áreas Antropologia/Arqueologia, o autor apresenta aos leitores o que ele mesmo chama de Admirável Mundo Nise, mostrando a fascinante vida da psiquiatra alagoana e sua complexa relação com a luta antimanicomial no Brasil. O título aborda a trajetória e a memória da doutora Nise, com foco em seu trabalho no Rio de Janeiro, a partir da década de 1940 até os dias atuais, em que permanece inspirando novas políticas públicas e produções culturais. O livro revela como o trabalho da médica se destacou pelo combate às intervenções biomédicas violentas e pela defesa de atividades artísticas e expressivas como forma de tratamento em saúde mental. Magaldi destaca que, para se aprofundar no legado da psiquiatra, mergulhou nas produções bibliográfica, documental e memorialística preexistentes sobre o trabalho dela. “Também realizei entrevistas com os seus colaboradores vivos e, principalmente, realizei um trabalho de campo, etnográfico, nas instituições vinculadas à memória e ao legado de Nise da Silveira”, revela. Entre as instituições exploradas durante a pesquisa de Magaldi, destacam-se o Instituto Municipal de Assistência à Saúde Nise da Silveira, em Engenho de Dentro, no Rio de Janeiro, onde estão localizados o Museu de Imagens do Inconsciente e a ocupação artística Hotel da Loucura. A Casa das Palmeiras, no bairro de Botafogo, também é um desses importantes espaços do legado nisiano.', '["Nise da Silveira","history of psychiatry","anti-asylum movement","psychiatric deinstitutionalization","biomedical interventions","memory and legacy","public mental health policy","Rio de Janeiro"]', '10.7476/9786557080689', '9786557080092', 'https://books.scielo.org/id/8vq58', NULL, NULL, 'https://books.scielo.org/id/8vq58/cover/cover_thumbnail.jpeg', 356, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8vq7m', '8vq7m', 'Ativismo patrocinado pelo Estado: burocratas e movimentos sociais no Brasil democrático', NULL, '["Jessica A. J. Rich"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-05-11', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A autora analisa as políticas de HIV e Aids no Brasil para desvendar as relações complexas entre a sociedade e o Estado no contexto do Brasil democrático (e, mais amplamente, na teoria da ciência política sobre transições democráticas na América Latina). A autora enfatiza uma relação muito mais rica do que previamente percebida entre o ativismo da sociedade civil e a presença de um espírito ativista também na burocracia estatal devidamente renovada e empoderada pelo aprofundamento dos processos de redemocratização. No retrato revelado pelo trabalho de Jessica Rich, podemos enxergar a construção de uma coalizão ativista (ou, em inglês, uma coalizão de advocacy) em que ativistas se transformam em burocratas (não no sentido pejorativo muitas vezes associado com a palavra burocrata, mas no seu sentido técnico, como funcionário ou servidor público), enquanto burocratas se transformam em verdadeiros ativistas. É um processo de integração em que os processos políticos são construídos simultaneamente tanto de cima quanto de baixo, com o envolvimento significante de setores governamentais na mobilização social, e com a participação da sociedade civil e as suas organizações (neste caso, especialmente o setor das chamadas ONGs/Aids) na articulação e na implementação das políticas públicas.', '["HIV/AIDS policy","civil society activism","bureaucracy","social movements","advocacy coalitions","democratic transition","redemocratization","non-governmental organizations","public policy implementation","state-society relations","Brazil"]', '10.7476/9786557081044', '9786557080313', 'https://books.scielo.org/id/8vq7m', NULL, NULL, 'https://books.scielo.org/id/8vq7m/cover/cover_thumbnail.jpeg', 305, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8vr6k', '8vr6k', 'Profissão: assistente social', NULL, '["Edméia Corrêa Netto"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'No presente estudo nossa atenção voltou-se para compreender as condições objetivas e subjetivas do processo de trabalho de assistentes sociais em entidades sociais no município de Bebedouro. A ação profissional já tem sido objeto de análise em diversos estudos, porém, com menos frequência busca-se investigar as reais condições de trabalho que o Assistente Social encontra em seu cotidiano profissional. Nossa análise procura compreender o processo de trabalho do Serviço Social em entidades sociais de modo a descartar a priori, tanto a tendência fatalista que considera o espaço profissional com limites insuperáveis, como a tendência messiânica que considera o assistente social um profissional independente, com autonomia quase absoluta para desenvolver propostas transformadoras da realidade, desconsiderando a verdadeira inserção profissional na realidade concreta. As duas abordagens, tanto a fatalista como a messiânica, não relevam a historicidade social a partir da realização dos homens, as particularidades da profissão e os elementos que a singularizam em determinado momento histórico e em cada processo de trabalho. Procuramos então responder: quem são os profissionais que estão nas entidades sociais? Quais as condições objetivas e subjetivas da ação profissional nesse espaço de trabalho? O que se revela por detrás da cotidianidade, o que há de significativo para além da repetição cotidiana? Nosso universo de investigação foi constituído por todas as entidades sociais regularmente inscritas no Conselho Municipal de Assistência Social - CMAS no ano de 2008. Isso significa que as entidades sociais tinham que estar com suas obrigações em dia com o CMAS referentes ao ano de 2007, como a apresentação de relatórios das atividades realizadas e a prestação de contas junto ao órgão gestor, além de projetos para o ano de 2008.', '["working conditions","social work practice","social entities","professional autonomy","municipal social assistance council","history of social work"]', '10.7476/9788579830839', '9788579830839', 'https://books.scielo.org/id/8vr6k', 'https://books.scielo.org/id/8vr6k/pdf/correa-9788579830839.pdf', NULL, 'https://books.scielo.org/id/8vr6k/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8wg4g', '8wg4g', 'Conservadorismos, fascismos e fundamentalismos: análises conjunturais', NULL, '["Ronaldo de Almeida","Rodrigo Ferreira Toniol"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Conservadorismo, fascismo e fundamentalismo são categorias associadas a eventos históricos específicos. No entanto, essas palavras tornaram-se comuns no debate público brasileiro contemporâneo, sendo constantemente acionadas nos noticiários, na imprensa escrita e nas redes sociais na internet. Ao dar centralidade a essas categorias, este livro reflete sobre o seu valor analítico e a sua capacidade descritiva. Os protestos de massa no Brasil, o processo de impeachment de Dilma Rousseff e seus desdobramentos, a eleição de Donald Trump e a participação dos evangélicos na política nacional são alguns dos focos empíricos analisados por pesquisadores de diferentes áreas das Humanidades. Este é um livro que nos ajuda a entender a crise política depois das manifestações de junho de 2013 e também nos dá pistas sobre o que podemos esperar para os próximos anos.', '["conservatism","fascism","fundamentalism","political categories","Brazilian political crisis","2013 Brazilian protests","Dilma Rousseff impeachment","Trump election","political situation","populism"]', '10.7476/9788526815025', '9788526814554', 'https://books.scielo.org/id/8wg4g', NULL, NULL, 'https://books.scielo.org/id/8wg4g/cover/cover_thumbnail.jpeg', 200, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8wh7k', '8wh7k', 'História e memórias das ações afirmativas na UEFS', NULL, '["Ana Clara Rodrigues da Silva Santos","Carina Silva de Carvalho Oliveira","Ivanilde Guedes de Mattos","Norma Lucia Fernandes de Almeida","Otto Vinicius Agra Figueiredo"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro História e Memórias das Ações Afirmativas da UEFS, traz em seu bojo as discussões sobre as ações afirmativas na Universidade Estadual de Feira de Santana (UEFS), e as retrata desde o seu nascedouro até os dias atuais. Todos esses caminhos são trilhados a partir das narrativas dos que viveram a transição da universidade antes, durante e depois da implantação da Resolução 034/2006, primeiro instrumento de garantia do acesso ao ensino superior para negros(as), indígenas e quilombolas nesta universidade. O livro está dividido em três partes.', '["affirmative action","Universidade Estadual de Feira de Santana","higher education access","Black students","Indigenous students","quilombola students","university history","institutional memory","racial quotas"]', '10.7476/9788555921742', '9786589524403', 'https://books.scielo.org/id/8wh7k', NULL, NULL, 'https://books.scielo.org/id/8wh7k/cover/cover_thumbnail.jpeg', 386, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8wzv5', '8wzv5', 'A cidade-atração: a norma de preservação de áreas centrais no Brasil dos anos 1990', NULL, '["Marcia Sant’Anna"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A cidade-atração investiga os programas e projetos que, a partir dos anos 1990, incorporaram o patrimônio de cidades brasileiras como um ativo urbano destinado a contribuir para a transformação de quadros de desvalorização econômica e de uso e apropriação popular. Com base em processos deflagrados nas áreas centrais de Salvador, Rio de Janeiro e São Paulo, busca compreender os sentidos subjacentes à proliferação e à banalização de práticas preservacionistas e apontar outras possibilidades socialmente mais significativas de uso do patrimônio urbano.', '["urban heritage conservation","urban decline","Salvador, Bahia","Rio de Janeiro","São Paulo"]', '10.7476/9788523218713', '9788523218713', 'https://books.scielo.org/id/8wzv5', 'https://books.scielo.org/id/8wzv5/pdf/santanna-9788523218713.pdf', NULL, 'https://books.scielo.org/id/8wzv5/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8x7p5', '8x7p5', 'Modesta proposta: e outros textos satíricos', NULL, '["Jonathan J. Swift"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este é o primeiro volume da coleção Pequenos Frascos, a qual apresenta pequenos textos, menos conhecidos - e, de certa forma, "marginais" - de autores consagrados nas mais diversas áreas. Neste volume há uma compilação de escritos satíricos de Jonathan Swift, escritor irlandês do século XVII. O texto que o intitula é um pequeno grande achado: o autor apresenta uma polêmica solução para o problema das crianças famintas que perambulava pelas ruas da Irlanda na época. É um "mundo dos horrores" modo pelo qual o autor convoca a todos para a liberdade de pensar "pelo avesso", porque "o mundo está direitinho demais para estar certo. Apesar do lapso temporal, é de uma incrível atualidade em relação à realidade mundial e, sobretudo, à brasileira.', '["Jonathan Swift","satire","Irish literature","17th-century literature","orphans","poverty","freedom of thought","contemporary relevance"]', '10.7476/9788539303274', '9788571395978', 'https://books.scielo.org/id/8x7p5', NULL, NULL, 'https://books.scielo.org/id/8x7p5/cover/cover_thumbnail.jpeg', 104, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8xmfk', '8xmfk', 'Memes e educação na cibercultura', NULL, '["Kaio Eduardo de Jesus Oliveira","Cristiane de Magalhães Porto","Edméa Santos"]', 'Directory of Open access Books (OAPEN Foundation)', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Memes são artefatos cada vez mais importantes na dinâmica comunicacional da cibercultura. Em seu modo de expressão, permitem diferentes formas de ler e interpretar o mundo a partir da autoria dos usuários em rede. Em sua amplitude na internet, tornam-se uma espécie de “caldeirão” da opinião pública onde múltiplos temas são misturados e ressignificados na medida em que são propagados. Sendo assim, é possível pensar a produção de memes como uma linguagem que democratiza o acesso à informação, por meio da brincadeira on-line, do humor e da comicidade. Embora superficializem muitas questões problematizadas. Por isso, é necessário analisar sua dinâmica comunicacional, já que os memes materializam um fenômeno representativo do nosso modo de ser e estar na cibercultura.', '["memes","digital culture","internet memes","user-generated content","online humor","online play","democratization of information","public opinion","communication dynamics"]', '10.7476/9786586213911', '9786586213911', 'https://books.scielo.org/id/8xmfk', 'https://books.scielo.org/id/8xmfk/pdf/oliveira-9786586213911.pdf', NULL, 'https://books.scielo.org/id/8xmfk/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8xmj7', '8xmj7', 'Encruzilhadas no coração de Shirley: a cidade, o gênero e o corpo no cinema de Edyala Yglesias', NULL, '["Jober Pascoal Souza Brito"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro surge do fascínio do autor Jober Pascoal pelo filme No coração de Shirley, realizado por Edyala Iglesias, em 2002, com suas personagens divergentes, a cidade que lhe deu forma e a realidade que o produziu. Em um texto rigoroso e criativo, Jober Pascoal faz do filme, um curta-metragem de 20 minutos de duração, o núcleo de seu trabalho, articulando o filme e a cidade de Salvador para discutir gênero e o mercado do sexo num tradicional local de trabalho noturno de prostitutas e travestis. Manejando um número expressivo de referências bibliográficas e filmografias – de Michel Foucault a Gilles Deleuze; de Simone de Beauvoir a Judith Butler; de Ítalo Calvino a Pierre Bourdieu, entre tantos outros autores, Jober Pascoal cria um instigante percurso de análise que vai da “cidade invisível”, obscura e alegórica, a “cidade proibida”, aquela reinventada por atos de micro resistências, em cada uma de suas três perspectivas de abordagem: a cidade, o gênero e o corpo.', '["Salvador, Bahia","gender","body","cities","sex work","prostitution","transgender women","Invisible Cities","Forbidden City","micro-resistance","short film","urban space in film"]', '10.7476/9786588211274', '9788578873608', 'https://books.scielo.org/id/8xmj7', 'https://books.scielo.org/id/8xmj7/pdf/brito-9786588211274.pdf', 'https://books.scielo.org/id/8xmj7/epub/brito-9786588211274.epub', 'https://books.scielo.org/id/8xmj7/cover/cover_thumbnail.jpeg', 197, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8xrkr', '8xrkr', 'Vozes, olhares, silêncios: diálogos transdisciplinares entre a lingüística e a tradução', NULL, '["Denise Scheyerl","Ramos, Elizabeth"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A presente coletânea convida ao debate e ao intercâmbio voltados para uma linguística crítica e interdisciplinar que dialoga com outros saberes e converge para a (re)construção de novas formas do saber/fazer linguístico. Exibe um leque multifocal de assuntos, apoiado em dois grandes temas: o ensino-aprendizagem de línguas como meio de transformação social e questões culturais envolvendo a tradução literária.', '["critical linguistics","interdisciplinarity","linguistics and translation","literary translation","language teaching and learning","social change"]', '10.7476/9788523212407', '9788523212407', 'https://books.scielo.org/id/8xrkr', 'https://books.scielo.org/id/8xrkr/pdf/scheyerl-9788523212407.pdf', NULL, 'https://books.scielo.org/id/8xrkr/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8xvf4', '8xvf4', 'Recuperação ambiental da Mata Atlântica', NULL, '["Danilo Sette de Almeida"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Neste trabalho são discutidos métodos de recuperação de áreas degradadas, principalmente aplicados em atividades agopecuárias na região da Floresta Atlântica. São abordados temas com o objetivo de fornecer subsídios para quem deseja se dedicar à recuperação de ecossistemas degradados, levando-se em consideração aspectos técnicos, legais e econômicos do processo de recuperação, abrangendo desde a metodologia para o desenvolvimento de diferentes modelos de recuperação até roteiros para a elaboração de projetos técnicos, realização de diagnósticos, montagem de infraestrutura básica, enfim, subsídios gerais para implantar programas de recuperação apropriados para diferentes situações e escalas.', '["Atlantic Forest","environmental restoration","degraded area recovery","agropecuarian activities","degraded ecosystem restoration","restoration project design","restoration diagnosis","restoration program"]', '10.7476/9788574554402', '9788574554402', 'https://books.scielo.org/id/8xvf4', 'https://books.scielo.org/id/8xvf4/pdf/almeida-9788574554402.pdf', NULL, 'https://books.scielo.org/id/8xvf4/cover/cover_thumbnail.jpeg', NULL, 28, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8xxn2', '8xxn2', 'Complexidade da formação de professores: saberes teóricos e saberes práticos', NULL, '["Marilda da Silva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra propõe uma reflexão sobre os saberes teóricos e práticos no âmbito da formação e atuação docente, tendo em vista a natureza de cada um desses saberes e em que medida eles tornam complexa a formação e o trabalho dos professores. Trata-se de um estudo de grande atualidade, fundamentado em pesquisas desenvolvidas a partir dos anos 90, em que se discute a racionalidade da constituição do trabalho docente em sala de aula, oportuno a professores e a professorandos', '["teacher professional development","theoretical knowledge","practical knowledge","teaching complexity","teacher work","classroom teaching"]', '10.7476/9788598605975', '9788598605975', 'https://books.scielo.org/id/8xxn2', 'https://books.scielo.org/id/8xxn2/pdf/silva-9788598605975.pdf', NULL, 'https://books.scielo.org/id/8xxn2/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8ycc4', '8ycc4', 'Tempo de acampamento', NULL, '["Nashieli Rangel Loera"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Resumo: O tempo de acampamento é um código social do mundo das ocupações de terra, na medida em que além de uma medida cronológica é também, um demarcador de prestígio, de status, um princípio organizador e ordenador das relações sociais, e um requisito para conseguir um lote de terra, tanto para participantes das ocupações e acampamentos de sem-terra, para os dirigentes das organizações que promovem as ocupações e para as autoridades encarregadas das desapropriações de terra, conformando assim uma fórmula social entendida e compartilhada por todos aqueles que fazem parte desse mundo social particular, o das ocupações de terra. No entanto, o tempo de acampamento pode ter diversos significados todos eles referidos ao contexto, à situação e à condição do indivíduo assim como às posições que as pessoas ocupam nesse mundo social particular. Assim sendo, ainda que os participantes do mundo das ocupações façam referência às expressões nativas: tempo de barraco, tempo de luta e tempo de reforma, como expressões homônimas ao tempo de acampamento, descrevem, a maioria das vezes, uma diversidade de significados, ações e situações.', '["land occupation","landless people","social codes","social status","prestige","land expropriation","interpersonal relationships","land reform"]', '10.7476/9788568334355', '9788568334355', 'https://books.scielo.org/id/8ycc4', 'https://books.scielo.org/id/8ycc4/pdf/loera-9788568334355.pdf', NULL, 'https://books.scielo.org/id/8ycc4/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8yg45', '8yg45', 'Terapia assistida por animais (TAA): aplicação no desenvolvimento psicomotor da criança com deficiência intelectual', NULL, '["Patrícia Sidorenko de Oliveira Capote","Maria da Piedade Resende da Costa"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'É um livro que trata sobre a importância da Terapia Assistida por Animais e sua aplicabilidade. Destina-se a profissionais como psicólogos, pedagogos, terapeutas ocupacionais, professores de Educação Física, entre outros, inclusive pais. Esperamos que esta leitura traga contribuições para melhorar a qualidade de vida da população de crianças com deficiência intelectual no seu desenvolvimento psicomotor.', '["animal-assisted therapy","intellectual disability","psychomotor development","children","quality of life","occupational therapy","physical education"]', '10.7476/9788576002949', '9788576002949', 'https://books.scielo.org/id/8yg45', 'https://books.scielo.org/id/8yg45/pdf/capote-9788576002949.pdf', NULL, 'https://books.scielo.org/id/8yg45/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8z56d', '8z56d', 'Direito à comunicação e saúde', NULL, '["Luiz Felipe Stevanim","Rodrigo Murtinho"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-07-27', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro analisa a centralidade do direito à comunicação para a garantia da saúde (um direito humano fundamental) e dos princípios do Sistema Único de Saúde (SUS). Segundo os autores, o objetivo principal da obra é compreender as relações entre comunicação e saúde - ambas identificadas como expressões de cidadania - à luz dos direitos humanos. Para isso, Luiz Felipe Stevanim e Rodrigo Murtinho norteiam o desenvolvimento do livro a partir de uma questão central: direito à comunicação tem a ver com saúde? Em cinco capítulos, o volume apresenta referenciais teóricos e contextos em que as interfaces entre direito à comunicação e à saúde se fazem presentes. Temas como exclusão digital, proteção de dados pessoais e desinformação também são abordados.', '["right to communication","right to health","human rights","Unified Health System (SUS)","citizenship","digital exclusion","personal data protection","disinformation","health communication"]', '10.7476/9786557081082', '9786557080399', 'https://books.scielo.org/id/8z56d', NULL, NULL, 'https://books.scielo.org/id/8z56d/cover/cover_thumbnail.jpeg', 163, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8zmft', '8zmft', '"Não é só a torcida organizada": o que os torcedores organizados têm a dizer sobre a violência no futebol?', NULL, '["Marcelo Fadori Soares Palhares","Gisele Maria Schwartz"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este estudo inves­tigou o que os torcedores organizados teriam a dizer sobre a violência no futebol brasileiro, para depois inter­pretar tais discursos à luz do referencial teórico de Johan Galtung. Visando contribuir com o debate sobre a violência no futebol, nesta abordagem, optamos pelo viés da compreensão em lugar da visão estigmatizante e preconceituosa sobre o tema. Defendemos que reduzir a discussão da vio­lência no futebol meramente à ação das torcidas organizadas frag­menta a análise desse complexo fenômeno e se mostra improdutivo, pois a violência no futebol perpassa a organização, gestão e estrutura do futebol brasileiro, além dos episódios de violência física.', '["organized football fans","football violence","Johan Galtung","Brazilian football","fan discourse","football governance"]', '10.7476/9788579837425', '9788579837425', 'https://books.scielo.org/id/8zmft', 'https://books.scielo.org/id/8zmft/pdf/palhares-9788579837425.pdf', NULL, 'https://books.scielo.org/id/8zmft/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-8znq5', '8znq5', 'Participação e saúde no Brasil', NULL, '["Soraya Vargas Côrtes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Grandes avanços na compreensão do sistema de funcionamento dos conselhos de saúde têm sido possibilitados, nos últimos anos, graças à produção acadêmica de qualidade sobre a participação em saúde no Brasil. Ainda que as abordagens nas investigações dos CEPs (Comitês de Ética em Pesquisa) tenham conduzido à constatação das enormes dificuldades que o controle social vem encontrando para sua efetivação, os projetos de pesquisa conduzidos pela autora, cujos resultados são aqui apresentados, conseguiram fugir dessas armadilhas mediante a construção de um elaborado referencial teórico-metodológico absolutamente inovador. A originalidade interpretativa, o rigor metodológico e a riqueza analítica constituem, em síntese, as características deste livro, rico material para os estudiosos da democracia participativa e para o público em geral.', '["health participation","social control","health councils","participatory democracy","health governance","research ethics committees"]', '10.7476/9788575413463', '9788575413463', 'https://books.scielo.org/id/8znq5', 'https://books.scielo.org/id/8znq5/pdf/cortes-9788575413463.pdf', NULL, 'https://books.scielo.org/id/8znq5/cover/cover_thumbnail.jpeg', NULL, 36, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-92py9', '92py9', 'Manguinhos do sonho à vida: a ciência na Belle Époque', NULL, '["Jaime Larry Benchimol"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Reimpressão comemorativa dos 120 anos da Fiocruz, celebrados em 2020, "Manguinhos do Sonho à Vida" retrata as origens e a trajetória do Instituto Oswaldo Cruz nas quatro primeiras décadas do século XX. Compõe-se de três ensaios que têm em comum o interesse pela assimilação do pasteurianismo na prática científica, na saúde pública e na arquitetura hospitalar. O primeiro aborda a história político-administrativa e o desenvolvimento da pesquisa, da produção e do ensino em Manguinhos. O segundo trata do complexo arquitetônico, remetendo-o ao contexto do ecletismo e das transformações urbanas. O último ensaio recupera a figura e a obra do arquiteto de Manguinhos, o português Luiz de Morais Júnior, enfatizando especialmente seus projetos de caráter médico-sanitário. A edição original do livro foi publicada em 1990, pelo Departamento de Pesquisa da Casa de Oswaldo Cruz/Fiocruz, como parte das comemorações do aniversário de 90 anos da instituição.', '["Instituto Oswaldo Cruz","Fiocruz","Manguinhos","history of public health","Pasteurianism","hospital architecture","Belle Époque","eclecticism","urban transformation","medical education","history of science","20th century"]', '10.7476/9786557080788', '9786557080238', 'https://books.scielo.org/id/92py9', NULL, NULL, 'https://books.scielo.org/id/92py9/cover/cover_thumbnail.jpeg', 320, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-93fh9', '93fh9', 'Voltaire político: espelhos para príncipes de um novo tempo', NULL, '["Marcos Antônio Lopes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Instigante, profundo, informativo, esclarecedor e atraente, este livro demonstra um perfil da relação do grande iluminista Voltaire com a história e com a historiografia. Ao enriquecer o retrato de Voltaire, um dos mais fascinantes autores do século XVIII, Marcos Antônio Lopes concilia aspectos inovadores e tradicionais do pensamento desse iluminista, propondo que o vejamos como continuador e renovador de um antigo gênero literário (o dos espelhos dos príncipes), ao construir um modelo de príncipe ideal, devotado à boa administração dos negócios públicos e ao aperfeiçoamento das artes e das ciências. Resultado do trabalho solitário do autor dos textos voltairianos e de conversações, que manteve por vários anos, com pesquisadores de diversas instituições.', '["Voltaire","political thought","mirrors for princes","ideal ruler","public administration","Enlightenment","historiography","eighteenth-century political thought","arts and sciences"]', '10.7476/9788539303489', '9788571395350', 'https://books.scielo.org/id/93fh9', NULL, NULL, 'https://books.scielo.org/id/93fh9/cover/cover_thumbnail.jpeg', 140, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-93mhk', '93mhk', 'Esporte e mídia: novas perspectivas: a influência da obra de Hans Ulrich Gumbrecht', NULL, '["Ronaldo George Helal","Fausto Amaro"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Com forte formação literária, Hans Ulrich Gumbrecht é um dos teóricos mais respeitados, na atualidade, pela diversidade de sua produção e também pelas reflexões na área dos esportes. Essa obra oferece ao leitor 11 artigos que se utilizam, em alguma medida, das contribuições do pensamento do teórico alemão para aprofundar a compreensão sobre a interface entre esporte e mídia. Entre os ensaios, destaca-se também o capítulo escrito pelo próprio Gumbrecht, ?”Perdido numa intensidade focada?”.', '["sport and media","Hans Ulrich Gumbrecht","sport theory","media theory"]', '10.7476/9788575114377', '9788575113752', 'https://books.scielo.org/id/93mhk', NULL, NULL, 'https://books.scielo.org/id/93mhk/cover/cover_thumbnail.jpeg', 312, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-93vd3', '93vd3', 'As drogas na contemporaneidade: perspectivas clínicas e culturais', NULL, '["Antônio Nery Filho","Edward MacRae","Luiz Alberto Tavares","María Eugenia Núñez","Marlize Rêgo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Sempre prezando pela pluralidade, este livro reúne perspectivas e investigações que têm como objetivo fomentar discussões. Para iniciar o debate, Antonio Nery Filho apresenta um texto que questiona Por que os humanos usam drogas. Então, a obra divide-se em três partes: Da cultura, que aborda questões de natureza social e cultural; Da clínica, que reúne relatos de experiência clínica e Psicoativos: usos e usuários, que abordam múltiplos aspectos relacionados ao uso de substâncias psicoativas.', '["drugs","psychoactive substances","drug use","substance use","clinical perspective","cultural perspective","clinical experience","drug users"]', '10.7476/9788523211608', '9788523208592', 'https://books.scielo.org/id/93vd3', NULL, NULL, 'https://books.scielo.org/id/93vd3/cover/cover_thumbnail.jpeg', 438, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-948hc', '948hc', 'Administração, poder e ideologia', NULL, '["Maurício Tragtenberg"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Obra indispensável e singular na crítica da administração, proporciona subsídios para a compreensão do capitalismo contemporâneo. De leitura proveitosa a todos que valorizam o trabalho humano, o autor apresenta uma análise crítica do papel das grandes corporações no Mercado - eixo da grande reorganização do capitalismo após a crise econômica mundial dos anos 70. Aborda: a nova exploração do trabalho que mudou as formas disciplinares do capitalismo; a internacionalização da economia na tendência da condução das políticas governamentais; as atividades artísticas e culturais através do mecenato; a decisão sobre os rumos da pesquisa científica, o trabalho e suas teorias participativas, como a co-gestão, ideologia que procura encobrir novas práticas de exploração, incidindo sobre a criatividade social da classe trabalhadora; a questão do ser político do trabalhador que as políticas de Recursos Humanos das empresas querem subjugar e neutralizar, recorrendo à psicologia e à sociologia, que buscam reduzir o político ao psicológico.', '["capitalism","large corporations","labor exploitation","discipline","economic globalization","public policy","cultural patronage","science policy","participatory work","co-management","ideology","working class"]', '10.7476/9788539302840', '9788571395916', 'https://books.scielo.org/id/948hc', NULL, NULL, 'https://books.scielo.org/id/948hc/cover/cover_thumbnail.jpeg', 240, 28, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
